                accent: siteDetails.site_theme_accent || 'blue'
            },
            header_content: siteDetails.header_content || [],
            footer_content: siteDetails.footer_content || [],
            pages: validPages
        };
        const jsonSnapshot = JSON.stringify(snapshot);
        const [result] = await db.query(
            `UPDATE templates SET name = ?, description = ?, icon = ?, category = ?, thumbnail_url = ?, default_block_content = ? WHERE id = ? AND user_id = ?`,
            [templateName, description || '', icon || 'Layout', category || 'General', thumbnail_url || null, jsonSnapshot, id, userId]
        );
        if (result.affectedRows === 0) {
            return res.status(404).json({ message: 'Шаблон не знайдено або у вас немає прав.' });
        }
        res.json({ message: 'Шаблон та його структуру успішно оновлено!' });
    } catch (error) {
        console.error('Error in updateTemplate:', error);
        next(error);
    }
};

// backend/middleware/errorHandler.js
const multer = require('multer');
const errorHandler = (err, req, res, next) => {
    const isValidationError = (err instanceof multer.MulterError) || 
                              (err.message && err.message.includes('Непідтримуваний тип файлу'));
    if (!isValidationError) {
        console.error(err.stack);
    }
    if (err instanceof multer.MulterError) {
        if (err.code === 'LIMIT_FILE_SIZE') {
            return res.status(200).json({ error: true, message: 'Файл занадто великий. Глобальний ліміт сервера перевищено.' });
        }
        return res.status(200).json({ error: true, message: `Помилка завантаження: ${err.message}` });
    }
    if (err.message && err.message.includes('Непідтримуваний тип файлу')) {
        return res.status(200).json({ error: true, message: err.message });
    }
    let statusCode = res.statusCode ? res.statusCode : 500;
    if (statusCode === 200) statusCode = 500;
    res.status(statusCode);
    res.json({
        message: err.message,
        stack: process.env.NODE_ENV === 'production' ? null : err.stack,
    });
};

module.exports = errorHandler;

// backend/middleware/platformGuards.js
const db = require('../config/db');
let settingsCache = null;
let lastCacheTime = 0;
const CACHE_TTL = 30000;
const clearSettingsCache = () => {
    settingsCache = null;
    lastCacheTime = 0;
};

const getSettings = async () => {
    const now = Date.now();
    if (settingsCache && (now - lastCacheTime < CACHE_TTL)) {
        return settingsCache;
    }
    try {
        const [rows] = await db.query('SELECT * FROM global_settings WHERE id = 1');
        if (rows.length > 0) {
            settingsCache = rows[0];
            lastCacheTime = now;
            return rows[0];
        }
    } catch (err) {
        console.error('Error fetching platform settings:', err);
    }
    return { maintenance_mode: 0, editor_locked: 0, maintenance_message: null };
};
const checkMaintenance = async (req, res, next) => {
    if (req.path.startsWith('/api/auth') || req.path.startsWith('/auth')) {
        return next();
    }
    if (req.path.startsWith('/api/admin')) {
        return next();
    }
    const settings = await getSettings();
    let isAdmin = false;
    if (req.user) {
        if (req.user.role === 'admin') {
            isAdmin = true;
        }
    }
    const isLockedForUser = settings.editor_locked && !isAdmin;
    const isMaintenanceForUser = settings.maintenance_mode && !isAdmin;
    res.set('Access-Control-Expose-Headers', 'X-Editor-Locked, X-Maintenance-Mode, X-Global-Announcement');
    res.set('X-Editor-Locked', isLockedForUser ? 'true' : 'false');
    res.set('X-Maintenance-Mode', isMaintenanceForUser ? 'true' : 'false');
    if (settings.maintenance_message) {
        const encodedAnnouncement = Buffer.from(settings.maintenance_message).toString('base64');
        res.set('X-Global-Announcement', encodedAnnouncement);
    } else {
        res.set('X-Global-Announcement', '');
    }
    if (settings.maintenance_mode) {
        if (isAdmin) {
             req.platformSettings = settings;
             return next();
        }
        return res.status(503).json({
            message: "Платформа на технічному обслуговуванні. Ми скоро повернемося.",
            maintenance_mode: true,
            retry_after: 3600
        });
    }
    if (settings.editor_locked) {
        const isEditorRequest = 
            (req.method === 'POST' || req.method === 'PUT' || req.method === 'DELETE' || req.method === 'PATCH') &&
            (req.path.startsWith('/api/sites') || req.path.startsWith('/api/pages') || req.path.startsWith('/api/media') || req.path.startsWith('/api/upload'));

        if (isEditorRequest) {
            if (isAdmin) return next();

            return res.status(503).json({
                message: "Редактор тимчасово заблоковано для оновлення.",
                editor_locked: true
            });
        }
    }
    req.platformSettings = settings;
    next();
};

module.exports = { checkMaintenance, clearSettingsCache };

// backend/middleware/trackVisit.js
const crypto = require('crypto');
const db = require('../config/db');
const jwt = require('jsonwebtoken');

const trackVisit = async (req, res, next) => {
    try {
        const { site_path } = req.params;
        const [sites] = await db.query('SELECT id, user_id FROM sites WHERE site_path = ?', [site_path]);
        if (!sites.length) {
            return next();
        }

        const site = sites[0];
        const authHeader = req.headers['authorization'];
        if (authHeader) {
            const token = authHeader.split(' ')[1];
            try {
                if (token) {
                    const decoded = jwt.verify(token, process.env.JWT_SECRET);
                    if (decoded.id === site.user_id) {
                        return next(); 
                    }
                }
            } catch (e) { 
            }
        }

        const ip = req.ip || req.connection.remoteAddress;
        const ua = req.headers['user-agent'] || '';
        const visitorHash = crypto.createHash('sha256').update(ip + ua).digest('hex');
        const [existing] = await db.query(
            `SELECT id FROM site_visits 
             WHERE site_id = ? AND visitor_hash = ? 
             AND visited_at > NOW() - INTERVAL 24 HOUR`,
            [site.id, visitorHash]
        );

        if (existing.length === 0) {
            await db.query(
                `INSERT INTO site_visits (site_id, visitor_hash) VALUES (?, ?)`,
                [site.id, visitorHash]
            );
            
            await db.query(
                `UPDATE sites SET view_count = view_count + 1 WHERE id = ?`,
                [site.id]
            );
        }
        next();
    } catch (error) {
        console.error("Analytics Error:", error);
        next();
    }
};

module.exports = trackVisit;

// backend/middleware/upload.js
const multer = require('multer');
const { CloudinaryStorage } = require('multer-storage-cloudinary');
const cloudinary = require('../config/cloudinary');
const path = require('path');

const safeFileFilter = (req, file, cb) => {
    file.originalname = Buffer.from(file.originalname, 'latin1').toString('utf8');
    const ext = path.extname(file.originalname).toLowerCase();
    const allowedMimeTypes = [
        'image/jpeg', 'image/png', 'image/webp', 'image/gif', 'image/svg+xml',
        'video/mp4', 'video/webm', 'video/quicktime',
        'font/ttf', 'font/otf', 'font/woff', 'font/woff2',
        'application/font-woff', 'application/font-woff2', 'application/x-font-ttf', 'application/x-font-opentype'
    ];
    const allowedExtensions = ['.jpg', '.jpeg', '.png', '.webp', '.gif', '.svg', '.mp4', '.webm', '.mov', '.ttf', '.otf', '.woff', '.woff2'];
    const isValidMime = allowedMimeTypes.some(type => file.mimetype.includes(type) || file.mimetype === type);
    const isValidExt = allowedExtensions.includes(ext);
    if (!isValidMime && !isValidExt) {
        return cb(new Error('Непідтримуваний тип файлу. Дозволені лише зображення, відео та шрифти.'), false);
    }
    cb(null, true);
};

const mediaStorage = new CloudinaryStorage({
    cloudinary: cloudinary,
    params: async (req, file) => {
        const ext = path.extname(file.originalname).toLowerCase();
        const FONT_EXTENSIONS = ['.ttf', '.otf', '.woff', '.woff2'];
        const isFont = FONT_EXTENSIONS.includes(ext) || file.mimetype.includes('font');
        let resource_type = 'image';
        let format = 'webp';
        if (file.mimetype.startsWith('video/')) {
            resource_type = 'video';
            format = undefined; 
        } else if (isFont || file.mimetype.includes('svg')) {
            resource_type = 'raw';
            format = undefined;
        }
        return {
            folder: 'kendr/media',
            resource_type: resource_type,
            format: format,
            allowed_formats: isFont || resource_type !== 'image' ? undefined : ['jpg', 'jpeg', 'png', 'webp', 'gif'],
            transformation: resource_type === 'image' && format === 'webp' ? [{ quality: 'auto', fetch_format: 'auto' }] : []
        };
    }
});

const mediaUpload = multer({
    storage: mediaStorage,
    fileFilter: safeFileFilter,
    limits: { fileSize: 1024 * 1024 * 16, files: 10 }
});

const imageStorage = new CloudinaryStorage({
    cloudinary: cloudinary,
    params: {
        folder: 'kendr/general',
        format: async (req, file) => 'webp',
        allowed_formats: ['jpg', 'jpeg', 'png', 'webp', 'gif'],
        transformation: [{ quality: 'auto', fetch_format: 'auto' }]
    }
});

const upload = multer({
    storage: imageStorage,
    fileFilter: safeFileFilter,
    limits: { fileSize: 1024 * 1024 * 15 }
});

const ticketStorage = new CloudinaryStorage({
    cloudinary: cloudinary,
    params: {
        folder: 'kendr/tickets',
        format: async (req, file) => 'webp',
        allowed_formats: ['jpg', 'jpeg', 'png', 'webp'],
        transformation: [{ width: 1920, crop: 'limit', quality: '85' }]
    }
});

const ticketUpload = multer({
    storage: ticketStorage,
    fileFilter: safeFileFilter,
    limits: { fileSize: 5 * 1024 * 1024, files: 5 }
});

