// backend/middleware/verifyToken.js
const jwt = require('jsonwebtoken');
const db = require('../config/db');
const verifyToken = async (req, res, next) => {
    try {
        const authHeader = req.headers.authorization;
        if (!authHeader || !authHeader.startsWith('Bearer ')) {
            return res.status(401).json({ message: 'Відмовлено у доступі. Токен не надано.' });
        }
        const token = authHeader.split(' ')[1];
        const decoded = jwt.verify(token, process.env.JWT_SECRET || 'secret_key');
        const [users] = await db.query('SELECT token_version, status FROM users WHERE id = ?', [decoded.id]);
        const user = users[0];
        if (!user) {
            return res.status(401).json({ message: 'Користувача не знайдено.' });
        }
        if (user.status === 'suspended') {
             return res.status(403).json({ message: 'Доступ заблоковано. Ваш акаунт деактивовано.', code: 'ACCOUNT_SUSPENDED' });
        }
        if (user.status === 'deleted') {
            const isRestoreRoute = req.originalUrl.includes('/restore');
            const isMeRoute = req.originalUrl.match(/\/(auth|users)\/me/);
            if (!isRestoreRoute && !isMeRoute) {
                return res.status(403).json({ 
                    message: 'Акаунт видалено. Необхідно відновити.', 
                    code: 'ACCOUNT_DELETED' 
                });
            }
        }
        if (decoded.token_version !== undefined && user.token_version !== decoded.token_version) {
            return res.status(401).json({ message: 'Сесія застаріла через зміну пароля або налаштувань безпеки. Будь ласка, увійдіть знову.' });
        }
        req.user = decoded;
        next();
    } catch (error) {
        if (error.name === 'TokenExpiredError') {
            return res.status(401).json({ message: 'Час дії сесії минув. Будь ласка, увійдіть знову.' });
        }
        return res.status(401).json({ message: 'Недійсний токен авторизації.' });
    }
};

module.exports = verifyToken;

// backend/middleware/verifyTokenOptional.js
const jwt = require('jsonwebtoken');

function verifyTokenOptional(req, res, next) {
    const authHeader = req.headers['authorization'];
    const token = authHeader && authHeader.split(' ')[1];

    if (token == null) {
        req.user = null;
        return next();
    }

    jwt.verify(token, process.env.JWT_SECRET || 'secret_key', (err, user) => {
        if (err) {
            req.user = null;
        } else {
            req.user = user;
        }
        next();
    });
}

module.exports = verifyTokenOptional;

// backend/middleware/verifyTurnstile.js
const verifyTurnstile = async (req, res, next) => {
    if (req.hostname === 'localhost' || req.hostname === '127.0.0.1') {
        return next();
    }
    const token = req.body.turnstileToken;
    const secretKey = process.env.TURNSTILE_SECRET_KEY;
    if (!token) {
        return res.status(400).json({ message: 'Перевірка безпеки (Turnstile) обов\'язкова.' });
    }
    try {
        const response = await fetch('https://challenges.cloudflare.com/turnstile/v0/siteverify', {
            method: 'POST',
            headers: {
                'Content-Type': 'application/x-www-form-urlencoded',
            },
            body: `secret=${encodeURIComponent(secretKey)}&response=${encodeURIComponent(token)}&remoteip=${encodeURIComponent(req.ip)}`,
        });
        const data = await response.json();
        if (data.success) {
            next();
        } else {
            console.error('Turnstile verification failed:', data['error-codes']);
            return res.status(403).json({ message: 'Перевірка на робота не пройдена. Спробуйте ще раз.' });
        }
    } catch (error) {
        console.error('Turnstile Error:', error);
        return res.status(500).json({ message: 'Помилка сервера при перевірці безпеки.' });
    }
};

module.exports = verifyTurnstile;

// backend/models/Category.js
const db = require('../config/db');

class Category {
    static async findBySiteId(siteId) {
        try {
            const [rows] = await db.query(
                'SELECT * FROM categories WHERE site_id = ? ORDER BY name ASC',
                [siteId]
            );
            return rows;
        } catch (error) {
            throw new Error(`Помилка під час отримання категорій для сайту ${siteId}: ${error.message}`);
        }
    }

    static async findById(categoryId) {
        try {
            const [rows] = await db.query(
                `SELECT c.*, s.user_id 
                 FROM categories c
                 JOIN sites s ON c.site_id = s.id
                 WHERE c.id = ?`,
                [categoryId]
            );
            return rows[0] || null;
        } catch (error) {
            throw new Error(`Помилка під час пошуку категорії ${categoryId}: ${error.message}`);
        }
    }

    static async create(siteId, name, discount_percentage = 0, icon = 'folder') {
        try {
            if (!name || name.trim().length === 0) {
                throw new Error('Назва категорії не може бути порожньою.');
            }

            const [result] = await db.query(
                'INSERT INTO categories (site_id, name, discount_percentage, icon) VALUES (?, ?, ?, ?)',
                [siteId, name.trim(), discount_percentage, icon]
            );
            return { id: result.insertId, site_id: siteId, name: name.trim(), discount_percentage, icon };
        } catch (error) {
            if (error.code === 'ER_DUP_ENTRY') {
                throw new Error('Категорія з такою назвою вже існує для цього сайту.');
            }
            throw new Error(`Помилка під час створення категорії: ${error.message}`);
        }
    }

    static async update(categoryId, name, discount_percentage = 0, icon = 'folder') {
        try {
            if (!name || name.trim().length === 0) {
                throw new Error('Назва категорії не може бути порожньою.');
            }

            const [result] = await db.query(
                'UPDATE categories SET name = ?, discount_percentage = ?, icon = ? WHERE id = ?',
                [name.trim(), discount_percentage, icon, categoryId]
            );
            
            if (result.affectedRows === 0) {
                throw new Error('Категорію не знайдено.');
            }
            
            return result;
        } catch (error) {
            if (error.code === 'ER_DUP_ENTRY') {
                throw new Error('Категорія з такою назвою вже існує для цього сайту.');
            }
            throw new Error(`Помилка під час оновлення категорії: ${error.message}`);
        }
    }

    static async delete(categoryId) {
        try {
            const [result] = await db.query(
                'DELETE FROM categories WHERE id = ?',
                [categoryId]
            );
            
            if (result.affectedRows === 0) {
                throw new Error('Категорію не знайдено.');
            }
            
            return result;
        } catch (error) {
            throw new Error(`Помилка під час видалення категорії: ${error.message}`);
        }
    }
}

module.exports = Category;

