// backend/utils/encryption.js
const crypto = require('crypto');
const ENCRYPTION_KEY = process.env.ENCRYPTION_KEY; 
const ALGORITHM = 'aes-256-gcm';
if (!ENCRYPTION_KEY || ENCRYPTION_KEY.length !== 32) {
    console.error('КРИТИЧНА ПОМИЛКА: ENCRYPTION_KEY у .env має містити рівно 32 символи.');
    process.exit(1);
}

exports.encrypt = (text) => {
    if (!text) return text;
    try {
        const iv = crypto.randomBytes(16);
        const cipher = crypto.createCipheriv(ALGORITHM, Buffer.from(ENCRYPTION_KEY), iv);
        let encrypted = cipher.update(text, 'utf8', 'hex');
        encrypted += cipher.final('hex');
        const authTag = cipher.getAuthTag().toString('hex');
        return `${iv.toString('hex')}:${authTag}:${encrypted}`;
    } catch (error) {
        console.error('Помилка шифрування:', error);
        return null;
    }
};

exports.decrypt = (hash) => {
    if (!hash) return hash;
    const parts = hash.split(':');
    if (parts.length !== 3) {
        return hash; 
    }
    
    try {
        const iv = Buffer.from(parts[0], 'hex');
        const authTag = Buffer.from(parts[1], 'hex');
        const encryptedText = parts[2];
        const decipher = crypto.createDecipheriv(ALGORITHM, Buffer.from(ENCRYPTION_KEY), iv);
        decipher.setAuthTag(authTag);
        let decrypted = decipher.update(encryptedText, 'hex', 'utf8');
        decrypted += decipher.final('utf8');
        return decrypted;
    } catch (error) {
        console.error('Помилка розшифрування (невірний ключ або пошкоджені дані):', error);
        return null;
    }
};

// backend/utils/fileUtils.js
const fs = require('fs').promises;
const fsSync = require('fs');
const path = require('path');
const https = require('https');
const ensureDirExists = async (dirPath) => {
    try {
        await fs.mkdir(dirPath, { recursive: true });
    } catch (error) {
        console.error(`Помилка під час створення директорії ${dirPath}:`, error);
        throw error;
    }
};

const deleteFile = async (filePath) => {
    if (!filePath || filePath.includes('/default/')) {
        return;
    }
    const projectRoot = path.resolve(__dirname, '..'); 
    let fullPath;
    
    if (path.isAbsolute(filePath)) {
        fullPath = path.normalize(filePath);
    } else {
        const cleanPath = filePath.replace(/^[\/\\]+/, '');
        fullPath = path.join(projectRoot, cleanPath);
    }
    if (!fullPath.startsWith(projectRoot)) {
        console.warn(`[SECURITY WARNING] Блокирована попытка выхода за пределы директории (Path Traversal): ${filePath}`);
        return;
    }

    try {
        await fs.unlink(fullPath);
    } catch (error) {
        if (error.code !== 'ENOENT') {
            console.error(`Критическая ошибка при удалении файла ${fullPath}:`, error);
        }
    }
};

const downloadImage = (url, destPath) => {
    return new Promise((resolve, reject) => {
        const file = fsSync.createWriteStream(destPath);
        https.get(url, (response) => {
            if (response.statusCode !== 200) {
                return reject(new Error(`Failed to download image: status ${response.statusCode}`));
            }
            response.pipe(file);
            file.on('finish', () => {
                file.close(() => resolve(destPath));
            });
        }).on('error', (err) => {
            fsSync.unlink(destPath, () => {});
            reject(err);
        });
    });
};

module.exports = { ensureDirExists, deleteFile, downloadImage };

// backend/utils/sendServiceError.js
const { ServiceError } = require('../services/ServiceError');

const sendServiceError = (error, res, next) => {
    if (error instanceof ServiceError) {
        const body = error.extra ? { message: error.message, ...error.extra } : { message: error.message };
        return res.status(error.status).json(body);
    }
    return next(error);
};

module.exports = sendServiceError;

