// frontend/src/app/guards/ProtectedRoute.jsx
import React, { useContext, useEffect } from 'react';
import { Navigate, Outlet, useOutletContext } from 'react-router-dom';
import { AuthContext } from '../providers/AuthContext';

const ProtectedRoute = ({ 
    requireAdmin = false, 
    requireStrictAdmin = false,
    onlyPublic = false, 
    excludeAdmin = false 
}) => {
    const { user, isAdmin, isModerator, isLoading, logout } = useContext(AuthContext); 
    const outletContext = useOutletContext();
    if (isLoading) {
        return (
            <div style={{ 
                padding: '2rem', 
                textAlign: 'center', 
                color: 'var(--platform-text-secondary)' 
            }}>
                Перевірка доступу...
            </div>
        );
    }
    const isAnyAdmin = isAdmin || isModerator;
    if (user && user.status === 'deleted' && !onlyPublic) {
        setTimeout(() => {
            logout();
        }, 0);
        return <Navigate to="/login" replace />;
    }
    if (onlyPublic) {
        if (user && user.status !== 'deleted') {
            return isAnyAdmin ? <Navigate to="/admin" replace /> : <Navigate to="/" replace />;
        }
        return <Outlet context={outletContext} />;
    }

    if (!user) {
        return <Navigate to="/login" replace />;
    }

    if (requireStrictAdmin && !isAdmin) {
        return <Navigate to="/admin/dashboard" replace />;
    }

    if (requireAdmin && !isAnyAdmin) {
        return <Navigate to="/login" replace />;
    }

    if (excludeAdmin && isAnyAdmin) {
        return <Navigate to="/admin" replace />;
    }

    return <Outlet context={outletContext} />;
};

export default ProtectedRoute;

// frontend/src/app/providers/AuthContext.jsx
import React, { createContext, useState, useEffect, useCallback } from 'react';
import apiClient from '../../shared/api/api';

export const AuthContext = createContext(null);
export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [isLoading, setIsLoading] = useState(true);
  const [isRestorePending, setIsRestorePending] = useState(false);
  const logout = useCallback(() => {
    localStorage.removeItem('token');
    localStorage.removeItem('user');
    localStorage.removeItem('themeMode');
    localStorage.removeItem('themeAccent');
    localStorage.removeItem('isRestorePending');
    setIsRestorePending(false);
    setUser(null);
  }, []);
  useEffect(() => {
    const initAuth = async () => {
      try {
        const token = localStorage.getItem('token');
        const userDataRaw = localStorage.getItem('user');
        const restorePendingRaw = localStorage.getItem('isRestorePending');
        if (token && userDataRaw && userDataRaw !== 'undefined' && userDataRaw !== 'null') {
          const parsedUser = JSON.parse(userDataRaw);
          setUser(parsedUser);
          if (restorePendingRaw === 'true' || parsedUser.status === 'deleted') {
            setIsRestorePending(true);
          }
        } else {
          if (token || userDataRaw || restorePendingRaw) {
             localStorage.removeItem('token');
             localStorage.removeItem('user');
             localStorage.removeItem('themeMode');
             localStorage.removeItem('themeAccent');
             localStorage.removeItem('isRestorePending');
          }
        }
      } catch (error) {
        console.error("Помилка під час ініціалізації AuthContext:", error);
        localStorage.clear();
        setUser(null);
        setIsRestorePending(false);
      } finally {
        setIsLoading(false);
      }
    };
    
    initAuth();
    const handleUnauthorized = () => {
      logout();
    };
    
    window.addEventListener('auth_unauthorized', handleUnauthorized);
    return () => {
      window.removeEventListener('auth_unauthorized', handleUnauthorized);
    };
  }, [logout]);

  const login = (userData, token, requireRestore = false) => {
    if (!userData || !token) return;
    localStorage.setItem('token', token);
    localStorage.setItem('user', JSON.stringify(userData));
    const needsRestore = requireRestore || userData.status === 'deleted';
    if (needsRestore) {
        localStorage.setItem('isRestorePending', 'true');
        setIsRestorePending(true);
    } else {
        localStorage.removeItem('isRestorePending');
        setIsRestorePending(false);
    }
    
    setUser(userData);
  };

  const updateUser = (userData) => {
    if (!userData) return;
    try {
        localStorage.setItem('user', JSON.stringify(userData));
        setUser(userData);
    } catch (e) {
        console.error("Помилка при збереженні даних користувача", e);
    }
  };

  const restoreAccount = async () => {
    try {
        const response = await apiClient.post('/users/me/restore');
        login(response.data.user, response.data.token, false);
        return response.data;
    } catch (error) {
        console.error("Помилка відновлення акаунту:", error);
        throw error;
    }
  };

  const refreshUserToken = async () => {
    try {
        const response = await apiClient.post('/auth/refresh');
        if (response.data && response.data.token && response.data.user) {
            login(response.data.user, response.data.token, false);
            return response.data.user;
        }
    } catch (error) {
        console.error("Помилка оновлення токена:", error);
    }
  };

  return (
    <AuthContext.Provider value={{ 
      user, 
      isLoading, 
      isRestorePending,
      login, 
      logout, 
      updateUser, 
      restoreAccount,
      refreshUserToken,
      isAdmin: user?.role === 'admin',
      isModerator: user?.role === 'moderator',
      plan: user?.plan || 'FREE',
      isAuthenticated: !!user 
    }}>
      {children}
    </AuthContext.Provider>
  );
};

// frontend/src/app/providers/CartContext.jsx
import React, { createContext, useState, useEffect, useContext } from 'react';
import { AuthContext } from './AuthContext';
import { toast } from 'react-toastify';

export const CartContext = createContext(null);
export const CartProvider = ({ children }) => {
    const { user } = useContext(AuthContext);
    const [cartItems, setCartItems] = useState([]);
    const [isLoaded, setIsLoaded] = useState(false);
    const getCartKey = () => `cart_${user?.id || 'guest'}`;
    useEffect(() => {
        const cartKey = getCartKey();
        try {
            const localData = localStorage.getItem(cartKey);
            setCartItems(localData ? JSON.parse(localData) : []);
        } catch (error) {
            console.error(`Помилка парсингу кошика`, error);
            setCartItems([]);
        } finally {
            setIsLoaded(true);
        }
    }, [user]);
    const updateCart = (updater) => {
        setCartItems(prevItems => {
            const newItems = typeof updater === 'function' ? updater(prevItems) : updater;
            localStorage.setItem(getCartKey(), JSON.stringify(newItems));
            return newItems;
        });
    };

    const isDigitalOnly = cartItems.length > 0 && cartItems.every(item => item.type === 'digital');
    const addToCart = (product, selectedOptions = {}, priceInfo = null) => {
        const optionsString = JSON.stringify(selectedOptions, Object.keys(selectedOptions).sort());
        const cartItemId = `${product.id}-${optionsString}`;
        const finalPrice = priceInfo ? priceInfo.finalPrice : product.price;
        const originalPrice = priceInfo ? priceInfo.originalPrice : product.price;
        const discount = priceInfo ? priceInfo.discount : 0;
        updateCart(prevItems => {
            const existingItemIndex = prevItems.findIndex(item => item.cartItemId === cartItemId);
            if (existingItemIndex > -1) {
                const newItems = [...prevItems];
                newItems[existingItemIndex].quantity += 1;
                return newItems;
            } else {
                return [...prevItems, { 
                    ...product, 
                    cartItemId,
                    selectedOptions,
                    price: finalPrice,
                    originalPrice: originalPrice,
                    discountPercent: discount,
                    quantity: 1 
                }];
            }
        });
        toast.success(`"${product.name}" додано до кошика!`);
    };
    const removeFromCart = (cartItemId) => {
        updateCart(prevItems => prevItems.filter(item => item.cartItemId !== cartItemId));
        toast.info("Товар видалено з кошика");
    };
    const updateQuantity = (cartItemId, newQuantity) => {
        if (newQuantity <= 0) {
            removeFromCart(cartItemId);
        } else {
            updateCart(prevItems =>
                prevItems.map(item =>
                    item.cartItemId === cartItemId ? { ...item, quantity: newQuantity } : item
                )
            );
        }
    };
    const clearCart = () => {
        updateCart([]);
    };
    const clearCartBySite = (siteId) => {
        updateCart(prevItems => prevItems.filter(item => item.site_id !== siteId));
    };
    return (
        <CartContext.Provider value={{ 
            cartItems, 
            isDigitalOnly,
            isLoaded,
            addToCart, 
            removeFromCart, 
            clearCart, 
            clearCartBySite,
            updateQuantity 
        }}>
            {children}
        </CartContext.Provider>
    );
};

