                                            <AdminCell align="right" style={{overflow: 'visible'}}><Button variant="ghost" style={{padding: '6px'}}><Settings size={18} color="var(--platform-text-secondary)" /></Button></AdminCell>
                                        </AdminRow>
                                    );
                                })}
