                            <Button type="submit" disabled={isLoading || !formData.newPassword || !formData.confirmPassword} className="w-full py-3 sm:py-3.5">
                                {isLoading ? 'Збереження...' : 'Змінити пароль'}
                            </Button>
                        </form>
                    )}
