import Switch from '../../../shared/ui/elements/Switch';
import { Undo, Redo, Play, Edit, Palette, Settings, ShoppingBag, Monitor, Smartphone, PenTool, Eye, BarChart2, Save, RotateCcw, Loader2 } from 'lucide-react';

