// frontend/src/modules/dashboard/components/ProductPickerModal.jsx
import React, { useState, useEffect } from 'react';
import apiClient from '../../../shared/api/api';
import { toast } from 'react-toastify';
import CustomSelect from '../../../shared/ui/elements/CustomSelect';
import LoadingState from '../../../shared/ui/complex/LoadingState';
import { BASE_URL } from '../../../shared/config';
import { Search, X, Check, ArrowUp, ArrowDown, ArrowUpDown, Trash, Filter, PackageOpen, Image } from 'lucide-react';

const ProductPickerModal = ({ isOpen, onClose, onSave, initialSelectedIds = [], siteId }) => {
    const [products, setProducts] = useState([]);
    const [categories, setCategories] = useState([]);
    const [selectedIds, setSelectedIds] = useState(new Set(initialSelectedIds));
    const [searchTerm, setSearchTerm] = useState('');
    const [selectedCategory, setSelectedCategory] = useState('all');
    const [sortBy, setSortBy] = useState('name');
    const [sortOrder, setSortOrder] = useState('asc');
    const [loading, setLoading] = useState(false);
    useEffect(() => {
        if (isOpen && siteId) {
            setLoading(true);
            Promise.all([
                apiClient.get(`/products/site/${siteId}`),
                apiClient.get(`/categories/site/${siteId}`)
            ])
            .then(([productsRes, categoriesRes]) => {
                setProducts(productsRes.data);
                setCategories(categoriesRes.data);
            })
            .catch(err => toast.error('Помилка завантаження даних'))
            .finally(() => setLoading(false));
            
            setSelectedIds(new Set(initialSelectedIds));
        }
    }, [isOpen, siteId, initialSelectedIds]);

    const toggleProduct = (id) => {
        const newSelected = new Set(selectedIds);
        if (newSelected.has(id)) {
            newSelected.delete(id);
        } else {
            if (newSelected.size >= 20) {
                toast.error('Максимум 20 товарів');
                return;
            }
            newSelected.add(id);
        }
        setSelectedIds(newSelected);
    };

    const handleSave = () => {
        onSave(Array.from(selectedIds));
        onClose();
    };

    const clearSelection = () => {
        setSelectedIds(new Set());
    };

    const selectAllFiltered = () => {
        const newSelected = new Set(selectedIds);
        let addedCount = 0;
        const limit = 20;
        if (newSelected.size >= limit) {
            toast.warning('Ліміт у 20 товарів вже досягнуто');
            return;
        }
        for (const p of filteredProducts) {
            if (!newSelected.has(p.id)) {
                if (newSelected.size < limit) {
                    newSelected.add(p.id);
                    addedCount++;
                } else {
                    toast.warning(`Додано ${addedCount} товарів. Досягнуто ліміт 20.`);
                    break;
                }
            }
        }
        if (addedCount > 0) {
            setSelectedIds(newSelected);
            toast.success(`Додано ${addedCount} товарів`);
        } else if (newSelected.size < limit) {
            toast.info('Всі доступні товари вже обрані');
        }
    };

    const clearSearch = () => {
        setSearchTerm('');
    };

    const toggleSort = (field) => {
        if (sortBy === field) {
            setSortOrder(sortOrder === 'asc' ? 'desc' : 'asc');
        } else {
            setSortBy(field);
            setSortOrder('asc');
        }
    };

    const getSortIcon = (field) => {
        if (sortBy !== field) return <ArrowUpDown size={14} />;
        return sortOrder === 'asc' ? <ArrowUp size={14} /> : <ArrowDown size={14} />;
    };

    const filteredProducts = products.filter(p => {
        const matchesSearch = p.name.toLowerCase().includes(searchTerm.toLowerCase());
        const matchesCategory = selectedCategory === 'all' || p.category_id == selectedCategory;
        return matchesSearch && matchesCategory;
    });

    const sortedProducts = [...filteredProducts].sort((a, b) => {
        let aValue, bValue;
        if (sortBy === 'name') {
            aValue = a.name.toLowerCase();
            bValue = b.name.toLowerCase();
            const aIsCyrillic = /[а-яіїєґ]/.test(aValue);
            const bIsCyrillic = /[а-яіїєґ]/.test(bValue);
            if (aIsCyrillic && !bIsCyrillic) return 1;
            if (!aIsCyrillic && bIsCyrillic) return -1;
        } else if (sortBy === 'price') {
            aValue = a.price || 0;
            bValue = b.price || 0;
        }
        if (aValue < bValue) return sortOrder === 'asc' ? -1 : 1;
        if (aValue > bValue) return sortOrder === 'asc' ? 1 : -1;
        return 0;
    });
    if (!isOpen) return null;
    const overlayStyle = {
        position: 'fixed', top: 0, left: 0, right: 0, bottom: 0,
        background: 'rgba(0,0,0,0.6)', zIndex: 30000,
        display: 'flex', alignItems: 'center', justifyContent: 'center',
        padding: '1rem', backdropFilter: 'blur(4px)'
    };

    const modalStyle = {
        background: 'var(--platform-card-bg)', 
        width: '900px', 
        maxWidth: '95%', 
        height: '650px',
        maxHeight: '90vh',
        borderRadius: '16px', 
        display: 'flex', 
        flexDirection: 'column',
        boxShadow: '0 20px 60px rgba(0,0,0,0.2)', 
        border: '1px solid var(--platform-border-color)',
        overflow: 'hidden'
    };

    const headerStyle = {
        padding: '1.2rem 1.5rem', 
        borderBottom: '1px solid var(--platform-border-color)',
        display: 'flex', 
        justifyContent: 'space-between', 
        alignItems: 'center',
        background: 'var(--platform-bg)'
    };

    const toolbarStyle = {
        padding: '1rem 1.5rem',
        borderBottom: '1px solid var(--platform-border-color)',
        display: 'flex',
        flexWrap: 'wrap',
        gap: '12px',
        alignItems: 'center',
        background: 'var(--platform-card-bg)'
    };

    const searchContainerStyle = {
        position: 'relative',
        flex: '2 1 250px',
        minWidth: '200px'
    };

    const selectWrapperStyle = {
        flex: '1 1 200px',
        minWidth: '180px'
    };

    const inputStyle = {
        padding: '10px 36px 10px 36px', 
        borderRadius: '8px', 
        border: '1px solid var(--platform-border-color)',
        background: 'var(--platform-input-bg)', 
        color: 'var(--platform-text-primary)', 
        fontSize: '0.9rem', width: '100%',
        transition: 'border-color 0.2s',
        boxSizing: 'border-box',
        outline: 'none'
