});

const CategoryManager = ({ siteId, onSavingChange, maxCategories }) => {
    const [search, setSearch] = useState('');
    const [sortBy, setSortBy] = useState('name');
    const [sortOrder, setSortOrder] = useState('asc');
    const [searchParams, setSearchParams] = useSearchParams();
    const { confirm } = useConfirm();
    const [isPanelOpen, setIsPanelOpen] = useState(true);
    const [activeCategory, setActiveCategory] = useState(null);
    const [formData, setFormData] = useState({ id: null, name: '', icon: 'folder' });
    const { categories, products, loading, fetchData, setCategories } = useCategories(siteId);
    useEffect(() => {
        const catIdFromUrl = searchParams.get('categoryId');
        if (!loading) {
            if (catIdFromUrl === 'new') {
                setActiveCategory(null);
                setFormData({ id: null, name: '', icon: 'folder' });
                setIsPanelOpen(true);
            } else if (catIdFromUrl && categories.length > 0) {
                const catToEdit = categories.find(c => c.id.toString() === catIdFromUrl);
                if (catToEdit) {
                    setActiveCategory(catToEdit);
                    setFormData({
                        id: catToEdit.id,
                        name: catToEdit.name,
                        icon: catToEdit.icon || 'folder'
                    });
                    setIsPanelOpen(true);
                }
            } else if (!catIdFromUrl && isPanelOpen && activeCategory) {
                 setActiveCategory(null);
                 setFormData({ id: null, name: '', icon: 'folder' });
            }
        }
    }, [loading, categories, searchParams]);

    const handleSelectCategory = useCallback((category) => {
        if (activeCategory && activeCategory.id === category.id) {
            setActiveCategory(null);
            setFormData({ id: null, name: '', icon: 'folder' });
            setSearchParams(prev => { prev.delete('categoryId'); return prev; });
            if (window.innerWidth < 1100) setIsPanelOpen(false);
        } else {
            setActiveCategory(category);
            setFormData({ id: category.id, name: category.name, icon: category.icon || 'folder' });
            setIsPanelOpen(true);
            setSearchParams(prev => { prev.set('categoryId', category.id); return prev; });
        }
    }, [activeCategory, setSearchParams]);

    const handleCreateNew = useCallback(() => {
        if (maxCategories !== Infinity && categories.length >= maxCategories) {
            toast.warning(`Досягнуто ліміт категорій (${maxCategories}) для вашого тарифу.`);
            return;
        }
        setActiveCategory(null);
        setFormData({ id: null, name: '', icon: 'folder' });
        setIsPanelOpen(true);
        setSearchParams(prev => { prev.set('categoryId', 'new'); return prev; });
    }, [categories.length, maxCategories, setSearchParams]);

    const handleClear = useCallback(() => {
        setActiveCategory(null);
        setFormData({ id: null, name: '', icon: 'folder' });
        setSearchParams(prev => { prev.delete('categoryId'); return prev; });
        if (window.innerWidth < 1100) setIsPanelOpen(false);
    }, [setSearchParams]);
    
    const handleClosePanel = useCallback(() => {
        setIsPanelOpen(false);
        setSearchParams(prev => { prev.delete('categoryId'); return prev; });
    }, [setSearchParams]);

    const handleSubmit = useCallback(async (e) => {
        e.preventDefault();
        const trimmedName = formData.name.trim();
        if (!trimmedName) {
            toast.warning("Введіть назву категорії");
            return;
        }
        if (!formData.id && maxCategories !== Infinity && categories.length >= maxCategories) {
            toast.error(`Досягнуто ліміт категорій (${maxCategories}) для вашого тарифу.`);
            return;
        }
        const isDuplicate = categories.some(cat =>
            cat.name.toLowerCase() === trimmedName.toLowerCase() &&
            cat.id !== formData.id
        );
        if (isDuplicate) {
            toast.error('Категорія з такою назвою вже існує!');
            return;
        }
        if (onSavingChange) onSavingChange(true);
        try {
            const payload = { siteId, name: trimmedName, icon: formData.icon };
            if (formData.id) {
                await apiClient.put(`/categories/${formData.id}`, payload);
                toast.success('Категорію оновлено');
            } else {
                await apiClient.post('/categories', payload);
                toast.success('Категорію додано');
            }
            fetchData();
            if (!formData.id) handleClear();
        } catch (e) {
            console.error(e);
            toast.error(e.response?.data?.message || 'Помилка збереження');
        } finally {
            if (onSavingChange) onSavingChange(false);
        }
    }, [formData, categories, maxCategories, onSavingChange, siteId, fetchData, handleClear]);

    const handleDelete = useCallback(async (e, id, name) => {
        e.stopPropagation();
        if (await confirm({ title: 'Видалити категорію?', message: `Ви впевнені, що хочете видалити категорію "${name}"?`, type: 'danger', confirmLabel: 'Видалити' })) {
            if (onSavingChange) onSavingChange(true);
            try {
                await apiClient.delete(`/categories/${id}`);
                if (activeCategory?.id === id) handleCreateNew();
                fetchData();
                toast.success('Категорію видалено');
            } catch (err) { 
                toast.error('Не вдалося видалити'); 
            } finally { 
                if (onSavingChange) onSavingChange(false); 
            }
        }
    }, [confirm, onSavingChange, activeCategory, handleCreateNew, fetchData]);
    
    if (loading) return <LoadingState title="Завантаження категорій..." />;
    return (
        <SplitViewLayout 
            isOpen={isPanelOpen}
            onToggle={setIsPanelOpen}
            sidebar={
                <CategoryList 
                    categories={categories}
                    products={products}
                    search={search}
                    setSearch={setSearch}
                    sortBy={sortBy}
                    setSortBy={setSortBy}
                    sortOrder={sortOrder}
                    setSortOrder={setSortOrder}
                    activeCategoryId={activeCategory?.id}
                    onSelect={handleSelectCategory}
                    onCreate={handleCreateNew}
                    onDelete={handleDelete}
                    maxCategories={maxCategories}
                />
            }
            content={
                <CategoryEditor 
                    formData={formData}
                    setFormData={setFormData}
                    onSubmit={handleSubmit}
                    onClear={handleClear}
                    onClose={handleClosePanel}
                    onSavingChange={onSavingChange}
                    isMobile={window.innerWidth < 1100}
                />
            }
            sidebarWidth="380px"
        />
    );
};

export default CategoryManager;

// frontend/src/modules/dashboard/features/commerce/components/CommerceSettingsTab.jsx
import React, { useState, useEffect } from 'react';
import { Button, Input, Switch } from '../../../../../shared/ui/elements';
import CustomSelect from '../../../../../shared/ui/elements/CustomSelect';
import apiClient from '../../../../../shared/api/api';
import { toast } from 'react-toastify';
import { CreditCard, Key, Lock, AlertCircle, Banknote, Wallet, Info } from 'lucide-react';

const CURRENCY_OPTIONS = [
    { value: 'UAH', label: 'Гривня – ₴', icon: Banknote },
    { value: 'USD', label: 'Долар – $', icon: Banknote },
    { value: 'EUR', label: 'Євро – €', icon: Banknote }
];

const CommerceSettingsTab = ({ siteData, onSavingChange }) => {
    const [currency, setCurrency] = useState(siteData?.currency || 'UAH');
    const [localPayment, setLocalPayment] = useState({
        public: siteData?.liqpay_public_key || '',
        private: siteData?.liqpay_private_key || '',
        isOnlineEnabled: siteData?.is_online_payment_enabled ?? true,
        isCodEnabled: siteData?.is_cod_enabled ?? true
    });
    const [savedPayment, setSavedPayment] = useState({
        public: siteData?.liqpay_public_key || '',
        private: siteData?.liqpay_private_key || '',
        isOnlineEnabled: siteData?.is_online_payment_enabled ?? true,
        isCodEnabled: siteData?.is_cod_enabled ?? true
    });

    useEffect(() => {
        const newData = {
            public: siteData?.liqpay_public_key || '',
            private: siteData?.liqpay_private_key || '',
            isOnlineEnabled: siteData?.is_online_payment_enabled ?? true,
            isCodEnabled: siteData?.is_cod_enabled ?? true
        };
        setLocalPayment(newData);
        setSavedPayment(newData);
    }, [siteData]);

    const handleCurrencyChange = async (e) => {
        const newCurrency = e.target.value;
        setCurrency(newCurrency);
        onSavingChange(true);
        try {
            await apiClient.put(`/sites/${siteData.site_path}/settings`, { currency: newCurrency });
            toast.success("Валюту магазину оновлено!");
        } catch (error) {
            console.error(error);
            toast.error("Не вдалося оновити валюту.");
            setCurrency(siteData.currency || 'UAH');
        } finally {
            onSavingChange(false);
        }
    };

    const handlePaymentToggle = (field) => {
        setLocalPayment(prev => {
            const newState = { ...prev, [field]: !prev[field] };
            if (!newState.isOnlineEnabled && !newState.isCodEnabled) {
                toast.warning('Має бути увімкнений хоча б один спосіб оплати!');
                return prev;
            }
            return newState;
        });
    };

    const handlePaymentSave = async () => {
        onSavingChange(true);
        try {
            await apiClient.put(`/sites/${siteData.site_path}/settings`, {
                liqpay_public_key: localPayment.public,
                liqpay_private_key: localPayment.private,
                is_online_payment_enabled: localPayment.isOnlineEnabled ? 1 : 0,
                is_cod_enabled: localPayment.isCodEnabled ? 1 : 0
            });
            setSavedPayment({ ...localPayment });
            toast.success('Налаштування оплати успішно збережено!');
        } catch (error) {
            console.error(error);
            toast.error('Не вдалося зберегти налаштування оплати.');
        } finally {
            onSavingChange(false);
        }
    };

    const isPaymentDirty = 
        localPayment.public !== savedPayment.public || 
        localPayment.private !== savedPayment.private ||
        localPayment.isOnlineEnabled !== savedPayment.isOnlineEnabled ||
        localPayment.isCodEnabled !== savedPayment.isCodEnabled;

    return (
        <div className="h-full overflow-y-auto custom-scrollbar p-1 flex flex-col gap-6">
            <div className="bg-(--platform-card-bg) rounded-2xl border border-(--platform-border-color) p-8 shadow-sm w-full max-w-3xl mx-auto">
                <div className="mb-6 flex items-center justify-between gap-3">
                    <div>
                        <h3 className="text-xl font-semibold text-(--platform-text-primary) m-0 mb-1 flex items-center gap-2.5">
                            <Banknote size={22} className="text-(--platform-accent)" /> Валюта магазину
                        </h3>
                        <p className="text-sm text-(--platform-text-secondary) m-0 leading-relaxed">
                            Оберіть основну валюту, в якій будуть відображатися ціни на товари та суми замовлень.
                        </p>
                    </div>
                </div>
                <div className="max-w-xs mx-auto">
                    <label className="block mb-2 font-medium text-(--platform-text-primary) text-sm text-center w-full">
                        Поточна валюта
                    </label>
                    <CustomSelect 
                        value={currency} 
                        onChange={handleCurrencyChange}
                        options={CURRENCY_OPTIONS}
                    />
                </div>
            </div>
            <div className="bg-(--platform-card-bg) rounded-2xl border border-(--platform-border-color) p-8 shadow-sm w-full max-w-3xl mx-auto">
                <div className="mb-6 flex items-center justify-between gap-3">
                    <div>
                        <h3 className="text-xl font-semibold text-(--platform-text-primary) m-0 mb-1 flex items-center gap-2.5">
                            <CreditCard size={22} className="text-(--platform-accent)" /> Варіанти оплати
                        </h3>
                        <p className="text-sm text-(--platform-text-secondary) m-0 leading-relaxed">
                            Налаштуйте, як клієнти зможуть розраховуватися за ваші товари.
                        </p>
                    </div>
                </div>
                <div className="flex flex-col gap-6 max-w-xl mx-auto w-full">
                    <div className="flex items-center justify-between p-4 rounded-xl border border-(--platform-border-color) bg-(--platform-bg)">
                        <div className="flex items-center gap-3">
                            <div className="p-2 bg-amber-500/10 text-amber-500 rounded-lg">
                                <Wallet size={20} />
                            </div>
                            <div>
                                <h4 className="font-semibold text-(--platform-text-primary) text-sm m-0">Оплата при отриманні</h4>
                                <p className="text-xs text-(--platform-text-secondary) m-0 mt-0.5">Клієнт платить на пошті (Накладений платіж).</p>
                            </div>
                        </div>
                        <Switch 
                            checked={localPayment.isCodEnabled} 
                            onChange={() => handlePaymentToggle('isCodEnabled')} 
                        />
                    </div>
                    <div className={`flex flex-col rounded-xl border transition-colors ${localPayment.isOnlineEnabled ? 'border-blue-500/30 bg-blue-500/5' : 'border-(--platform-border-color) bg-(--platform-bg)'}`}>
                        <div className="flex items-center justify-between p-4">
                            <div className="flex items-center gap-3">
                                <div className={`p-2 rounded-lg ${localPayment.isOnlineEnabled ? 'bg-blue-500/10 text-blue-500' : 'bg-(--platform-border-color) text-(--platform-text-secondary)'}`}>
                                    <CreditCard size={20} />
                                </div>
                                <div>
                                    <h4 className="font-semibold text-(--platform-text-primary) text-sm m-0">Онлайн оплата (Картка / GPay)</h4>
                                    <p className="text-xs text-(--platform-text-secondary) m-0 mt-0.5">
                                        Прийом платежів через LiqPay та Google Pay на сайті.
                                    </p>
                                </div>
                            </div>
                            <Switch 
                                checked={localPayment.isOnlineEnabled} 
                                onChange={() => handlePaymentToggle('isOnlineEnabled')} 
                            />
                        </div>
                        {localPayment.isOnlineEnabled && (
                            <div className="p-4 border-t border-blue-500/20 flex flex-col gap-4 bg-(--platform-bg) rounded-b-xl">
                                <div>
                                    <Input
                                        label="LiqPay Public Key"
                                        value={localPayment.public}
                                        onChange={(e) => setLocalPayment(prev => ({ ...prev, public: e.target.value }))}
                                        placeholder="sandbox_..."
                                        leftIcon={<Key size={16}/>}
                                    />
                                </div>
                                <div>
                                    <Input
                                        label="LiqPay Private Key"
                                        value={localPayment.private}
                                        onChange={(e) => setLocalPayment(prev => ({ ...prev, private: e.target.value }))}
                                        placeholder="sandbox_..."
                                        leftIcon={<Lock size={16}/>}
                                        type="password"
                                    />
                                </div>
                                
                                {(!savedPayment.public || !savedPayment.private) && (
                                    <div className="mt-2 p-3 bg-red-500/10 border border-red-500/20 rounded-lg text-sm text-red-500 flex gap-2 items-center justify-center text-center">
                                        <AlertCircle size={16} className="shrink-0" />
                                        <span>Ключі не налаштовані. Онлайн оплата не працюватиме.</span>
                                    </div>
                                )}
                            </div>
                        )}
                    </div>
                </div>
                <div className="flex justify-center mt-6">
                    <Button 
                        type="button" 
                        onClick={handlePaymentSave}
                        disabled={!isPaymentDirty}
                        className="px-8"
                    >
                        Зберегти налаштування оплати
                    </Button>
                </div>
            </div>
            
        </div>
    );
};

export default CommerceSettingsTab;

// frontend/src/modules/dashboard/features/commerce/components/OrdersTab.jsx
import React, { useState, useEffect, useMemo } from 'react';
import apiClient from '../../../../../shared/api/api';
import { toast } from 'react-toastify';
import CustomSelect from '../../../../../shared/ui/elements/CustomSelect';
import { Input } from '../../../../../shared/ui/elements/Input';
import { Button } from '../../../../../shared/ui/elements/Button';
import DateRangePicker from '../../../../../shared/ui/elements/DateRangePicker';
import EmptyState from '../../../../../shared/ui/complex/EmptyState';
import LoadingState from '../../../../../shared/ui/complex/LoadingState';
import { Package, MapPin, User, Calendar, Search, CreditCard, Wallet } from 'lucide-react';

const STATUS_MAP = {
    'pending': { label: 'Очікує оплати', color: 'bg-amber-500/10 text-amber-600 border-amber-500/20 dark:text-amber-500' },
    'paid': { label: 'Оплачено (В обробці)', color: 'bg-blue-500/10 text-blue-600 border-blue-500/20 dark:text-blue-500' },
    'shipped': { label: 'Відправлено', color: 'bg-purple-500/10 text-purple-600 border-purple-500/20 dark:text-purple-500' },
    'completed': { label: 'Виконано', color: 'bg-emerald-500/10 text-emerald-600 border-emerald-500/20 dark:text-emerald-500' },
    'cancelled': { label: 'Скасовано', color: 'bg-red-500/10 text-red-600 border-red-500/20 dark:text-red-500' }
};

const PAYMENT_METHOD_MAP = {
    online: { label: 'Оплата картою (LiqPay)', icon: CreditCard, color: 'text-blue-600 dark:text-blue-400' },
    cod: { label: 'Оплата при отриманні', icon: Wallet, color: 'text-amber-600 dark:text-amber-500' }
};

const STATUS_OPTIONS = Object.entries(STATUS_MAP)
    .filter(([key]) => key !== 'pending')
    .map(([key, val]) => ({
        value: key,
        label: val.label
    }));

const FILTER_STATUS_OPTIONS = [
    { value: 'all', label: 'Всі статуси' },
    ...Object.entries(STATUS_MAP).map(([key, val]) => ({
        value: key,
        label: val.label
    }))
];

const FILTER_TYPE_OPTIONS = [
    { value: 'all', label: 'Всі типи' },
    { value: 'digital', label: 'Тільки цифрові' },
    { value: 'physical', label: 'Містять фізичні' }
];

const SORT_FIELDS = [
    { value: 'date', label: 'За датою' },
    { value: 'amount', label: 'За сумою' },
    { value: 'id', label: 'За номером' }
];

const OrdersTab = ({ site, siteData }) => {
    const currentSite = site || siteData;
    const [orders, setOrders] = useState([]);
    const [loading, setLoading] = useState(true);
    const [search, setSearch] = useState('');
    const [statusFilter, setStatusFilter] = useState('all');
    const [typeFilter, setTypeFilter] = useState('all');
    const [sortBy, setSortBy] = useState('date');
    const [sortOrder, setSortOrder] = useState('desc');
    const [startDate, setStartDate] = useState('');
    const [endDate, setEndDate] = useState('');
    const currencyMap = { 'UAH': '₴', 'USD': '$', 'EUR': '€' };
    const siteCurrency = currentSite?.currency || 'UAH';
    const currencySymbol = currencyMap[siteCurrency] || '₴';
    useEffect(() => {
        if (!currentSite?.id) {
            setLoading(false);
            return;
        }
        const fetchOrders = async () => {
            setLoading(true);
            try {
                const res = await apiClient.get(`/orders/site/${currentSite.id}`);
                setOrders(res.data || []);
            } catch (err) {
                console.error(err);
                toast.error('Не вдалося завантажити замовлення');
            } finally {
                setLoading(false);
            }
        };
        fetchOrders();
    }, [currentSite]);

    const handleStatusChange = async (orderId, newStatus) => {
        try {
            await apiClient.put(`/orders/${orderId}/status`, { status: newStatus });
            setOrders(prev => prev.map(o => o.id === orderId ? { ...o, status: newStatus } : o));
            toast.success('Статус замовлення оновлено');
        } catch (error) {
            console.error('Помилка оновлення статусу:', error);
            toast.error('Не вдалося оновити статус');
        }
    };

    const formatDate = (dateString) => {
        const date = new Date(dateString);
        const day = String(date.getDate()).padStart(2, '0');
        const month = String(date.getMonth() + 1).padStart(2, '0');
        const year = date.getFullYear();
        const hours = String(date.getHours()).padStart(2, '0');
        const minutes = String(date.getMinutes()).padStart(2, '0');
        return `${day}.${month}.${year} о ${hours}:${minutes}`;
    };

    const clearFilters = () => {
        search && setSearch('');
        statusFilter !== 'all' && setStatusFilter('all');
        typeFilter !== 'all' && setTypeFilter('all');
        startDate && setStartDate('');
        endDate && setEndDate('');
    };

    const getStatusControl = (order) => {
        const hasItems = order.items && order.items.length > 0;
        const isDigitalOnly = hasItems && order.items.every(item => item.type === 'digital');
        const isDisabled = (order.status === 'pending' && order.payment_method === 'online') || isDigitalOnly;
        let config = STATUS_MAP[order.status] || STATUS_MAP['pending'];
        if (order.status === 'pending' && order.payment_method === 'cod') {
            config = { label: 'Нове замовлення (Наложка)', color: 'bg-blue-500/10 text-blue-600 border-blue-500/20' };
        }

        if (isDisabled) {
            return (
                <span className={`px-3 py-1.5 rounded-lg text-xs font-bold border flex items-center gap-1.5 ${config.color} shadow-sm`}>
                    {config.label}
                    {isDigitalOnly && order.status !== 'pending' && order.status !== 'cancelled' && (
                        <span className="opacity-75 text-[10px] uppercase tracking-wider bg-black/5 dark:bg-white/10 px-1.5 rounded">(Авто)</span>
                    )}
                </span>
            );
        }
        return (
            <div className="w-56">
                <CustomSelect
                    name="status"
                    value={order.status}
                    onChange={(e) => handleStatusChange(order.id, e.target.value)}
                    options={order.status === 'pending' ? [{ value: 'pending', label: 'Нове замовлення' }, ...STATUS_OPTIONS] : STATUS_OPTIONS}
                />
            </div>
        );
    };

    const processedOrders = useMemo(() => {
        let result = [...orders];
        if (search.trim()) {
            const query = search.toLowerCase();
            result = result.filter(o =>
                o.id.toString().toLowerCase().includes(query) ||
                (o.customer_name || '').toLowerCase().includes(query) ||
                (o.customer_email || '').toLowerCase().includes(query) ||
                (o.customer_phone || '').includes(query)
            );
        }
        if (statusFilter !== 'all') {
            result = result.filter(o => o.status === statusFilter);
        }
        if (typeFilter === 'digital') {
            result = result.filter(o => o.items && o.items.length > 0 && o.items.every(item => item.type === 'digital'));
        } else if (typeFilter === 'physical') {
            result = result.filter(o => o.items && o.items.some(item => item.type !== 'digital'));
        }
        if (startDate) {
            const start = new Date(`${startDate}T00:00:00`);
            result = result.filter(o => new Date(o.created_at) >= start);
        }
        if (endDate) {
            const end = new Date(`${endDate}T23:59:59`);
            result = result.filter(o => new Date(o.created_at) <= end);
        }
        result.sort((a, b) => {
            let comparison = 0;
            if (sortBy === 'date') {
                comparison = new Date(a.created_at) - new Date(b.created_at);
            } else if (sortBy === 'amount') {
                comparison = parseFloat(a.total_amount) - parseFloat(b.total_amount);
            } else if (sortBy === 'id') {
                comparison = a.id.toString().localeCompare(b.id.toString());
            }
            return sortOrder === 'asc' ? comparison : comparison * -1;
        });
        return result;
    }, [orders, search, statusFilter, typeFilter, startDate, endDate, sortBy, sortOrder]);

    const toggleSortOrder = () => {
        setSortOrder(prev => prev === 'asc' ? 'desc' : 'asc');
    };

    if (loading) {
        return <LoadingState title="Завантаження замовлень..." />;
    }

    const hasActiveFilters = search || statusFilter !== 'all' || typeFilter !== 'all' || startDate || endDate;
    return (
        <div className="flex flex-col h-full bg-(--platform-card-bg) rounded-2xl border border-(--platform-border-color) overflow-hidden">
            <div className="min-h-18 p-3 sm:px-5 border-b border-(--platform-border-color) flex justify-between items-center gap-3 flex-wrap bg-(--platform-bg) shrink-0">
                <div className="flex gap-2 flex-1 items-center flex-wrap">
                    <Input
                        leftIcon={<Search size={16} />}
                        placeholder="Пошук..."
                        value={search}
                        onChange={(e) => setSearch(e.target.value)}
                        wrapperStyle={{ margin: 0, flex: '1 1 180px' }}
                    />
                    <DateRangePicker 
                        startDate={startDate}
                        endDate={endDate}
                        onStartDateChange={setStartDate}
                        onEndDateChange={setEndDate}
                        onClear={() => {setStartDate(''); setEndDate('');}}
                    />
                    <div className="w-44">
                        <CustomSelect
                            value={statusFilter}
                            onChange={(e) => setStatusFilter(e.target.value)}
                            options={FILTER_STATUS_OPTIONS}
                        />
                    </div>
                    <div className="w-44">
                        <CustomSelect
                            value={typeFilter}
                            onChange={(e) => setTypeFilter(e.target.value)}
                            options={FILTER_TYPE_OPTIONS}
                        />
                    </div>
                    <div className="flex gap-1 items-center">
                        <div className="w-40">
                            <CustomSelect
                                value={sortBy}
                                onChange={(e) => setSortBy(e.target.value)}
                                options={SORT_FIELDS}
                            />
                        </div>
                        <Button 
                            variant="outline" 
                            onClick={toggleSortOrder} 
                            className="w-10.5 h-10.5 p-0 flex items-center justify-center shrink-0"
                            title={sortOrder === 'desc' ? "За спаданням" : "За зростанням"}
                        >
                            <span className="text-lg leading-none">{sortOrder === 'desc' ? '↓' : '↑'}</span>
                        </Button>
                    </div>
                </div>
            </div>
            <div className="flex-1 overflow-y-auto p-5 custom-scrollbar">
                {processedOrders.length === 0 ? (
                    <div className="flex flex-col items-center justify-center h-full py-10">
                        <EmptyState 
                            title={orders.length === 0 ? "Замовлень поки немає" : "Замовлень не знайдено"}
                            description={
                                orders.length === 0 
                                ? "Коли клієнти зроблять покупку, вони з'являться тут." 
                                : "За вашим запитом або фільтрами нічого не знайдено. Спробуйте змінити критерії пошуку."
                            }
                            icon={orders.length === 0 ? Package : Search}
                            action={
                                hasActiveFilters && (
                                    <Button variant="ghost" onClick={clearFilters}>
                                        Очистити фільтри
                                    </Button>
                                )
                            }
                        />
                    </div>
                ) : (
                    <div className="flex flex-col gap-5">
                        {processedOrders.map(order => {
                            const paymentConfig = PAYMENT_METHOD_MAP[order.payment_method] || PAYMENT_METHOD_MAP.online;
                            const PaymentIcon = paymentConfig.icon;
                            return (
                                <div key={order.id} className="bg-(--platform-bg) border border-(--platform-border-color) rounded-2xl p-5 sm:p-6 transition-all duration-200 hover:shadow-md hover:border-(--platform-text-secondary)/30">
                                    <div className="flex justify-between items-start border-b border-(--platform-border-color)/60 pb-5 mb-5 flex-wrap gap-4">
                                        <div className="flex flex-col gap-2">
                                            <div className="flex items-center gap-4 flex-wrap">
                                                <span className="font-bold text-xl text-(--platform-text-primary)">
                                                    Замовлення #{order.id}
                                                </span>
                                                {getStatusControl(order)}
                                            </div>
                                            <div className="flex items-center gap-2 text-sm text-(--platform-text-secondary) font-medium">
                                                <Calendar size={14} className="text-(--platform-text-secondary)"/>
                                                <span>{formatDate(order.created_at)}</span>
                                            </div>
                                        </div>
                                        <div className="flex gap-4 flex-wrap justify-end">
                                            <div className="text-right bg-(--platform-card-bg) border border-(--platform-border-color) rounded-xl px-4 py-3 shadow-sm flex flex-col justify-center">
                                                <div className="text-xs font-medium text-(--platform-text-secondary) mb-1 uppercase tracking-wide">Спосіб оплати</div>
