                                ? "За вашим запитом або фільтрами нічого не знайдено. Спробуйте змінити критерії пошуку." 
                                : "Додайте свій перший товар, щоб почати продавати."
                            }
                            icon={hasActiveFilters ? Search : Store}
                            action={
