                                                    -{product.sale_percentage}%
                                                </div>
                                            )}
                                        </div>
                                    </div>
                                </div>
                            );
                        })}
                    </div>
                )}
            </div>
        </div>
    );
});

const ProductEditorPanel = ({ 
