// frontend/src/modules/editor/blocks/Catalog/CatalogSettings.jsx
import React, { useState, useEffect } from 'react';
import apiClient from '../../../../shared/api/api';
import { commonStyles, ToggleSwitch, SectionTitle, ToggleGroup } from '../../ui/configuration/SettingsUI';
import CustomSelect from '../../../../shared/ui/elements/CustomSelect';
import { Input } from '../../../../shared/ui/elements/Input';
import RangeSlider from '../../../../shared/ui/elements/RangeSlider'; 
import FontSelector from '../../ui/components/FontSelector';
import { Type, List, Layers, Settings, LayoutGrid } from 'lucide-react';

const CatalogSettings = ({ data, onChange, siteData }) => {
    const [categories, setCategories] = useState([]);
    const themeSettings = siteData?.theme_settings || {};
    const currentSiteFonts = {
        heading: themeSettings.font_heading,
        body: themeSettings.font_body
    };
    useEffect(() => {
        if (siteData?.id) {
            apiClient.get(`/categories/site/${siteData.id}`)
                .then(res => setCategories(res.data))
                .catch(console.error);
        }
    }, [siteData?.id]);

    const updateData = (updates) => {
        onChange({ ...data, ...updates });
    };

    const handleInputChange = (e) => {
        const { name, value } = e.target;
        updateData({ [name]: value });
    };

    const handleSwitchChange = (name, val) => {
        updateData({ [name]: val });
    };

    const sourceTypeOptions = [
        { value: 'all', label: 'Все' },
        { value: 'category', label: 'Категорія' }
    ];

    const categoryOptions = [
        { value: "", label: "-- Оберіть категорію --" },
        ...categories.map(cat => ({ value: cat.id, label: cat.name }))
    ];

    return (
        <div className="flex flex-col gap-6">
            <div>
                <SectionTitle icon={<Type size={16} />}>Заголовок та Шрифт</SectionTitle>
                <div className="mb-5">
                    <Input 
                        name="title" 
                        value={data.title || ''} 
                        onChange={handleInputChange} 
                        placeholder="Напр. Наш Каталог"
                    />
                </div>
                <div className="mb-5">
                    <FontSelector 
                        value={data.titleFontFamily}
                        onChange={(val) => updateData({ titleFontFamily: val })}
                        label="Шрифт заголовка"
                        siteFonts={currentSiteFonts}
                    />
                </div>
            </div>
            <div>
                <SectionTitle icon={<Layers size={16} />}>Джерело товарів</SectionTitle>
                <div className="mb-5">
                    <label style={commonStyles.label}>Що показувати?</label>
                    <ToggleGroup 
                        options={sourceTypeOptions}
                        value={data.source_type || 'all'}
                        onChange={(val) => updateData({ source_type: val })}
                    />
                </div>
                {data.source_type === 'category' && (
                    <div className="mb-5">
                        <label style={{...commonStyles.label}}>Оберіть категорію:</label>
                        <CustomSelect 
                            name="root_category_id" 
                            value={data.root_category_id || ''} 
                            onChange={(e) => updateData({ root_category_id: e.target.value })}
                            options={categoryOptions}
                            leftIcon={<List size={16} />}
                        />
                    </div>
                )}
            </div>
            <div>
                <SectionTitle icon={<Settings size={16} />}>Інструменти для клієнта</SectionTitle>
                <div className="flex flex-col gap-2">
                    <ToggleSwitch 
                        checked={data.show_search !== false}
                        onChange={(val) => handleSwitchChange('show_search', val)}
                        label="Показувати рядок пошуку"
                    />
                    <ToggleSwitch 
                        checked={data.show_category_filter !== false}
                        onChange={(val) => handleSwitchChange('show_category_filter', val)}
                        label="Показувати фільтр категорій"
                    />
                    <ToggleSwitch 
                        checked={data.show_sorting !== false}
                        onChange={(val) => handleSwitchChange('show_sorting', val)}
                        label="Показувати сортування"
                    />
                </div>
            </div>
            <div>
                <SectionTitle icon={<LayoutGrid size={16} />}>Налаштування відображення</SectionTitle>
                <div className="mb-5">
                    <label style={commonStyles.label}>Кількість колонок</label>
                    <ToggleGroup 
                        options={[
                            { value: 2, label: '2' },
                            { value: 3, label: '3' },
                            { value: 4, label: '4' },
                            { value: 5, label: '5' },
                        ]}
                        value={data.columns || 3}
                        onChange={(val) => updateData({ columns: val })}
                    />
                </div>
                <div className="mb-5">
                    <RangeSlider 
                        label="Товарів на одній сторінці"
                        value={data.items_per_page || 12}
                        min={4}
                        max={48}
                        step={4}
                        onChange={(val) => updateData({ items_per_page: val })}
                        unit=" шт" 
                    />
                </div>
            </div>
        </div>
    );
};

export default CatalogSettings;

// frontend/src/modules/editor/blocks/Features/FeaturesBlock.jsx
import React from 'react';
import { useBlockFonts } from '../../../../shared/hooks/useBlockFonts';
import { Star, Zap, Shield, Truck, Gift, Clock, Phone, Settings, Check, User, Globe, Heart, ShoppingBag, Box, Smile, Award } from 'lucide-react';
import { areBlockPropsEqual } from '../../core/blockProps';

const ICON_MAP = {
    star: Star, zap: Zap, shield: Shield, truck: Truck, gift: Gift,
    clock: Clock, phone: Phone, settings: Settings, check: Check,
    user: User, globe: Globe, heart: Heart, shop: ShoppingBag,
    box: Box, smile: Smile, award: Award, default: Star
};

const FeaturesBlock = ({ blockData, siteData, isEditorPreview, style }) => {
    const { 
        title, 
        items = [], 
        columns = 2, 
        layout = 'cards', 
        align = 'center',
        blockAlign = 'center',
        borderRadius = '8px',
        showIconBackground = false,
        titleFontFamily,
        contentFontFamily,
        height = 'small',
        styles = {} 
    } = blockData || {};

    const { styles: fontStyles, RenderFonts, cssVariables } = useBlockFonts({
        title: titleFontFamily,
        content: contentFontFamily
    }, siteData);

    const uniqueClass = `features-scope-${blockData?.block_id || blockData?.id || 'preview'}`;
    const heightClasses = { 
        small: 'min-h-auto', 
        medium: 'min-h-[400px] @3xl:min-h-[600px]', 
        large: 'min-h-[600px] @3xl:min-h-[800px]', 
        full: 'min-h-[calc(100vh-60px)]',
        auto: 'min-h-auto'
    };
    const isCard = layout === 'cards';
    const isList = layout === 'list';
    const blockAlignClasses = {
        left: 'justify-start',
        center: 'justify-center',
        right: 'justify-end'
    };

    const itemWidthClasses = {
        1: 'w-full',
        2: 'w-full @2xl:w-[calc(50%-1rem)]',
        3: 'w-full @2xl:w-[calc(50%-1rem)] @5xl:w-[calc(33.333%-1.333rem)]',
        4: 'w-full @2xl:w-[calc(50%-1rem)] @5xl:w-[calc(25%-1.5rem)]'
    };

    let alignClass = 'items-start text-left';
    if (!isList) {
        if (align === 'center') alignClass = 'items-center text-center';
        else if (align === 'right') alignClass = 'items-end text-right';
    }

    const renderIcon = (iconName) => {
        const IconComponent = ICON_MAP[iconName] || ICON_MAP.default;
        return <IconComponent size={showIconBackground ? 28 : 36} className="@2xl:w-8 @2xl:h-8 @3xl:w-10 @3xl:h-10" />;
    };

    return (
        <div 
            className={`
                py-12 @2xl:py-16 @3xl:py-20 px-5 @2xl:px-8 flex flex-col justify-center bg-(--site-bg) text-(--site-text-primary) w-full
                ${heightClasses[height] || 'min-h-auto'}
                ${uniqueClass}
            `}
            style={{ 
                ...styles,
                ...style,
                ...cssVariables
            }}
        >
            <RenderFonts />
            <style>{`.${uniqueClass} { ${fontStyles.cssVars || ''} }`}</style>
            <style>{`
                .${uniqueClass} .feature-card:hover {
                    transform: translateY(-6px);
                    box-shadow: 0 12px 24px rgba(0,0,0,0.08);
                }
                .${uniqueClass} .feature-card:hover .feature-icon {
                    transform: scale(1.1) rotate(5deg);
                }
            `}</style>
            <div className="w-full max-w-300 mx-auto">
                {title && (
                    <h2 
                        className="text-center mb-10 @3xl:mb-14 text-3xl @2xl:text-4xl @3xl:text-5xl font-bold text-(--site-text-primary) w-full leading-tight tracking-tight"
                        style={{ fontFamily: fontStyles.title }}
                    >
                        {title}
                    </h2>
                )}
                
                <div 
                    className={`
                        flex flex-wrap items-stretch gap-6 @2xl:gap-8 w-full
                        ${blockAlignClasses[blockAlign] || 'justify-center'}
                    `}
                >
                    {items.map((item, index) => (
                        <div 
                            key={item.id || index} 
                            className={`
                                ${itemWidthClasses[columns] || itemWidthClasses[2]}
                                flex relative z-10 transition-all duration-300 ease-[cubic-bezier(0.25,0.8,0.25,1)]
                                ${isList ? 'flex-row items-start gap-4 @2xl:gap-5' : `flex-col gap-3 @2xl:gap-4 ${alignClass}`}
                                ${isCard ? 'feature-card bg-(--site-card-bg) border border-(--site-border-color) p-6 @2xl:p-8 shadow-sm' : 'bg-transparent border-none p-0 @2xl:p-2'}
                            `}
                            style={{ 
                                borderRadius: isCard ? borderRadius : '0' 
                            }}
                        >
                            <div 
                                className={`
                                    feature-icon flex items-center justify-center shrink-0 transition-all duration-300 ease-out
                                    ${showIconBackground ? 'w-14 h-14 @2xl:w-16 @2xl:h-16 rounded-full bg-(--site-accent) text-white shadow-lg shadow-(--site-accent)/20' : 'w-auto h-auto bg-transparent text-(--site-accent)'}
                                    ${(!isList && !showIconBackground) ? 'mb-1 @2xl:mb-2' : ''}
                                `}
                            >
                                {renderIcon(item.icon)}
                            </div>
                            <div className="w-full">
                                <h4 
                                    className="m-0 mb-2 @2xl:mb-3 text-lg @2xl:text-xl font-semibold text-(--site-text-primary) leading-snug"
                                    style={{ fontFamily: fontStyles.content }}
                                >
                                    {item.title}
                                </h4>
                                <p 
                                    className="m-0 text-(--site-text-secondary) leading-relaxed text-sm @2xl:text-base whitespace-pre-wrap opacity-90"
                                    style={{ fontFamily: fontStyles.content }}
                                >
                                    {item.text}
                                </p>
                            </div>
                        </div>
                    ))}
                </div>
                {isEditorPreview && items.length === 0 && (
                    <div className="text-center p-10 opacity-50 border-2 border-dashed border-(--site-border-color) rounded-xl flex flex-col items-center justify-center w-full mt-4">
                        <div className="mb-3 text-(--site-accent)">
                            <Star size={32} />
                        </div>
                        <span className="font-medium">Додайте переваги у налаштуваннях блоку</span>
                    </div>
                )}
            </div>
        </div>
    );
};

export default React.memo(FeaturesBlock, areBlockPropsEqual);

// frontend/src/modules/editor/blocks/Features/FeaturesSettings.jsx
import React, { useState } from 'react';
import { useConfirm } from '../../../../shared/hooks/useConfirm';
import { Input } from '../../../../shared/ui/elements/Input';
import { Button } from '../../../../shared/ui/elements/Button';
import { commonStyles, SectionTitle, ToggleGroup, ToggleSwitch } from '../../ui/configuration/SettingsUI';
import FontSelector from '../../ui/components/FontSelector';
import AlignmentControl from '../../ui/components/AlignmentControl';
import { generateBlockId } from '../../core/editorConfig';
import { List, Grid, Trash2, Plus, Star, Zap, Shield, Truck, Gift, Clock, Phone, Settings, User, Globe, Heart, ShoppingBag, Check, Type } from 'lucide-react';

const CONFIG = {
  MAX_ITEMS: 8,
  DEFAULT_DATA: {
    title: 'Наші переваги',
    items: [],
    columns: 2,
    layout: 'cards',
    align: 'center',
    blockAlign: 'center',
    borderRadius: '8px',
    showIconBackground: false,
    titleFontFamily: 'global',
    contentFontFamily: 'global'
  },
  LAYOUT_OPTIONS: [
    { value: 'cards', label: 'Картки' },
    { value: 'minimal', label: 'Мінімалізм' },
    { value: 'list', label: 'Список' }
  ],
  COLUMN_OPTIONS: [
    { value: 1, label: '1' },
    { value: 2, label: '2' },
    { value: 3, label: '3' },
    { value: 4, label: '4' }
  ],
};

const ICON_OPTIONS = [
  { key: 'star', icon: <Star size={20} /> },
  { key: 'zap', icon: <Zap size={20} /> },
  { key: 'shield', icon: <Shield size={20} /> },
  { key: 'truck', icon: <Truck size={20} /> },
  { key: 'gift', icon: <Gift size={20} /> },
  { key: 'clock', icon: <Clock size={20} /> },
  { key: 'phone', icon: <Phone size={20} /> },
  { key: 'settings', icon: <Settings size={20} /> },
  { key: 'user', icon: <User size={20} /> },
  { key: 'globe', icon: <Globe size={20} /> },
  { key: 'heart', icon: <Heart size={20} /> },
  { key: 'shop', icon: <ShoppingBag size={20} /> }
];

const FeaturesSettings = ({ data, onChange, siteData }) => {
  const [openIndex, setOpenIndex] = useState(null);
  const { confirm } = useConfirm();
  const normalizedData = {
    ...CONFIG.DEFAULT_DATA,
    ...data
  };

  const themeSettings = siteData?.theme_settings || {};
  const currentSiteFonts = {
      heading: themeSettings.font_heading,
      body: themeSettings.font_body
  };
  
  const updateData = (updates) => {
    onChange({ ...normalizedData, ...updates });
  };
  
  const handleFeatureChange = (index, field, value) => {
    const newItems = normalizedData.items.map((item, i) =>
      i === index ? { ...item, [field]: value } : item
    );
    updateData({ items: newItems });
  };
  
  const handleAddFeature = () => {
    if (normalizedData.items.length >= CONFIG.MAX_ITEMS) return;
    const newItem = {
      id: generateBlockId(),
      icon: 'star',
      title: 'Перевага',
      text: 'Опис переваги'
    };
    
    updateData({ items: [...normalizedData.items, newItem] });
    setOpenIndex(normalizedData.items.length);
  };
  
  const handleRemoveFeature = async (e, index) => {
    e.stopPropagation();
    const isConfirmed = await confirm({
      title: "Видалити елемент?",
      message: `Видалити "${normalizedData.items[index].title}"?`,
      type: "danger",
      confirmLabel: "Видалити"
    });
    
    if (isConfirmed) {
      updateData({ 
        items: normalizedData.items.filter((_, i) => i !== index) 
      });
      setOpenIndex(null);
    }
  };
  
  const getIconComponent = (key) => {
    const option = ICON_OPTIONS.find(o => o.key === key);
    return option ? option.icon : <Star size={18} />;
  };
  
  const isMaxItemsReached = normalizedData.items.length >= CONFIG.MAX_ITEMS;
  return (
    <div className="flex flex-col gap-6 w-full">
      <div>
        <SectionTitle icon={<Grid size={16} />}>
          Загальні
        </SectionTitle>
        <Input
          label="Заголовок блоку"
          value={normalizedData.title}
          onChange={(e) => updateData({ title: e.target.value })}
          placeholder="Введіть заголовок"
        />
      </div>

      <div>
        <SectionTitle icon={<Type size={16} />}>
          Типографіка
        </SectionTitle>
        <div className="mb-5">
            <FontSelector 
                value={normalizedData.titleFontFamily}
                onChange={(val) => updateData({ titleFontFamily: val })}
                label="Шрифт заголовку"
                siteFonts={currentSiteFonts}
            />
        </div>
        <div className="mb-5">
            <FontSelector 
                value={normalizedData.contentFontFamily}
                onChange={(val) => updateData({ contentFontFamily: val })}
                label="Шрифт контенту"
                siteFonts={currentSiteFonts}
            />
        </div>
      </div>
      <div>
        <SectionTitle icon={<List size={16} />}>
          Макет та Вигляд
        </SectionTitle>
        <div className="mb-5">
          <label style={commonStyles.label}>Стиль відображення</label>
          <ToggleGroup
            options={CONFIG.LAYOUT_OPTIONS}
            value={normalizedData.layout}
            onChange={(val) => updateData({ layout: val })}
          />
        </div>
        <div className="mb-5">
          <label style={commonStyles.label}>Кількість колонок</label>
          <ToggleGroup
            options={CONFIG.COLUMN_OPTIONS}
            value={normalizedData.columns}
            onChange={(val) => updateData({ columns: val })}
          />
        </div>
        <div className="mb-5">
           <AlignmentControl
              label="Вирівнювання блоків"
              value={normalizedData.blockAlign}
              onChange={(val) => updateData({ blockAlign: val })}
           />
        </div>
        {normalizedData.layout !== 'list' && (
           <div className="mb-5">
              <AlignmentControl
                 label="Вирівнювання тексту"
                 value={normalizedData.align}
                 onChange={(val) => updateData({ align: val })}
              />
           </div>
        )}
      </div>
      <div>
        <SectionTitle icon={<Check size={16} />}>
          Стилізація
        </SectionTitle>
        
        <div className="mb-5">
          <ToggleSwitch
            checked={normalizedData.showIconBackground}
            onChange={(val) => updateData({ showIconBackground: val })}
            label="Фон для іконок"
          />
        </div>
      </div>
      <div>
        <SectionTitle>
          Елементи ({normalizedData.items.length}/{CONFIG.MAX_ITEMS})
        </SectionTitle>
        {normalizedData.items.map((item, index) => (
          <FeatureItem
            key={item.id || index}
            item={item}
            index={index}
            isOpen={openIndex === index}
            onToggle={() => setOpenIndex(openIndex === index ? null : index)}
            onRemove={handleRemoveFeature}
            onChange={handleFeatureChange}
            iconOptions={ICON_OPTIONS}
            getIconComponent={getIconComponent}
          />
        ))}
        <button
          type="button"
          onClick={handleAddFeature}
          disabled={isMaxItemsReached}
          className={`
            w-full p-3 flex items-center justify-center gap-2 bg-transparent border border-dashed border-(--platform-border-color) rounded-lg 
            text-(--platform-text-secondary) font-medium transition-all duration-200 
            ${isMaxItemsReached ? 'cursor-not-allowed opacity-50' : 'cursor-pointer hover:border-(--platform-accent) hover:text-(--platform-accent) hover:bg-transparent'}
          `}
        >
          <Plus size={18} />
          Додати перевагу
        </button>
      </div>
    </div>
  );
};

const FeatureItem = ({ item, index, isOpen, onToggle, onRemove, onChange, iconOptions, getIconComponent }) => {
  return (
    <div
      className={`
        border rounded-lg mb-3 bg-(--platform-card-bg) overflow-hidden transition-colors duration-200
        ${isOpen ? 'border-(--platform-accent)' : 'border-(--platform-border-color) hover:border-(--platform-accent)'}
      `}
    >
      <div 
        className="flex justify-between items-center px-4 py-3 cursor-pointer bg-(--platform-bg) border-b border-transparent transition-colors duration-200" 
        onClick={onToggle}
      >
        <div className="flex items-center gap-2.5">
          <div className="text-(--platform-accent) flex bg-(--platform-card-bg) p-1.5 rounded-md border border-(--platform-border-color)">
            {getIconComponent(item.icon)}
          </div>
          <span className="font-medium text-sm">
            {item.title}
          </span>
        </div>
        <Button
          variant="danger"
          size="sm"
          onClick={(e) => onRemove(e, index)}
          className="w-7! h-7! opacity-60 p-0!"
          title="Видалити"
        >
          <Trash2 size={14} />
        </Button>
      </div>
      {isOpen && (
        <div className="p-4 border-t border-(--platform-border-color)">
          <div className="mb-5">
            <label style={commonStyles.label}>Виберіть іконку</label>
            <div className="grid grid-cols-4 gap-2 w-full">
              {iconOptions.map(opt => (
                <button
                  key={opt.key}
                  type="button"
                  className={`
                    w-full aspect-square flex items-center justify-center rounded-lg border bg-transparent cursor-pointer transition-all duration-200
                    ${item.icon === opt.key 
                        ? 'border-(--platform-accent) text-(--platform-accent) ring-1 ring-(--platform-accent)' 
                        : 'border-(--platform-border-color) text-(--platform-text-secondary) hover:border-(--platform-accent) hover:text-(--platform-accent)'
                    }
                  `}
                  onClick={() => onChange(index, 'icon', opt.key)}
                  title={opt.key}
                >
                  {opt.icon}
                </button>
              ))}
            </div>
          </div>
          <Input
            label="Заголовок"
            value={item.title}
            onChange={(e) => onChange(index, 'title', e.target.value)}
            placeholder="Назва переваги"
          />
          <div className="mb-5">
            <label style={commonStyles.label}>Опис</label>
            <textarea
              value={item.text}
              onChange={(e) => onChange(index, 'text', e.target.value)}
              style={{ ...commonStyles.textarea, minHeight: '80px' }}
              className="custom-scrollbar"
            />
          </div>
        </div>
      )}
    </div>
  );
};

export default FeaturesSettings;

// frontend/src/modules/editor/blocks/Footer/FooterBlock.jsx
import React, { useId } from 'react';
import { useBlockFonts } from '../../../../shared/hooks/useBlockFonts';
import { BASE_URL } from '../../../../shared/config';
import { Facebook, Instagram, Send, Youtube, Music, Twitter, Linkedin, Github } from 'lucide-react';
import { areBlockPropsEqual } from '../../core/blockProps';

const IconsMap = {
    facebook: Facebook,
    instagram: Instagram,
    telegram: Send,
    youtube: Youtube,
    tiktok: Music,
    twitter: Twitter,
    linkedin: Linkedin,
    github: Github,
    default: Send
};

const FooterBlock = ({ blockData, siteData, isEditorPreview, style }) => {
    const data = blockData || {};
    const reactId = useId().replace(/:/g, '');
    const {
        variant = 'standard',
        theme_mode = 'auto',
        bg_type = 'color',
        bg_color = '#111827',
        bg_opacity = 1,
        bg_image,
        overlay_color = '#000000',
        overlay_opacity = 0.5,
        copyright = `© ${new Date().getFullYear()} Назва компанії`,
        links = [],
        socials = [],
        contentFontFamily,
        styles = {}
    } = data;

    const { styles: fontStyles, RenderFonts, cssVariables } = useBlockFonts({
        content: contentFontFamily
    }, siteData);
    
    let rawOpacity = Number(overlay_opacity);
    if (isNaN(rawOpacity)) rawOpacity = 0.5;
    const safeOpacity = rawOpacity > 1 ? rawOpacity / 100 : rawOpacity;
    const fullImageUrl = bg_image 
        ? (bg_image.startsWith('http') ? bg_image : `${BASE_URL}${bg_image}`)
        : null;
    const getTextColor = () => {
        if (theme_mode === 'dark') return '#ffffff';
        if (theme_mode === 'light') return '#111827';
        return 'var(--site-text-primary, inherit)';
    };
    const computedTextColor = getTextColor();
    const isTransparent = overlay_color === 'transparent';
    const uniqueClass = `footer-scope-${data.block_id || data.id || reactId}`;
    const renderBackground = () => (
        <div className="absolute inset-0 z-0 overflow-hidden pointer-events-none">
            {bg_type === 'color' && (
                <div className="absolute inset-0" style={{ backgroundColor: bg_color, opacity: bg_opacity }} />
            )}
            {bg_type === 'image' && fullImageUrl && (
                <div 
                    className="w-full h-full bg-cover bg-center"
                    style={{ backgroundImage: `url(${fullImageUrl})` }} 
                />
            )}
            {bg_type === 'image' && !isTransparent && (
                <div
                    className="absolute inset-0 z-1 transition-all duration-300"
                    style={{ backgroundColor: overlay_color, opacity: safeOpacity }}
                />
            )}
        </div>
    );

    return (
        <footer 
            className={`
                relative w-full flex flex-col overflow-hidden
                ${variant === 'simple' ? 'py-6 @2xl:py-8' : 'py-8 @2xl:py-12'}
                ${uniqueClass}
            `}
            style={{ 
                ...styles,
                ...style,
                color: computedTextColor,
                ...cssVariables
            }}
            id={data.anchorId}
        >
            <RenderFonts />
            <style>{`.${uniqueClass} { ${fontStyles.cssVars || ''} }`}</style>
            {renderBackground()}
            <div className="relative z-10 mx-auto px-5 @2xl:px-8 max-w-300 w-full">
                {variant === 'simple' ? (
                    <div className="text-center">
                        <p className="text-sm @2xl:text-base m-0 opacity-80" style={{ fontFamily: fontStyles.content }}>
                            {copyright}
                        </p>
                    </div>
                ) : (
                    <div className="flex flex-col @3xl:flex-row justify-between items-center gap-6 @2xl:gap-8">
                        <div className="flex flex-col items-center @3xl:items-start gap-3 w-full @3xl:w-auto text-center @3xl:text-left">
                            <p className="text-sm @2xl:text-base m-0 opacity-80" style={{ fontFamily: fontStyles.content }}>
                                {copyright}
                            </p>
                        </div>
                        {links && links.length > 0 && (
                            <div className="flex flex-wrap justify-center @3xl:justify-end gap-4 @2xl:gap-6 text-sm @2xl:text-base font-medium">
                                {links.map((link, idx) => (
                                    <a 
                                        key={link.id || idx} 
                                        href={link.link || '#'}
                                        className="transition-opacity duration-200 no-underline text-inherit opacity-80 hover:opacity-100"
                                        style={{ fontFamily: fontStyles.content }}
                                        onClick={(e) => isEditorPreview && e.preventDefault()}
                                    >
                                        {link.label}
                                    </a>
                                ))}
                            </div>
                        )}
                        {socials && socials.length > 0 && (
                            <div className="flex justify-center gap-4 @2xl:gap-5">
                                {socials.map((social, idx) => {
                                    const IconComponent = IconsMap[social.platform] || IconsMap.default;
                                    return (
                                        <a 
                                            key={social.id || idx} 
                                            href={social.link || '#'} 
                                            className="transition-transform duration-200 no-underline text-inherit opacity-80 hover:opacity-100 hover:scale-110"
                                            title={social.platform}
                                            onClick={(e) => isEditorPreview && e.preventDefault()}
                                        >
                                            <IconComponent size={20} className="@2xl:w-6 @2xl:h-6" />
                                        </a>
                                    );
                                })}
                            </div>
                        )}
                    </div>
                )}
            </div>
        </footer>
    );
};

export default React.memo(FooterBlock, areBlockPropsEqual);

// frontend/src/modules/editor/blocks/Footer/FooterSettings.jsx
import React from 'react';
import { generateBlockId } from '../../core/editorConfig';
import { commonStyles, SectionTitle, ToggleGroup } from '../../ui/configuration/SettingsUI';
import { Input } from '../../../../shared/ui/elements/Input';
import { Button } from '../../../../shared/ui/elements/Button';
import CustomSelect from '../../../../shared/ui/elements/CustomSelect';
import OverlayControl from '../../ui/components/OverlayControl';
import UniversalMediaInput from '../../../../shared/ui/complex/UniversalMediaInput';
import FontSelector from '../../ui/components/FontSelector';
import { BASE_URL } from '../../../../shared/config';
import { Palette, Image as ImageIcon, Type, FileText, Link as LinkIcon, Share2, Trash2, Plus, Moon, Sun, Monitor } from 'lucide-react';

const SOCIAL_PLATFORMS = [
    { value: 'facebook', label: 'Facebook' },
    { value: 'instagram', label: 'Instagram' },
    { value: 'telegram', label: 'Telegram' },
    { value: 'youtube', label: 'YouTube' },
    { value: 'tiktok', label: 'TikTok' },
    { value: 'twitter', label: 'Twitter' },
    { value: 'linkedin', label: 'LinkedIn' },
    { value: 'github', label: 'GitHub' },
];

const FooterSettings = ({ data, onChange, siteData }) => {
    const updateData = (updates) => onChange({ ...data, ...updates });
    const themeSettings = siteData?.theme_settings || {};
    const currentSiteFonts = {
        heading: themeSettings.font_heading,
        body: themeSettings.font_body
    };
    const currentVariant = data.variant || 'standard';
    const currentThemeMode = data.theme_mode || 'auto';
    const currentBgType = data.bg_type || 'color';
    const handleImageChange = (val) => {
        let finalUrl = val?.target?.value || val || '';
        updateData({ bg_image: finalUrl.replace(BASE_URL, '') });
    };

    const handleAddLink = () => {
        const newLinks = [...(data.links || []), { id: generateBlockId(), label: 'Нове посилання', link: '#' }];
        updateData({ links: newLinks });
    };

    const handleUpdateLink = (index, field, value) => {
        const newLinks = [...(data.links || [])];
        newLinks[index][field] = value;
        updateData({ links: newLinks });
    };

    const handleRemoveLink = (index) => {
        const newLinks = (data.links || []).filter((_, i) => i !== index);
        updateData({ links: newLinks });
    };

    const handleAddSocial = () => {
        const newSocials = [...(data.socials || []), { id: generateBlockId(), platform: 'instagram', link: 'https://' }];
        updateData({ socials: newSocials });
    };

    const handleUpdateSocial = (index, field, value) => {
        const newSocials = [...(data.socials || [])];
        newSocials[index][field] = value;
        updateData({ socials: newSocials });
    };

    const handleRemoveSocial = (index) => {
        const newSocials = (data.socials || []).filter((_, i) => i !== index);
        updateData({ socials: newSocials });
    };

    const bgTypeOptions = [
        { value: 'color', label: 'Колір', icon: <Palette size={16}/> },
        { value: 'image', label: 'Фото', icon: <ImageIcon size={16}/> }
    ];

    return (
        <div className="flex flex-col gap-6">
            <div>
                <SectionTitle icon={<Palette size={18}/>}>Фон та Тема</SectionTitle>
                <div className="mb-5">
                    <label style={commonStyles.label}>Варіант відображення</label>
                    <ToggleGroup 
                        options={[
                            { value: 'standard', label: 'Стандартний' },
                            { value: 'simple', label: 'Мінімалізм' },
                        ]}
                        value={currentVariant}
                        onChange={(val) => updateData({ variant: val })}
                    />
                </div>
                <div className="mb-5">
                    <label style={commonStyles.label}>Тема</label>
                    <ToggleGroup 
                        options={[
                            { value: 'auto', label: <div className="flex gap-1.5 items-center"><Monitor size={16}/> Авто</div> },
                            { value: 'light', label: <div className="flex gap-1.5 items-center"><Sun size={16}/> Світла</div> },
                            { value: 'dark', label: <div className="flex gap-1.5 items-center"><Moon size={16}/> Темна</div> },
                        ]}
                        value={currentThemeMode}
                        onChange={(val) => updateData({ theme_mode: val })}
                    />
                </div>
                <div className="mb-5">
                    <label style={commonStyles.label}>Тип фону</label>
                    <ToggleGroup 
                        options={bgTypeOptions}
                        value={currentBgType}
                        onChange={(val) => updateData({ bg_type: val })}
                    />
                </div>
                {currentBgType === 'color' && (
                    <OverlayControl 
                        color={data.bg_color || '#111827'}
                        opacity={data.bg_opacity !== undefined ? data.bg_opacity : 1} 
                        onColorChange={(val) => updateData({ bg_color: val })}
                        onOpacityChange={(val) => updateData({ bg_opacity: val })} 
                    />
                )}
                {currentBgType === 'image' && (
                    <div className="mb-5">
                        <label style={commonStyles.label}>Фонове зображення</label>
                        <div className="h-40">
                            <UniversalMediaInput 
                                type="image"
                                value={data.bg_image}
                                onChange={handleImageChange}
                                aspect={21/9}
                            />
                        </div>
                    </div>
                )}
                {currentBgType === 'image' && (
                    <OverlayControl 
                        color={data.overlay_color || '#000000'}
                        opacity={data.overlay_opacity !== undefined ? data.overlay_opacity : 0.5}
                        onColorChange={(val) => updateData({ overlay_color: val })}
                        onOpacityChange={(val) => updateData({ overlay_opacity: val })}
                    />
                )}
            </div>
            <div>
                <SectionTitle icon={<Type size={18}/>}>Бренд та Типографіка</SectionTitle>
                <div className="mb-5">
                    <FontSelector 
                        value={data.titleFontFamily}
                        onChange={(val) => updateData({ titleFontFamily: val })}
                        label="Шрифт логотипу"
                        siteFonts={currentSiteFonts}
                    />
                </div>
                <div className="mb-5">
                    <FontSelector 
                        value={data.contentFontFamily}
                        onChange={(val) => updateData({ contentFontFamily: val })}
                        label="Шрифт посилань та тексту"
                        siteFonts={currentSiteFonts}
                    />
                </div>
                {currentVariant !== 'simple' && (
                    <div className="mb-5">
                        <Input 
                            label="Текст логотипу" 
                            value={data.logo_text || 'Логотип'} 
                            onChange={(e) => updateData({ logo_text: e.target.value })} 
                        />
                    </div>
                )}
                <div className="mb-5">
                    <Input 
                        label="Текст копірайту"
                        name="copyright" 
                        value={data.copyright || `© ${new Date().getFullYear()} Назва компанії`} 
                        onChange={(e) => updateData({ copyright: e.target.value })} 
                        placeholder="© 2026 Company Name"
                        leftIcon={<FileText size={16}/>}
                    />
                </div>
            </div>
            {currentVariant !== 'simple' && (
                <>
                    <div className="border-t border-(--platform-border-color) pt-6">
                        <SectionTitle icon={<LinkIcon size={18}/>}>Навігація / Посилання</SectionTitle>
                        <div className="flex flex-col gap-3">
                            {(data.links || []).map((link, idx) => (
                                <div key={link.id || idx} className="flex gap-2 items-start bg-(--platform-card-bg) p-3 rounded-lg border border-(--platform-border-color)">
                                    <div className="flex flex-col gap-2 flex-1">
                                        <Input 
                                            value={link.label} 
                                            onChange={(e) => handleUpdateLink(idx, 'label', e.target.value)} 
                                            placeholder="Назва"
                                        />
                                        <Input 
                                            value={link.link} 
                                            onChange={(e) => handleUpdateLink(idx, 'link', e.target.value)} 
                                            placeholder="URL"
                                        />
                                    </div>
                                    <Button variant="danger" size="sm" onClick={() => handleRemoveLink(idx)} className="w-9! h-9! p-0! shrink-0">
                                        <Trash2 size={16} />
                                    </Button>
                                </div>
                            ))}
                            <Button variant="outline" onClick={handleAddLink} icon={<Plus size={16} />} className="w-full border-dashed">
                                Додати посилання
                            </Button>
                        </div>
                    </div>

                    <div className="border-t border-(--platform-border-color) pt-6">
                        <SectionTitle icon={<Share2 size={18}/>}>Соціальні мережі</SectionTitle>
                        <div className="flex flex-col gap-3">
                            {(data.socials || []).map((social, idx) => (
                                <div key={social.id || idx} className="flex gap-2 items-start bg-(--platform-card-bg) p-3 rounded-lg border border-(--platform-border-color)">
                                    <div className="flex flex-col gap-2 flex-1">
                                        <CustomSelect 
                                            value={social.platform}
                                            onChange={(e) => handleUpdateSocial(idx, 'platform', e.target.value)}
                                            options={SOCIAL_PLATFORMS}
                                        />
                                        <Input 
                                            value={social.link} 
                                            onChange={(e) => handleUpdateSocial(idx, 'link', e.target.value)} 
                                            placeholder="https://"
                                        />
                                    </div>
                                    <Button variant="danger" size="sm" onClick={() => handleRemoveSocial(idx)} className="w-9! h-9! p-0! shrink-0">
                                        <Trash2 size={16} />
                                    </Button>
                                </div>
                            ))}
                            <Button variant="outline" onClick={handleAddSocial} icon={<Plus size={16} />} className="w-full border-dashed">
                                Додати соцмережу
                            </Button>
                        </div>
                    </div>
                </>
            )}
        </div>
    );
};

export default FooterSettings;

// frontend/src/modules/editor/blocks/Form/FormBlock.jsx
import React, { useState } from 'react';
import apiClient from '../../../../shared/api/api';
import { toast } from 'react-toastify';
import { useBlockFonts } from '../../../../shared/hooks/useBlockFonts';
import { Send, ArrowRight, ShoppingCart, Mail, Phone, Check, Star, MousePointer2, User, AtSign, Type, MessageSquare } from 'lucide-react';
import { areBlockPropsEqual } from '../../core/blockProps';

const DEFAULT_BUTTON_CONFIG = {
    text: 'Надіслати',
    styleType: 'primary',
    variant: 'solid',
    size: 'medium',
    borderRadius: 8,
    width: 'auto',
    alignment: 'center',
    icon: 'none',
    iconPosition: 'right',
    fontFamily: 'global'
};

const FormBlock = ({ blockData, siteData, isEditorPreview, style }) => {
    const [formData, setFormData] = useState({ name: '', email: '', subject: '', message: '' });
    const [status, setStatus] = useState({ loading: false, error: '', success: '' });
    const { 
        successMessage, 
        height = 'small', 
        buttonText 
    } = blockData;
    
    const buttonConfig = {
        ...DEFAULT_BUTTON_CONFIG,
        ...((blockData && blockData.button) || {}),
        text: (blockData && blockData.button && blockData.button.text) || buttonText || DEFAULT_BUTTON_CONFIG.text
    };

    const rawRadius = buttonConfig.borderRadius;
    const safeRadius = (rawRadius !== undefined && rawRadius !== null && rawRadius !== '') 
        ? parseInt(rawRadius, 10) 
        : 8;
    const { styles: fontStyles, RenderFonts, cssVariables } = useBlockFonts({
        button: buttonConfig.fontFamily
    }, siteData);

    const handleChange = (e) => {
        setFormData({ ...formData, [e.target.name]: e.target.value });
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        if (isEditorPreview) return;
        setStatus({ loading: true, error: '', success: '' });
        try {
            await apiClient.post(`/public/form/${siteData.id}/submit`, formData);
            toast.success(successMessage || 'Дякуємо! Ваше повідомлення надіслано.');
            setStatus({ loading: false, error: '', success: '' });
            setFormData({ name: '', email: '', subject: '', message: '' });
        } catch (err) {
            setStatus({ loading: false, error: err.response?.data?.message || 'Помилка відправки.', success: '' });
        }
    };

    const accentColor = 'var(--site-accent, #3b82f6)';
    const textColor = 'var(--site-text-primary, #111827)';
    const whiteColor = '#ffffff';
    const colorVar = buttonConfig.styleType === 'secondary' ? textColor : accentColor;
    const isOutline = buttonConfig.variant === 'outline';
    const dynamicBtnStyle = {
        background: isOutline ? 'transparent' : colorVar,
        color: isOutline ? colorVar : (buttonConfig.styleType === 'secondary' && !isOutline ? whiteColor : whiteColor),
        border: isOutline ? `2px solid ${colorVar}` : '2px solid transparent',
        opacity: status.loading ? 0.7 : 1,
    };

    const sizeClasses = {
        small: 'px-5 py-2 @2xl:px-6 @2xl:py-2.5 text-sm @2xl:text-[0.95rem]',
        medium: 'px-6 py-2.5 @2xl:px-8 @2xl:py-3.5 text-sm @2xl:text-base',
        large: 'px-8 py-3 @2xl:px-12 @2xl:py-4 text-base @2xl:text-[1.15rem]'
    };
    
    const alignMap = {
        left: 'justify-start',
        center: 'justify-center',
        right: 'justify-end'
    };

    const heightClasses = { 
        small: 'min-h-auto',
        medium: 'min-h-[400px] @3xl:min-h-[500px]',
        large: 'min-h-[500px] @3xl:min-h-[700px]',
        full: 'min-h-[calc(100vh-60px)]' 
    };
    
    const scopeClass = `form-scope-${blockData?.block_id || blockData?.id || 'preview'}`;
    const btnClass = `form-btn-${blockData?.block_id || blockData?.id || 'preview'}`;
    const labelClasses = "block text-sm @2xl:text-[0.95rem] font-medium text-(--site-text-primary) mb-1.5 @2xl:mb-2.5 ml-0.5";
    const inputClasses = `
        peer w-full pl-10 @2xl:pl-12 pr-3 @2xl:pr-4 py-3 @2xl:py-3.5 
        bg-black/[0.02] dark:bg-white/[0.02] 
        border-2 border-(--site-border-color)
        text-(--site-text-primary) font-medium
        rounded-xl text-[1rem] 
        transition-all duration-300 outline-none 
        focus:bg-transparent dark:focus:bg-transparent
        focus:border-(--site-accent) focus:ring-4 focus:ring-(--site-accent)/15 
        hover:border-(--site-text-secondary)
    `;
    
