// frontend/src/modules/editor/blocks/Header/HeaderBlock.jsx
import React, { useContext } from 'react';
import { Link } from 'react-router-dom';
import { AuthContext } from '../../../../app/providers/AuthContext';
import { FavoritesContext } from '../../../../app/providers/FavoritesContext';
import { resolveSiteLink } from '../../../../shared/utils/linkUtils';
import { useBlockFonts } from '../../../../shared/hooks/useBlockFonts';
import { BASE_URL } from '../../../../shared/config';
import { Settings, Star, Menu, ArrowRight, ShoppingCart, Mail, Phone, Check, MousePointer2, Star as StarIcon } from 'lucide-react';

const ICON_MAP = {
    arrowRight: ArrowRight, cart: ShoppingCart, mail: Mail, phone: Phone, check: Check, none: null, star: StarIcon, pointer: MousePointer2
};

const formatRadius = (val) => {
    if (val === undefined || val === null || val === '') return '0px';
    const str = String(val);
    return str.endsWith('px') ? str : `${str}px`;
};

const resolveUrl = (src) => {
    if (!src) return null;
    if (typeof src === 'string') {
        if (src.startsWith('http') || src.startsWith('data:') || src.startsWith('blob:')) return src;
        if (src.startsWith('/logos/')) return src;
        if (src.includes('/src/') || src.includes('/assets/') || src.includes('@fs')) return src;
        const cleanSrc = src.startsWith('/') ? src : `/${src}`;
        return `${BASE_URL}${cleanSrc}`;
    }
    return null;
};

const HeaderBlock = React.memo(({ blockData, siteData, isEditorPreview, onMenuToggle }) => {
    const { 
        show_title, nav_items = [], logo_size = 'medium', nav_alignment = 'right',
        nav_style = 'text', nav_fontFamily, buttonSettings = {}, logo_radius, borderRadius
    } = blockData;
    const effectiveLogoRadius = logo_radius !== undefined ? logo_radius : (borderRadius || 0);
    const { styles: fontStyles, RenderFonts, cssVariables } = useBlockFonts({
        navText: nav_fontFamily, btnFont: buttonSettings.fontFamily 
    }, siteData);
    let effectiveLogoSrc = blockData.logo_src;
    let effectiveTitle = blockData.site_title;
    if (effectiveLogoSrc === undefined || effectiveLogoSrc === null) {
        if (siteData?.logo_url) effectiveLogoSrc = siteData.logo_url;
    }
    if (effectiveTitle === undefined || effectiveTitle === null) {
        if (siteData?.title) effectiveTitle = siteData.title || 'Site Title';
    }
    const { user } = useContext(AuthContext) || {};
    const favContext = useContext(FavoritesContext) || {};
    const favoriteSiteIds = favContext.favoriteSiteIds || new Set();
    const addFavorite = favContext.addFavorite || (() => console.warn('FavoritesProvider missing'));
    const removeFavorite = favContext.removeFavorite || (() => console.warn('FavoritesProvider missing'));
    const isOwner = user && siteData && user.id === siteData.user_id;
    const isCollaborator = user && siteData && (
        siteData.user_access_role === 'editor' || 
        siteData.user_access_role === 'collaborator' ||
        siteData.is_collaborator === true ||
        siteData.isCollaborator === true
    );
    const canManageSite = isOwner || isCollaborator;
    const isFavorite = siteData && favoriteSiteIds.has(parseInt(siteData.id));
    const logoUrl = resolveUrl(effectiveLogoSrc);
    const NavWrapper = isEditorPreview ? 'div' : Link;
    const ActionWrapper = isEditorPreview ? 'div' : Link;
    const siteRoot = resolveSiteLink('/', siteData?.site_path);
    const homeLink = isEditorPreview ? '#' : siteRoot;
    const isStickyBlock = blockData.is_sticky && !isEditorPreview;
    const getLogoHeight = () => {
        switch (logo_size) {
            case 'small': return '30px';
            case 'large': return '80px'; 
            case 'medium': default: return '50px';
        }
    };
    const btnVariant = buttonSettings.variant || 'solid';
    const btnStyleType = buttonSettings.styleType || 'primary';
    const btnRadius = buttonSettings.borderRadius !== undefined ? parseInt(buttonSettings.borderRadius) : 4;
    const btnSize = buttonSettings.size || 'medium';
    const colorVar = btnStyleType === 'secondary' ? 'var(--site-text-primary)' : 'var(--site-accent)';
    const btnCssVars = {
        '--nav-btn-bg': btnVariant === 'outline' ? 'transparent' : colorVar,
        '--nav-btn-color': btnVariant === 'outline' ? colorVar : (btnStyleType === 'secondary' ? 'var(--site-bg)' : '#ffffff'),
        '--nav-btn-border': btnVariant === 'outline' ? `2px solid ${colorVar}` : '2px solid transparent',
        '--nav-btn-hover-bg': btnVariant === 'outline' ? `color-mix(in srgb, ${colorVar} 10%, transparent)` : colorVar,
        '--nav-btn-hover-opacity': btnVariant === 'solid' ? '0.9' : '1',
    };
    let btnPadding = '8px 16px';
    let btnFontSize = '0.95rem';
    if (btnSize === 'small') { btnPadding = '6px 12px'; btnFontSize = '0.85rem'; }
    if (btnSize === 'large') { btnPadding = '12px 24px'; btnFontSize = '1.05rem'; }
    const iconBtnClass = `
        header-action-btn flex items-center justify-center w-11 h-11 rounded-xl border cursor-pointer transition-all duration-200 shrink-0 backdrop-blur-md
        border-(--site-border-color) bg-(--site-card-bg)/90
    `;
    return (
        <header 
            className={`
                flex items-center justify-between w-full transition-all duration-300
                bg-(--site-header-bg,var(--site-bg)) text-(--site-text-primary)
                ${isStickyBlock ? 'sticky top-0 z-90' : 'relative'}
                py-3 px-4 @3xl:py-4 @3xl:px-8 gap-4 @3xl:gap-8
            `}
            style={cssVariables}
        >
            <RenderFonts />
            <style>{`
                .nav-style-text:hover { color: var(--site-accent); }
                .nav-style-button {
                    background: var(--nav-btn-bg);
                    color: var(--nav-btn-color);
                    border: var(--nav-btn-border);
                }
                .nav-style-button:hover {
                    background: var(--nav-btn-hover-bg);
                    opacity: var(--nav-btn-hover-opacity);
                    transform: translateY(-1px);
                }
                .header-action-btn {
                    color: var(--site-text-secondary);
                }
                .header-action-btn:hover {
                    color: var(--site-accent) !important;
                    border-color: var(--site-accent) !important;
                    background-color: var(--site-bg) !important;
                }
                ${isFavorite && !canManageSite ? `
                    .favorite-btn-active {
                        border-color: var(--site-accent) !important;
                        background: var(--site-bg) !important;
                        color: var(--site-accent) !important;
                    }
                ` : ''}
            `}</style>
            <NavWrapper to={homeLink} className="flex items-center gap-3 no-underline text-inherit shrink-0 cursor-pointer" onClick={e => isEditorPreview && e.preventDefault()}>
                {logoUrl && (
                    <img 
                        src={logoUrl} 
                        alt="Logo" 
                        className="w-auto object-contain transition-[height] duration-200 max-w-37.5 @3xl:max-w-50 @5xl:max-w-75" 
                        style={{ height: getLogoHeight(), borderRadius: formatRadius(effectiveLogoRadius) }} 
                    />
                )}
                {show_title && (
                    <span 
                        className="font-bold whitespace-nowrap overflow-hidden text-ellipsis text-[1rem] @3xl:text-[1.2rem] max-w-35 @3xl:max-w-50 @5xl:max-w-75" 
                        style={{ fontFamily: fontStyles.navText }}
                    >
                        {effectiveTitle}
                    </span>
                )}
            </NavWrapper>
            <nav
                className="hidden @5xl:flex gap-6 flex-1 px-5 items-center" 
                style={{ justifyContent: nav_alignment === 'center' ? 'center' : (nav_alignment === 'left' ? 'flex-start' : 'flex-end') }}
            >
                {nav_items.map((item) => {
                    const isBtnStyle = nav_style === 'button';
                    const IconComp = (isBtnStyle && buttonSettings.icon && buttonSettings.icon !== 'none') ? ICON_MAP[buttonSettings.icon] : null;
                    const iconPos = buttonSettings.iconPosition || 'right';
                    const isFlipped = buttonSettings.iconFlip;
                    return (
                        <NavWrapper 
                            key={item.id} 
                            to={isEditorPreview ? '#' : resolveSiteLink(item.link, siteData?.site_path)} 
                            onClick={e => isEditorPreview && e.preventDefault()} 
                            className={`
                                no-underline transition-all duration-200 cursor-pointer 
                                ${isBtnStyle ? 'nav-style-button flex items-center justify-center gap-2 font-semibold' : 'nav-style-text font-medium text-[0.95rem] py-1 text-inherit'}
                            `}
                            style={isBtnStyle ? {
                                ...btnCssVars,
                                borderRadius: `${btnRadius}px`,
                                fontFamily: fontStyles.btnFont,
                                padding: btnPadding,
                                fontSize: btnFontSize,
                                lineHeight: 1
                            } : { fontFamily: fontStyles.navText }}
                        >
                            {isBtnStyle && IconComp && iconPos === 'left' && <IconComp size={16} style={{ transform: isFlipped ? 'scaleX(-1)' : 'none' }} />}
                            <span>{item.label}</span>
                            {isBtnStyle && IconComp && iconPos === 'right' && <IconComp size={16} style={{ transform: isFlipped ? 'scaleX(-1)' : 'none' }} />}
                        </NavWrapper>
                    );
                })}
            </nav>
            <div className="flex items-center gap-2 shrink-0">
                {nav_items.length > 0 && (
                    <div 
                        className={`@5xl:hidden ${iconBtnClass}`}
                        title="Меню" 
                        onClick={onMenuToggle}
                    >
                        <Menu size={22} />
                    </div>
                )}
                {canManageSite ? (
                    <ActionWrapper 
                        to={`/dashboard/${siteData?.site_path}`} 
                        className={`${iconBtnClass} no-underline`}
                        title="Налаштування сайту" 
                        onClick={e => isEditorPreview && e.preventDefault()} 
                    >
                        <Settings size={22} />
                    </ActionWrapper>
                ) : (
                    <button 
                        className={`${iconBtnClass} ${isFavorite ? 'favorite-btn-active' : ''}`}
                        onClick={() => !isEditorPreview && (isFavorite ? removeFavorite(siteData.id) : addFavorite(siteData.id))} 
                        title={isFavorite ? "Видалити з обраних" : "Додати в обрані"} 
                    >
                        <Star size={22} fill={isFavorite ? "currentColor" : "none"} />
                    </button>
                )}
            </div>
        </header>
    );
});

export default HeaderBlock;

// frontend/src/modules/editor/blocks/Header/HeaderSettings.jsx
import React, { useState } from 'react';
import { generateBlockId } from '../../core/editorConfig';
import { commonStyles, ToggleGroup, ToggleSwitch, SectionTitle } from '../../ui/configuration/SettingsUI';
import { Input } from '../../../../shared/ui/elements/Input';
import { Button } from '../../../../shared/ui/elements/Button';
import RangeSlider from '../../../../shared/ui/elements/RangeSlider';
import ConfirmModal from '../../../../shared/ui/complex/ConfirmModal';
import AlignmentControl from '../../ui/components/AlignmentControl';
import ButtonEditor from '../../ui/components/ButtonEditor';
import FontSelector from '../../ui/components/FontSelector';
import UniversalMediaInput from '../../../../shared/ui/complex/UniversalMediaInput';
import { Trash2, Plus, Image, Type, LayoutTemplate, List, Link as LinkIcon, Pencil, Crop } from 'lucide-react';

const HeaderSettings = ({ data, onChange, siteData }) => {
    const [isDeleteModalOpen, setIsDeleteModalOpen] = useState(false);
    const [itemToDeleteId, setItemToDeleteId] = useState(null);
    const MAX_NAV_ITEMS = 5;
    const navItemsCount = (data.nav_items || []).length;
    const isLimitReached = navItemsCount >= MAX_NAV_ITEMS;
    const updateData = (updates) => onChange({ ...data, ...updates });
    const handleNavItemChange = (id, field, value) => {
        const newItems = data.nav_items.map(item => 
            item.id === id ? { ...item, [field]: value } : item
        );
        updateData({ nav_items: newItems });
    };

    const addNavItem = () => {
        if (isLimitReached) return;
        const newItem = { id: generateBlockId(), label: 'Нова сторінка', link: '/' };
        updateData({ nav_items: [...(data.nav_items || []), newItem] });
    };

    const requestDelete = (id) => {
        setItemToDeleteId(id);
        setIsDeleteModalOpen(true);
    };

    const confirmDelete = () => {
        if (itemToDeleteId) {
            updateData({ nav_items: data.nav_items.filter(item => item.id !== itemToDeleteId) });
        }
        setIsDeleteModalOpen(false);
        setItemToDeleteId(null);
    };

    const handleLogoChange = (val) => {
        const newValue = val?.target ? val.target.value : val;
        updateData({ logo_src: newValue });
    };

    const currentLogoRadius = data.logo_radius !== undefined ? data.logo_radius : (data.borderRadius || 0);
    const navStyle = data.nav_style || 'text';
    return (
        <div className="flex flex-col gap-6">
            <ConfirmModal 
                isOpen={isDeleteModalOpen}
                title="Видалити пункт меню?"
                message="Цю дію не можна скасувати."
                confirmLabel="Видалити"
                cancelLabel="Скасувати"
                onConfirm={confirmDelete}
                onCancel={() => setIsDeleteModalOpen(false)}
                type="danger"
            />
            <div>
                <SectionTitle icon={<Image size={18}/>}>Логотип та Назва</SectionTitle>
                <div className="mb-5">
                    <label style={commonStyles.label}>Центральний логотип</label>
                    <div className="bg-(--platform-bg) p-3 rounded-xl border border-(--platform-border-color)">
                        <div className="w-full h-50">
                            <UniversalMediaInput 
                                type="image"
                                value={data.logo_src} 
                                onChange={handleLogoChange} 
                                aspect={data.aspectRatio === 1 ? 1 : null}
                            />
                        </div>
                    </div>
                </div>
                <div className="mb-5">
                    <ToggleGroup 
                        options={[
                            { value: 'small', label: 'S' },
                            { value: 'medium', label: 'M' },
                            { value: 'large', label: 'L' },
                        ]}
                        value={data.logo_size || 'medium'}
                        onChange={(val) => updateData({ logo_size: val })}
                    />
                </div>
                <div className="mb-5">
                    <RangeSlider 
                        label="Скруглення логотипу"
                        value={currentLogoRadius}
                        onChange={(val) => updateData({ logo_radius: val })}
                        min={0}
                        max={50}
                        unit="px"
                    />
                </div>
                <div className="mb-5">
                    <Input 
                        label="Назва сайту"
                        value={data.site_title || ''}
                        onChange={(e) => updateData({ site_title: e.target.value })}
                        leftIcon={<Type size={16}/>}
                    />
                </div>
                <ToggleSwitch 
                    checked={data.show_title || false}
                    onChange={(checked) => updateData({ show_title: checked })}
                    label="Показувати назву поруч з лого"
                />
            </div>
            <div>
                <SectionTitle icon={<Crop size={16}/>}>Формат логотипу</SectionTitle>
                <div className="mb-5">
                      <ToggleSwitch 
                        label="Квадратне зображення (1:1)"
                        checked={data.aspectRatio === 1}
                        onChange={(val) => updateData({ aspectRatio: val ? 1 : null })}
                      />
                </div>
            </div>
            <div>
                <SectionTitle icon={<LayoutTemplate size={18}/>}>Розміщення та Стиль</SectionTitle>
                <div className="mb-5">
                    <ToggleSwitch 
                        checked={data.is_sticky || false}
                        onChange={(checked) => updateData({ is_sticky: checked })}
                        label="Закріпити при прокрутці"
                    />
                </div>
                <div className="mb-5">
                    <AlignmentControl 
                        label="Вирівнювання меню"
                        value={data.nav_alignment || 'right'}
                        onChange={(val) => updateData({ nav_alignment: val })}
                    />
                </div>
                <div className="mb-5">
                    <label style={commonStyles.label}>Тип відображення</label>
                    <ToggleGroup 
                        options={[
                            { value: 'text', label: 'Текст' },
                            { value: 'button', label: 'Кнопки' },
                        ]}
                        value={navStyle}
                        onChange={(val) => updateData({ nav_style: val })}
                    />
                </div>
                {navStyle === 'button' ? (
                    <div className="mb-5">
                        <label style={commonStyles.label}>Стиль кнопок меню</label>
                        <ButtonEditor 
                            data={data.buttonSettings || {}}
                            onChange={(val) => updateData({ buttonSettings: val })}
                            siteData={siteData}
                            showAlignment={false} 
                            hideLinks={true}      
                            hideIcons={true}
                            hideText={true}
                        />
                    </div>
                ) : (
                    <div className="mb-5">
                        <FontSelector 
                            label="Шрифт меню"
                            value={data.nav_fontFamily}
                            onChange={(val) => updateData({ nav_fontFamily: val })}
                            siteFonts={siteData?.theme_settings}
                        />
                    </div>
                )}
            </div>
            <div>
                <div className="flex items-center justify-between mb-3">
                    <SectionTitle icon={<List size={18}/>} style={{marginBottom: 0}}>Пункти меню</SectionTitle>
                    <span 
                        className={`
                            text-xs font-semibold px-2 py-0.5 rounded
                            ${isLimitReached ? 'text-(--platform-danger) bg-red-500/10' : 'text-(--platform-text-secondary) bg-(--platform-bg)'}
                        `}
                    >
                        {navItemsCount} / {MAX_NAV_ITEMS}
                    </span>
                </div>
                <div className="mb-3 p-2 bg-blue-500/10 text-(--platform-accent) rounded-md text-xs leading-snug">
                    <strong>Формат посилань:</strong>
                    <ul className="m-1 ml-4 p-0 list-disc">
                        <li><code className="bg-black/5 px-1 rounded">/page</code> - внутрішня сторінка</li>
                        <li><code className="bg-black/5 px-1 rounded">#blockId</code> - якір (скрол до блоку)</li>
                    </ul>
                </div>
                <div className="flex flex-col gap-3">
                    {data.nav_items && data.nav_items.map((item, idx) => (
                        <div key={item.id} className="relative bg-(--platform-card-bg) p-3 rounded-xl border border-(--platform-border-color) flex flex-col gap-3 transition-all hover:border-(--platform-accent)/40">
                            <div className="flex items-center justify-between">
                                <span className="text-xs font-semibold uppercase tracking-wide text-(--platform-text-secondary) flex items-center gap-1.5">
                                    <List size={14} /> Пункт {idx + 1}
                                </span>
                                <button
                                    type="button"
                                    onClick={() => requestDelete(item.id)}
                                    className="text-(--platform-text-secondary) hover:text-(--platform-danger) hover:bg-red-500/10 p-1.5 rounded-md transition-colors"
                                    title="Видалити"
                                >
                                    <Trash2 size={14} />
                                </button>
                            </div>
                            <div className="flex flex-col gap-2">
                                <Input 
                                    value={item.label} 
                                    onChange={(e) => handleNavItemChange(item.id, 'label', e.target.value)}
                                    placeholder="Назва"
                                    leftIcon={<Pencil size={14}/>}
                                />
                                <Input 
                                    value={item.link} 
                                    onChange={(e) => handleNavItemChange(item.id, 'link', e.target.value)}
                                    placeholder="/page"
                                    leftIcon={<LinkIcon size={14}/>}
                                    style={{fontFamily: 'monospace'}}
                                />
                            </div>
                        </div>
                    ))}
                </div>
                <Button 
                    variant="outline"
                    onClick={addNavItem}
                    disabled={isLimitReached}
                    className={`
                        w-full mt-2 transition-opacity
                        ${isLimitReached ? 'border-(--platform-border-color) text-(--platform-text-secondary) opacity-60 cursor-not-allowed' : 'border-(--platform-accent) text-(--platform-accent) cursor-pointer'}
                    `}
                    icon={<Plus size={16} />}
                >
                    {isLimitReached ? 'Ліміт досягнуто' : 'Додати пункт меню'}
                </Button>
            </div>
        </div>
    );
};

export default HeaderSettings;

// frontend/src/modules/editor/blocks/Hero/HeroBlock.jsx
import React, { useRef, useEffect } from 'react';
import { useBlockFonts } from '../../../../shared/hooks/useBlockFonts';
import ButtonBlock from '../Button/ButtonBlock'; 
import { BASE_URL } from '../../../../shared/config';
import { areBlockPropsEqual } from '../../core/blockProps';

const HeroBlock = ({ blockData = {}, siteData, isEditorPreview, style }) => {
    const { 
        bg_type = 'image',
        bg_image, 
        bg_video,
        title, 
        subtitle, 
        button_text, 
        button_link,
        button = {}, 
        alignment = 'middle-center', 
        height = 'medium', 
        styles = {}, 
        titleFontFamily, 
        contentFontFamily,
        theme_mode = 'auto', 
        overlay_opacity,
        overlay_color = '#000000',
        show_title = true,
        show_subtitle = true,
        show_button = true,
    } = blockData || {};

    const { styles: fontStyles, RenderFonts, cssVariables } = useBlockFonts({
        title: titleFontFamily,
        content: contentFontFamily
    }, siteData);
    
    const videoRef = useRef(null);
    const safeOpacity = (overlay_opacity === undefined || isNaN(Number(overlay_opacity))) 
        ? 0.5 : Number(overlay_opacity);
        
    const getTextColor = () => {
        if (theme_mode === 'dark') return '#ffffff';
        if (theme_mode === 'light') return 'var(--site-text-primary, #000000)';
        return 'var(--site-text-primary)'; 
    };
    const computedTextColor = getTextColor();
    const computedTextShadow = theme_mode === 'dark' ? '0 2px 8px rgba(0,0,0,0.6)' : 'none';
    const fullImageUrl = bg_image 
        ? (bg_image.startsWith('http') ? bg_image : `${BASE_URL}${bg_image}`)
        : null;
    const fullVideoUrl = bg_video 
        ? (bg_video.startsWith('http') ? bg_video : `${BASE_URL}${bg_video}`)
        : null;
    useEffect(() => {
        const video = videoRef.current;
        if (video && bg_type === 'video') {
            video.play().catch(e => console.error("Autoplay failed", e));
        }
    }, [bg_type, fullVideoUrl]);
    const heightClasses = { 
        small: 'min-h-[300px]',
        medium: 'min-h-[400px] @3xl:min-h-[500px]',
        large: 'min-h-[600px] @3xl:min-h-[700px]',
        full: 'min-h-[calc(100vh-60px)]'
    };

    const alignClassesMap = {
        'left': { outer: 'justify-start items-center', inner: 'items-start text-left', btn: 'justify-start' },
        'center': { outer: 'justify-center items-center', inner: 'items-center text-center', btn: 'justify-center' },
        'right': { outer: 'justify-end items-center', inner: 'items-end text-right', btn: 'justify-end' },
        'top-left': { outer: 'justify-start items-start', inner: 'items-start text-left', btn: 'justify-start' },
        'top-center': { outer: 'justify-center items-start', inner: 'items-center text-center', btn: 'justify-center' },
        'top-right': { outer: 'justify-end items-start', inner: 'items-end text-right', btn: 'justify-end' },
        'middle-left': { outer: 'justify-start items-center', inner: 'items-start text-left', btn: 'justify-start' },
        'middle-center': { outer: 'justify-center items-center', inner: 'items-center text-center', btn: 'justify-center' },
        'middle-right': { outer: 'justify-end items-center', inner: 'items-end text-right', btn: 'justify-end' },
        'bottom-left': { outer: 'justify-start items-end', inner: 'items-start text-left', btn: 'justify-start' },
        'bottom-center': { outer: 'justify-center items-end', inner: 'items-center text-center', btn: 'justify-center' },
        'bottom-right': { outer: 'justify-end items-end', inner: 'items-end text-right', btn: 'justify-end' }
    };

    const currentAlign = alignClassesMap[alignment] || alignClassesMap['middle-center'];
    const resolvedButtonData = {
        text: button.text || button_text,
        link: button.link || button_link,
        size: button.size || 'large', 
        styleType: button.styleType || 'primary',
        variant: button.variant || 'solid',
        targetBlank: button.targetBlank,
        icon: button.icon,
        iconPosition: button.iconPosition,
        iconFlip: button.iconFlip,
        borderRadius: button.borderRadius,
        fontFamily: button.fontFamily || contentFontFamily, 
        width: button.width || 'auto',
        theme_mode: theme_mode,
        height: 'auto' 
    };

    const uniqueClass = `hero-scope-${(blockData && blockData.id) ? blockData.id : 'preview'}`;
    const isTransparent = overlay_color === 'transparent';
    return (
        <div 
            style={{ 
                ...styles,
                ...style,
                backgroundColor: 'var(--site-bg)', 
                color: computedTextColor,
                ...cssVariables
            }}
            className={`
                relative w-full flex box-border overflow-hidden
                ${heightClasses[height] || heightClasses.medium}
                ${currentAlign.outer}
                ${uniqueClass}
            `}
            id={blockData.anchorId}
        >
            <RenderFonts />
            <div className="absolute inset-0 z-0 bg-(--site-bg)">
                {bg_type === 'video' && fullVideoUrl ? (
                    <video 
                        ref={videoRef} 
                        src={fullVideoUrl} 
                        poster={fullImageUrl}
                        autoPlay 
                        muted 
                        loop 
                        playsInline
                        className="w-full h-full object-cover"
                    />
                ) : fullImageUrl ? (
                    <div 
                        className="w-full h-full bg-cover bg-center"
                        style={{ backgroundImage: `url(${fullImageUrl})` }} 
                    />
                ) : null}
            </div>
            
            {!isTransparent && (
                <div
                    className="absolute inset-0 z-1 transition-all duration-300 pointer-events-none"
                    style={{ backgroundColor: overlay_color, opacity: safeOpacity }}
                ></div>
            )}
            
            <div
                className={`
                    relative z-2 w-full text-inherit flex flex-col max-w-300 mx-auto
                    px-6 py-12 @2xl:px-8 @2xl:py-16 @3xl:px-12 @3xl:py-24
                    ${currentAlign.inner}
                `}
            >
                {show_title && title && (
                    <h1 
                        className="m-0 mb-4 @2xl:mb-6 font-extrabold leading-[1.15] tracking-tight text-inherit w-full text-4xl @2xl:text-5xl @3xl:text-6xl @5xl:text-7xl"
                        style={{ 
                            fontFamily: fontStyles.title, 
                            textShadow: computedTextShadow
                        }}
                    >
                        {title}
                    </h1>
                )}
                {show_subtitle && subtitle && (
                    <p 
                        className="m-0 mb-8 @2xl:mb-10 opacity-90 leading-[1.6] text-inherit w-full max-w-3xl whitespace-pre-wrap text-base @2xl:text-lg @3xl:text-xl"
                        style={{ 
                            fontFamily: fontStyles.content,
                            textShadow: computedTextShadow, 
                        }}
                    >
                        {subtitle}
                    </p>
                )}
                {show_button && resolvedButtonData.text && (
                    <div className={`w-full flex mt-2 @2xl:mt-4 ${currentAlign.btn}`}>
                        <ButtonBlock 
                            blockData={resolvedButtonData} 
                            siteData={siteData} 
                            isEditorPreview={isEditorPreview}
                            style={{ 
                                backgroundColor: 'transparent',
                                minHeight: 'auto',
                                padding: 0,
                                width: 'auto'
                            }}
                        />
                    </div>
                )}
            </div>
        </div>
    );
};

export default React.memo(HeroBlock, areBlockPropsEqual);

// frontend/src/modules/editor/blocks/Hero/HeroSettings.jsx
import React, { useState, useEffect } from 'react';
import { commonStyles, ToggleGroup, SectionTitle } from '../../ui/configuration/SettingsUI';
import { Input } from '../../../../shared/ui/elements/Input';
import AlignmentControl from '../../ui/components/AlignmentControl';
import FontSelector from '../../ui/components/FontSelector';
import OverlayControl from '../../ui/components/OverlayControl';
import ButtonEditor from '../../ui/components/ButtonEditor';
import UniversalMediaInput from '../../../../shared/ui/complex/UniversalMediaInput';
import { BASE_URL } from '../../../../shared/config';
import { Image, Video, Moon, Sun, Type, Palette, MousePointerClick, ImageIcon, Eye } from 'lucide-react';

const SwitchControl = ({ label, checked, onChange }) => (
    <div 
        className="flex items-center justify-between cursor-pointer group py-2"
        onClick={() => onChange(!checked)}
    >
        <span className="text-sm font-medium text-(--platform-text-primary) transition-colors">{label}</span>
        <div className={`relative inline-flex h-5 w-9 items-center rounded-full transition-colors duration-200 ease-in-out ${checked ? 'bg-(--platform-accent)' : 'bg-black/20 dark:bg-white/20'}`}>
            <span className={`inline-block h-3.5 w-3.5 transform rounded-full bg-white transition duration-200 ease-in-out shadow-sm ${checked ? 'translate-x-4.5' : 'translate-x-1'}`} />
        </div>
    </div>
);

const HeroSettings = ({ data, onChange, siteData }) => {
    const safeData = {
        bg_type: data.bg_type || 'image',
        bg_image: data.bg_image || data.imageUrl || '',
        bg_video: data.bg_video || '',
        overlay_color: data.overlay_color || '#000000', 
        title: data.title || '',
        subtitle: data.subtitle || '',
        alignment: data.alignment || 'middle-center',
        height: data.height || 'medium',
        titleFontFamily: data.titleFontFamily || 'global',
        contentFontFamily: data.contentFontFamily || 'global',
        theme_mode: data.theme_mode || 'light',
        overlay_opacity: (data.overlay_opacity !== undefined && !isNaN(data.overlay_opacity)) ? parseFloat(data.overlay_opacity) : 0.5,
        show_title: data.show_title !== false, 
        show_subtitle: data.show_subtitle !== false,
        show_button: data.show_button !== false,
        button: data.button || {
            text: data.button_text || '',
            link: data.button_link || '',
            styleType: 'primary',
            size: 'large',
            variant: 'solid'
        },
        ...data
    };

    const themeSettings = siteData?.theme_settings || {};
    const currentSiteFonts = {
        heading: themeSettings.font_heading,
        body: themeSettings.font_body
    };
    
    const [localTitle, setLocalTitle] = useState(safeData.title);
    const [localSubtitle, setLocalSubtitle] = useState(safeData.subtitle);
    useEffect(() => {
        setLocalTitle(safeData.title);
        setLocalSubtitle(safeData.subtitle);
    }, [safeData.title, safeData.subtitle]);

    const handleChange = (name, value) => {
        onChange({ ...safeData, [name]: value }, true);
    };

    const handleTitleBlur = () => {
        onChange({ ...safeData, title: localTitle }, true);
    };

    const handleSubtitleBlur = () => {
        onChange({ ...safeData, subtitle: localSubtitle }, true);
    };

    const handleButtonChange = (newButtonData) => {
        onChange({ 
            ...safeData, 
            button: newButtonData,
            button_text: newButtonData.text, 
            button_link: newButtonData.link
        }, true);
    };

    const handleImageChange = (val) => {
        let finalUrl = '';
        if (val && val.target && typeof val.target.value === 'string') {
            finalUrl = val.target.value;
        } else if (typeof val === 'string') {
            finalUrl = val;
        }
        const relativeUrl = finalUrl.replace(BASE_URL, '');
        onChange({ ...safeData, bg_image: relativeUrl }, true);
    };

    const handleVideoChange = (val) => {
        let finalUrl = '';
        if (val && val.target && typeof val.target.value === 'string') {
            finalUrl = val.target.value;
        } else if (typeof val === 'string') {
            finalUrl = val;
        }
        const relativeUrl = finalUrl.replace(BASE_URL, '');
        onChange({ ...safeData, bg_video: relativeUrl }, true);
    };

    const bgTypeOptions = [
        { value: 'image', label: <div className="flex items-center justify-center w-full gap-1.5"><Image size={16}/> Фото</div> },
        { value: 'video', label: <div className="flex items-center justify-center w-full gap-1.5"><Video size={16}/> Відео</div> }
    ];

    const themeOptions = [
        { value: 'light', label: <div className="flex items-center justify-center w-full gap-1.5"><Sun size={16}/> Світла</div>, title: 'Темний текст на світлому' },
        { value: 'dark', label: <div className="flex items-center justify-center w-full gap-1.5"><Moon size={16}/> Темна</div>, title: 'Світлий текст на темному' },
    ];

    return (
        <div className="flex flex-col gap-6"> 
            <div>
                <SectionTitle icon={<Eye size={18}/>}>Відображення елементів</SectionTitle>
                <div className="flex flex-col gap-0.5">
                    <SwitchControl 
                        label="Заголовок" 
                        checked={safeData.show_title} 
                        onChange={(val) => handleChange('show_title', val)} 
                    />
                    <div className="h-px bg-(--platform-border-color) opacity-30 my-1" />
                    <SwitchControl 
                        label="Підзаголовок" 
                        checked={safeData.show_subtitle} 
                        onChange={(val) => handleChange('show_subtitle', val)} 
                    />
                    <div className="h-px bg-(--platform-border-color) opacity-30 my-1" />
                    <SwitchControl 
                        label="Кнопка дії" 
                        checked={safeData.show_button} 
                        onChange={(val) => handleChange('show_button', val)} 
                    />
                </div>
            </div>
            <div>
                <SectionTitle icon={<Palette size={18}/>}>Фон блоку</SectionTitle>
                <div className="mb-5">
                    <label style={commonStyles.label}>Тип фону</label>
                    <ToggleGroup 
                        options={bgTypeOptions}
                        value={safeData.bg_type}
                        onChange={(val) => handleChange('bg_type', val)}
                    />
                </div>
                {safeData.bg_type === 'image' && (
                    <div className="mb-5">
                        <label style={commonStyles.label}>Зображення</label>
                        <div className="h-50">
                            <UniversalMediaInput 
                                type="image"
                                value={safeData.bg_image}
                                onChange={handleImageChange}
                                aspect={16/9}
                            />
                        </div>
                    </div>
                )}
                {safeData.bg_type === 'video' && (
                    <>
                        <div className="mb-5">
                            <label style={commonStyles.label}>Відео файл</label>
                            <div className="h-37.5 mb-2">
                                <UniversalMediaInput 
                                    type="video"
                                    value={safeData.bg_video}
                                    onChange={handleVideoChange}
                                    placeholder="Завантажити відео"
                                />
                            </div>
                        </div>
                        <div className="mb-5">
                            <label className="flex items-center gap-1.5 mb-1.5 font-medium text-sm text-(--platform-text-primary)">
                                <ImageIcon size={14} />
                                Обкладинка
                            </label>
                            <div className="h-37.5">
                                <UniversalMediaInput 
                                    type="image"
                                    value={safeData.bg_image}
                                    onChange={handleImageChange}
                                    aspect={16/9}
                                />
                            </div>
                        </div>
                    </>
                )}
                <div className="mb-5">
                    <label style={commonStyles.label}>Контраст тексту</label>
                    <ToggleGroup 
                        options={themeOptions}
                        value={safeData.theme_mode}
                        onChange={(val) => handleChange('theme_mode', val)}
                    />
                </div>
                <OverlayControl 
                    color={safeData.overlay_color}
                    opacity={safeData.overlay_opacity}
                    onColorChange={(val) => handleChange('overlay_color', val)}
                    onOpacityChange={(val) => onChange({ ...safeData, overlay_opacity: val }, false)}
                />
            </div>
            <div>
                <SectionTitle icon={<Type size={18}/>}>Вміст</SectionTitle>
                <div className={`transition-all duration-300 ${!safeData.show_title ? 'opacity-40 pointer-events-none grayscale' : ''}`}>
                    <div className="mb-5">
                        <FontSelector 
                            value={safeData.titleFontFamily}
                            onChange={(val) => handleChange('titleFontFamily', val)}
                            label="Шрифт заголовка"
                            siteFonts={currentSiteFonts}
                        />
                    </div>
                    <div className="mb-5">
                        <Input 
                            label="Заголовок"
                            type="text" 
                            name="title" 
                            value={localTitle}
                            onChange={(e) => setLocalTitle(e.target.value)} 
                            onBlur={handleTitleBlur}
                            placeholder="Головний заголовок"
                        />
                    </div>
                </div>
                <div className={`transition-all duration-300 ${!safeData.show_subtitle ? 'opacity-40 pointer-events-none grayscale' : ''}`}>
                    <div className="mb-5">
                        <FontSelector 
                            value={safeData.contentFontFamily}
                            onChange={(val) => handleChange('contentFontFamily', val)}
                            label="Шрифт тексту"
                            siteFonts={currentSiteFonts}
                        />
                    </div>
                    <div className="mb-5">
                        <label style={commonStyles.label}>Підзаголовок</label>
                        <textarea 
                            name="subtitle"
                            className="custom-scrollbar custom-input min-h-20 max-h-50 h-25 resize-y overflow-y-auto"
                            value={localSubtitle}
                            onChange={(e) => setLocalSubtitle(e.target.value)} 
                            onBlur={handleSubtitleBlur}
                            placeholder="Короткий опис або слоган"
                        />
                    </div>
                </div>
                <div className="mb-5">
                    <label style={commonStyles.label}>Вирівнювання контенту</label>
                    <AlignmentControl 
                        value={safeData.alignment}
                        onChange={(val) => handleChange('alignment', val)}
                        gridMode={true}
                    />
                </div>
            </div>
            <div className={`transition-all duration-300 ${!safeData.show_button ? 'opacity-40 pointer-events-none grayscale' : ''}`}>
                <SectionTitle icon={<MousePointerClick size={18}/>}>Кнопка дії</SectionTitle>
                <ButtonEditor 
                    data={safeData.button}
                    onChange={handleButtonChange}
                    siteData={siteData}
                    showAlignment={false} 
                />
            </div>
        </div>
    );
};

export default HeroSettings;

// frontend/src/modules/editor/blocks/Image/ImageBlock.jsx
import React from 'react';
import { Swiper, SwiperSlide } from 'swiper/react';
import { Navigation, Pagination, Autoplay } from 'swiper/modules';
import 'swiper/css';
import 'swiper/css/navigation';
import 'swiper/css/pagination';
import { resolveSiteLink } from '../../../../shared/utils/linkUtils';
import { BASE_URL } from '../../../../shared/config';
import { Image as ImageIcon } from 'lucide-react';
import { areBlockPropsEqual } from '../../core/blockProps';

const formatBorderRadius = (radius) => {
    if (!radius) return '0px';
    return String(radius).match(/^[0-9]+$/) ? `${radius}px` : radius;
};

const getFlexItemClass = (cols) => {
    const safeCols = parseInt(cols) || 3;
    if (safeCols === 1) return 'w-full';
    if (safeCols === 2) return 'w-full @2xl:w-[calc(50%-8px)]';
    if (safeCols === 3) return 'w-full @2xl:w-[calc(50%-8px)] @3xl:w-[calc(33.333%-10.66px)]';
    if (safeCols >= 4) return 'w-full @2xl:w-[calc(50%-8px)] @3xl:w-[calc(33.333%-10.66px)] @5xl:w-[calc(25%-12px)]';
    return 'w-full @2xl:w-[calc(50%-8px)] @3xl:w-[calc(33.333%-10.66px)]';
};

const ImageBlock = ({ blockData, isEditorPreview, siteData, style }) => {
    const { 
        objectFit = 'contain',
        borderRadius = '0px', 
        link, 
        targetBlank,
        width = 'medium',
        height = 'auto', 
        mode = 'single',
        items = [],
        styles = {}
    } = blockData;
    
    const effectiveItems = (blockData.imageUrl && items.length === 0) 
        ? [{ id: 'legacy', src: blockData.imageUrl }] 
        : items;
    const settings_slider = blockData.settings_slider || { navigation: true, pagination: true, autoplay: false, loop: true };
    const settings_grid = { columns: 3, alignment: 'center', ...blockData.settings_grid };
    const heightClasses = {
        small: 'h-[250px] @2xl:h-[300px]',
        medium: 'h-[300px] @2xl:h-[400px] @3xl:h-[500px]',
        large: 'h-[400px] @2xl:h-[500px] @3xl:h-[700px]',
        full: 'h-[calc(100vh-80px)]', 
        auto: 'h-auto'
    };
    
    const currentHeightClass = heightClasses[height] || heightClasses.auto;
    const isFixedHeight = height !== 'auto';
    const renderImage = (item, customStyle = {}) => {
        if (!item || !item.src) return null;
        const fullUrl = item.src.startsWith('http') ? item.src : `${BASE_URL}${item.src}`;
        return (
            <img 
                src={fullUrl} 
                alt={item.alt || ''} 
                className="w-full h-full block transition-opacity duration-300"
                style={{ 
                    objectFit: isFixedHeight ? (objectFit === 'contain' ? 'contain' : 'cover') : objectFit,
                    borderRadius: formatBorderRadius(borderRadius),
                    ...customStyle
                }} 
                loading="lazy"
            />
        );
    };

    const Placeholder = () => (
        <div 
            className="p-8 @2xl:p-12 text-center bg-(--site-card-bg) border border-dashed border-(--site-border-color) text-(--site-text-secondary) flex flex-col items-center justify-center gap-3 w-full"
            style={{
                borderRadius: formatBorderRadius(borderRadius),
                height: isFixedHeight ? '100%' : '200px'
            }}
        >
            <div className="opacity-40 text-(--site-text-primary)">
                <ImageIcon size={48} className="@2xl:w-16 @2xl:h-16" />
            </div>
            <div className="text-sm font-medium">
                Зображення не вибрано
            </div>
        </div>
    );

    const renderSingle = () => {
        const item = effectiveItems[0];
        if (!item?.src) return isEditorPreview ? <Placeholder /> : null;
        const content = renderImage(item, { height: '100%' });
        if (link && !isEditorPreview) {
            const finalLink = resolveSiteLink(link, siteData?.site_path);
            return (
                <a 
                    href={finalLink} 
                    target={targetBlank ? '_blank' : '_self'} 
                    rel={targetBlank ? 'noopener noreferrer' : ''}
                    className="block w-full h-full hover:opacity-90 transition-opacity"
                >
                    {content}
                </a>
            );
        }
        return <div className="w-full h-full">{content}</div>;
    };

    const renderSlider = () => {
        if (effectiveItems.length === 0) return renderSingle();
        return (
            <div className={`swiper-container-wrapper my-block-swiper-${blockData.block_id || 'preview'} h-full w-full`}>
                <style>{`
                    .my-block-swiper-${blockData.block_id || 'preview'} .swiper-button-next,
                    .my-block-swiper-${blockData.block_id || 'preview'} .swiper-button-prev { 
                        color: var(--site-accent); 
                        transform: scale(0.7);
                    }
                    @container (min-width: 672px) {
                        .my-block-swiper-${blockData.block_id || 'preview'} .swiper-button-next,
                        .my-block-swiper-${blockData.block_id || 'preview'} .swiper-button-prev { transform: scale(1); }
                    }
                    .my-block-swiper-${blockData.block_id || 'preview'} .swiper-pagination-bullet-active { background: var(--site-accent); }
                    .my-block-swiper-${blockData.block_id || 'preview'} .swiper { height: 100%; width: 100%; }
                `}</style>
                <Swiper
                    modules={[Navigation, Pagination, Autoplay]}
                    navigation={settings_slider.navigation}
                    pagination={settings_slider.pagination ? { clickable: true } : false}
                    loop={settings_slider.loop && effectiveItems.length > 1}
                    autoplay={settings_slider.autoplay ? { delay: 3000, disableOnInteraction: false } : false}
                    className="overflow-hidden h-full w-full"
                    style={{ borderRadius: formatBorderRadius(borderRadius) }}
                >
                    {effectiveItems.map((item, idx) => (
                        <SwiperSlide key={item.id || idx} className="h-full w-full">
                            <div 
                                className="w-full flex justify-center items-center"
                                style={{ 
                                    height: isFixedHeight ? '100%' : 'auto',
                                    aspectRatio: isFixedHeight ? 'auto' : '16 / 9',
                                }}
                            >
                                {renderImage(item)}
                            </div>
                        </SwiperSlide>
                    ))}
                </Swiper>
            </div>
        );
    };

    const renderGrid = () => {
        if (effectiveItems.length === 0) return renderSingle();
        const cols = settings_grid.columns || 3;
        const gridAlignClass = settings_grid.alignment === 'left' ? 'justify-start' :
                               settings_grid.alignment === 'right' ? 'justify-end' : 
                               'justify-center';
        return (
            <div 
                className={`flex flex-wrap gap-2 @2xl:gap-4 w-full ${gridAlignClass}`}
                style={{ 
                    height: isFixedHeight ? '100%' : 'auto', 
                    alignContent: isFixedHeight ? 'center' : 'flex-start' 
                }}
            >
                {effectiveItems.map((item, idx) => (
                    <div 
                        key={item.id || idx} 
                        className={`overflow-hidden flex justify-center items-center shrink-0 ${getFlexItemClass(cols)}`}
                        style={{ 
                            height: cols === 1 ? (isFixedHeight ? '100%' : 'auto') : 'auto',
                            aspectRatio: cols === 1 ? 'auto' : '1 / 1', 
                            borderRadius: formatBorderRadius(borderRadius),
                        }}
                    >
                        {renderImage(item, { 
                            objectFit: (cols === 1 && !isFixedHeight) ? 'contain' : 'cover', 
                            height: '100%' 
                        })}
                    </div>
                ))}
            </div>
        );
    };

    const widthClasses = { 
        'small': 'max-w-full @2xl:max-w-[400px]', 
        'medium': 'max-w-full @2xl:max-w-[700px]', 
        'large': 'max-w-full @5xl:max-w-[1000px]', 
        'full': 'max-w-full' 
    };

    const blockAlignment = mode === 'grid' ? settings_grid.alignment : 'center';
    const alignClass = blockAlignment === 'left' ? 'items-start' : 
                       blockAlignment === 'right' ? 'items-end' : 
                       'items-center';
    return (
        <div 
            className={`
                w-full flex flex-col justify-center px-4 @2xl:px-6 @3xl:px-8 py-4
                ${alignClass}
                ${isFixedHeight ? 'min-h-0' : 'min-h-auto'}
                ${currentHeightClass}
            `}
            style={{ 
                height: isFixedHeight ? undefined : 'auto',
                ...styles,
                ...style
            }}
        >
            <div 
                className={`
                    w-full flex flex-col justify-center
                    ${widthClasses[width] || widthClasses.medium}
                    ${isFixedHeight ? 'h-full flex-1' : 'h-auto flex-none'}
                `}
            >
                {mode === 'slider' ? renderSlider() : mode === 'grid' ? renderGrid() : renderSingle()}
            </div>
        </div>
    );
};

export default React.memo(ImageBlock, areBlockPropsEqual);

// frontend/src/modules/editor/blocks/Image/ImageSettings.jsx
import React from 'react';
import { generateBlockId } from '../../core/editorConfig';
import CustomSelect from '../../../../shared/ui/elements/CustomSelect';
import { commonStyles, ToggleGroup, ToggleSwitch, SectionTitle } from '../../ui/configuration/SettingsUI';
import RangeSlider from '../../../../shared/ui/elements/RangeSlider';
import UniversalMediaInput from '../../../../shared/ui/complex/UniversalMediaInput';
import AlignmentControl from '../../ui/components/AlignmentControl'; 
import { Image, Grid, Play, Link, Settings, Plus, Crop, ChevronUp, ChevronDown } from 'lucide-react';

const ImageSettings = ({ data, onChange }) => {
    const normalizedData = {
        mode: data.mode || 'single',
        items: Array.isArray(data.items) ? data.items : [],
        settings_slider: data.settings_slider || { navigation: true, pagination: true, autoplay: false, loop: true },
        settings_grid: { columns: 3, alignment: 'center', ...data.settings_grid },
        objectFit: data.objectFit || 'cover',
        borderRadius: data.borderRadius || '0px',
        link: data.link || '',
        targetBlank: data.targetBlank || false,
        aspectRatio: data.aspectRatio === 1 ? 1 : null 
    };

    const updateData = (updates) => onChange({ ...normalizedData, ...updates });
    const handleItemChange = (index, val) => {
        const newValue = val?.target ? val.target.value : val;
        const newItems = [...normalizedData.items];
        if (!newValue) {
            newItems.splice(index, 1);
        } else {
            newItems[index] = { ...newItems[index], src: newValue };
        }
        updateData({ items: newItems });
    };

    const handleAddItem = (val) => {
        const newValue = val?.target ? val.target.value : val;
        if (!newValue) return;
        const newItem = { id: generateBlockId(), src: newValue };
        const newItems = normalizedData.mode === 'single' 
            ? [newItem] 
            : [...normalizedData.items, newItem];
        updateData({ items: newItems });
    };

    const moveItem = (index, direction) => {
        const newItems = [...normalizedData.items];
        if (direction === 'up' && index > 0) {
            [newItems[index - 1], newItems[index]] = [newItems[index], newItems[index - 1]];
            updateData({ items: newItems });
        } else if (direction === 'down' && index < newItems.length - 1) {
            [newItems[index + 1], newItems[index]] = [newItems[index], newItems[index + 1]];
            updateData({ items: newItems });
        }
    };

    const currentAspect = normalizedData.aspectRatio;
    return (
        <div className="flex flex-col gap-5">
            <ToggleGroup 
                options={[
                    { value: 'single', label: 'Одне', icon: <Image size={16} /> },
                    { value: 'slider', label: 'Слайдер', icon: <Play size={16} /> },
                    { value: 'grid', label: 'Сітка', icon: <Grid size={16} /> },
                ]}
                value={normalizedData.mode}
                onChange={(val) => updateData({ mode: val })}
            />
            <div className="bg-(--platform-bg) p-3 rounded-xl border border-(--platform-border-color)">
                {normalizedData.mode === 'single' ? (
                    <div className="w-full h-50">
                        <UniversalMediaInput 
                            type="image"
                            value={normalizedData.items[0]?.src || ''}
                            onChange={(e) => {
                                if (normalizedData.items.length > 0) handleItemChange(0, e);
                                else handleAddItem(e);
                            }}
                            aspect={currentAspect}
                        />
                    </div>
                ) : (
                    <div className="flex flex-col gap-3">
                        {normalizedData.items.map((item, idx) => (
                            <div key={item.id || idx} className="flex gap-2 items-stretch bg-(--platform-card-bg) p-2 rounded-xl border border-(--platform-border-color) shadow-sm group">
                                <div className="flex flex-col justify-center gap-1 shrink-0">
                                    <button
                                        onClick={() => moveItem(idx, 'up')}
                                        disabled={idx === 0}
                                        className="p-1 text-(--platform-text-secondary) hover:text-(--platform-text-primary) hover:bg-black/5 dark:hover:bg-white/10 rounded-md disabled:opacity-30 disabled:cursor-not-allowed transition-colors"
                                        title="Підняти вище"
                                    >
                                        <ChevronUp size={16} />
                                    </button>
                                    <button
                                        onClick={() => moveItem(idx, 'down')}
                                        disabled={idx === normalizedData.items.length - 1}
                                        className="p-1 text-(--platform-text-secondary) hover:text-(--platform-text-primary) hover:bg-black/5 dark:hover:bg-white/10 rounded-md disabled:opacity-30 disabled:cursor-not-allowed transition-colors"
                                        title="Опустити нижче"
                                    >
                                        <ChevronDown size={16} />
                                    </button>
                                </div>
                                <div className="flex-1 h-28 relative rounded-lg overflow-hidden border border-black/5">
                                    <UniversalMediaInput 
                                        type="image"
                                        value={item.src}
                                        onChange={(e) => handleItemChange(idx, e)}
                                        aspect={currentAspect}
                                    />
                                    <div className="absolute top-1.5 left-1.5 bg-black/60 text-white text-[10px] font-bold px-1.5 py-0.5 rounded z-10 pointer-events-none backdrop-blur-sm">
                                        #{idx + 1}
                                    </div>
                                </div>
                            </div>
                        ))}
                        <UniversalMediaInput 
                            type="image" 
                            value="" 
                            onChange={handleAddItem} 
                            aspect={currentAspect}
                            triggerStyle={{ width: '100%', padding: 0, border: 'none', background: 'transparent' }}
                        >
                            <div className="w-full h-12 mt-1 rounded-xl border border-dashed border-(--platform-border-color) flex items-center justify-center cursor-pointer text-(--platform-text-secondary) bg-(--platform-card-bg) gap-2 transition-all duration-200 hover:border-(--platform-accent) hover:text-(--platform-accent) hover:bg-(--platform-accent)/5 shadow-sm">
                                <Plus size={18} />
                                <span className="text-sm font-medium">Додати зображення</span>
                            </div>
                        </UniversalMediaInput>
                    </div>
                )}
            </div>
            <div>
                <SectionTitle icon={<Crop size={16}/>}>Формат</SectionTitle>
                <div className="mb-5">
                      <ToggleSwitch 
                        label="Квадратне зображення (1:1)"
                        checked={normalizedData.aspectRatio === 1}
                        onChange={(val) => updateData({ aspectRatio: val ? 1 : null })}
                      />
                      <div className="text-xs text-(--platform-text-secondary) mt-1.5 leading-snug">
                        {normalizedData.aspectRatio === 1 
                            ? "При завантаженні буде запропоновано обрізати фото під квадрат." 
                            : "Зображення відображатиметься в оригінальних пропорціях."}
                      </div>
                </div>
            </div>
            {normalizedData.mode === 'slider' && (
                <div className="flex flex-col gap-2">
                    <SectionTitle icon={<Settings size={16}/>}>Налаштування слайдера</SectionTitle>
                    <ToggleSwitch checked={normalizedData.settings_slider.navigation} label="Стрілки" onChange={(v) => updateData({ settings_slider: {...normalizedData.settings_slider, navigation: v}})} />
                    <ToggleSwitch checked={normalizedData.settings_slider.autoplay} label="Автопрокрутка" onChange={(v) => updateData({ settings_slider: {...normalizedData.settings_slider, autoplay: v}})} />
                    <ToggleSwitch checked={normalizedData.settings_slider.loop} label="Зациклити" onChange={(v) => updateData({ settings_slider: {...normalizedData.settings_slider, loop: v}})} />
                </div>
            )}
            {normalizedData.mode === 'grid' && (
                <div className="flex flex-col gap-2">
                    <SectionTitle icon={<Grid size={16}/>}>Налаштування сітки</SectionTitle>
                    <div className="mb-5">
                         <label style={commonStyles.label}>Кількість колонок</label>
                         <CustomSelect 
                            value={normalizedData.settings_grid.columns}
                            onChange={(e) => updateData({ settings_grid: { ...normalizedData.settings_grid, columns: parseInt(e.target.value) } })}
                            options={[
                                { value: 1, label: '1 колонка' },
                                { value: 2, label: '2 колонки' },
                                { value: 3, label: '3 колонки' },
                                { value: 4, label: '4 колонки' },
                            ]}
                         />
                    </div>
                    <div className="mb-2">
                        <AlignmentControl 
                            label="Вирівнювання сітки"
                            value={normalizedData.settings_grid.alignment}
                            onChange={(val) => updateData({ settings_grid: { ...normalizedData.settings_grid, alignment: val } })}
                        />
                    </div>
                </div>
            )}
            <div>
                <SectionTitle icon={<Image size={16}/>}>Вигляд</SectionTitle>
                <div className="mb-5">
                    <RangeSlider 
                        label="Скруглення кутів"
                        value={normalizedData.borderRadius}
                        onChange={(val) => updateData({ borderRadius: val })}
                        min={0}
                        max={60}
                        unit="px"
                    />
                </div>
            </div>
            {normalizedData.mode === 'single' && (
                <div>
                    <SectionTitle icon={<Link size={16}/>}>Дія при кліку</SectionTitle>
                    <input 
                        type="text" 
                        value={normalizedData.link}
                        onChange={(e) => updateData({ link: e.target.value })}
                        style={commonStyles.input}
                        placeholder="https://..."
                    />
                </div>
            )}
        </div>
    );
};

export default ImageSettings;

// frontend/src/modules/editor/blocks/Layout/LayoutBlock.jsx
import React, { useRef, useEffect } from 'react';
import { useDrop } from 'react-dnd';
import { DND_TYPE_NEW_BLOCK } from '../../ui/DraggableBlockItem';
import { useBlockRenderer, useEditableBlock } from '../../core/blockComponents';
import { BASE_URL } from '../../../../shared/config';
import { Plus } from 'lucide-react';

const DRAG_ITEM_TYPE_EXISTING = 'BLOCK';
const getGridClasses = (direction = 'row', preset, verticalAlign = 'top') => {
    const verticalAlignMap = {
        top: 'items-start',
        middle: 'items-center',
        bottom: 'items-end',
        stretch: 'items-stretch'
    };
    const alignClass = verticalAlignMap[verticalAlign] || 'items-start';
    if (direction === 'column') {
        return `grid grid-cols-1 ${alignClass}`;
    }
    let colsClass = 'grid-cols-1 @3xl:grid-cols-2';
    switch (preset) {
        case '50-50': colsClass = 'grid-cols-1 @3xl:grid-cols-2'; break;
        case '75-25': colsClass = 'grid-cols-1 @3xl:grid-cols-[3fr_1fr]'; break;
        case '25-75': colsClass = 'grid-cols-1 @3xl:grid-cols-[1fr_3fr]'; break;
        case '33-33-33': colsClass = 'grid-cols-1 @3xl:grid-cols-3'; break;
        case '25-25-25-25': colsClass = 'grid-cols-1 @2xl:grid-cols-2 @5xl:grid-cols-4'; break; 
        default: colsClass = 'grid-cols-1 @3xl:grid-cols-2';
    }
    return `grid w-full ${colsClass} ${alignClass}`;
};

const ColumnDropZone = ({ children, onDrop, path, isEditorPreview, onAddBlock, viewMode = 'editor' }) => {
    const isActuallyEditing = isEditorPreview && viewMode === 'editor';
    const [{ isOver, canDrop }, drop] = useDrop({
        accept: [DRAG_ITEM_TYPE_EXISTING, DND_TYPE_NEW_BLOCK],
        drop: (item, monitor) => {
            if (monitor.didDrop()) return;
            const dragType = monitor.getItemType();
            if (dragType === DRAG_ITEM_TYPE_EXISTING) {
                const dragPath = item.path;
                const dropZonePath = path;
                const isDroppingOnSelf = dropZonePath.join(',').startsWith(dragPath.join(',')) &&
                                         dropZonePath.length > dragPath.length;
                if (isDroppingOnSelf) return;
                onDrop(item, path);
            } else if (dragType === DND_TYPE_NEW_BLOCK) {
                const newBlockPath = [...path, React.Children.count(children)];
                onAddBlock(newBlockPath, item.blockType, item.presetData);
            }
            return { name: 'ColumnDropZone', path };
        },
        canDrop: () => isActuallyEditing,
        collect: (monitor) => ({
            isOver: monitor.isOver(),
            canDrop: monitor.canDrop(),
        }),
    });

    const isActive = isOver && canDrop;
    return (
        <div 
            ref={drop} 
            className={`
                layout-drop-zone
                min-h-25 p-2.5 rounded-lg w-full box-border flex flex-col relative transition-colors duration-200
                ${isActive ? 'border-2 border-dashed border-(--platform-accent) bg-blue-500/5' : `border border-dashed ${isActuallyEditing ? 'border-(--platform-border-color)' : 'border-transparent'}`}
            `}
        >
            <div className="flex-1 w-full flex flex-col">
                {children}
                {isActuallyEditing && React.Children.count(children) === 0 && (
                    <div className="layout-empty-placeholder flex flex-col items-center justify-center h-25 text-(--platform-text-secondary) opacity-60 pointer-events-none">
                        <div className="w-8 h-8 rounded-full border border-(--platform-border-color) flex items-center justify-center mb-1.5 bg-(--platform-bg)">
                            <Plus size={16} />
                        </div>
                        <span className="text-xs">Сюди блок</span>
                    </div>
                )}
            </div>
        </div>
    );
};

const LayoutBlock = ({ 
    block, 
    siteData, 
    isEditorPreview, 
    path = [], 
    viewMode = 'editor',
    onMoveBlock, 
    onDropBlock, 
    onDeleteBlock, 
    onSelectBlock, 
    selectedBlockPath,
    onAddBlock 
}) => {
    const { 
        preset, 
        columns = [], 
        direction = 'row', 
        verticalAlign = 'top', 
        gap = 20,
        height = 'auto', 
        styles = {},
        minHeight: legacyMinHeight,
        padding: legacyPadding = '20px',
        bg_type = 'none', 
        bg_color = 'transparent',
        bg_image,
        bg_video,
        overlay_color = '#000000',
        overlay_opacity = 0
    } = block.data;
    const BlockRenderer = useBlockRenderer();
    const EditableBlockWrapper = useEditableBlock();
    const videoRef = useRef(null);
    const heightClasses = { 
        small: 'min-h-[300px]',
        medium: 'min-h-[500px]',
        large: 'min-h-[700px]',
        full: 'min-h-[calc(100vh-60px)]',
        auto: 'min-h-auto'
    };
    const activeMinHeightClass = heightClasses[height] || (legacyMinHeight === 'screen' ? 'min-h-screen' : '') || 'min-h-auto';
    const activeMinHeightStyle = (!heightClasses[height] && legacyMinHeight !== 'screen' && legacyMinHeight) ? { minHeight: legacyMinHeight } : {};
    const fullImageUrl = bg_image 
        ? (bg_image.startsWith('http') ? bg_image : `${BASE_URL}${bg_image}`)
        : null;
    const fullVideoUrl = bg_video 
        ? (bg_video.startsWith('http') ? bg_video : `${BASE_URL}${bg_video}`)
        : null;
    useEffect(() => {
        if (videoRef.current && bg_type === 'video') {
            videoRef.current.play().catch(e => console.error("Autoplay failed", e));
        }
    }, [bg_type, fullVideoUrl]);
    const alignmentClass = activeMinHeightClass !== 'min-h-auto' 
        ? (verticalAlign === 'middle' ? 'justify-center' : (verticalAlign === 'bottom' ? 'justify-end' : 'justify-start'))
        : 'justify-start';
        
    const isActuallyEditing = isEditorPreview && viewMode === 'editor';
    const safePadding = legacyPadding === '20px' ? undefined : legacyPadding;
    return (
        <div 
            className={`
                relative flex flex-col overflow-hidden w-full
                ${safePadding === undefined ? 'px-4 py-8 @3xl:p-8' : ''}
                ${activeMinHeightClass}
                ${alignmentClass}
            `}
            style={{
                padding: safePadding,
                ...styles, 
                ...activeMinHeightStyle,
                backgroundColor: bg_type === 'color' ? bg_color : 'var(--site-bg, #f7fafc)',
            }}
            id={block.data.anchorId}
        >
            {bg_type === 'image' && fullImageUrl && (
                 <div 
                    className="absolute inset-0 z-0 bg-cover bg-center"
                    style={{ backgroundImage: `url(${fullImageUrl})` }} 
                />
            )}
