                {(data.bg_type === 'image' || data.bg_type === 'video') && (
                    <OverlayControl 
                        color={data.overlay_color || '#000000'}
                        opacity={data.overlay_opacity}
                        onColorChange={(val) => updateData({ overlay_color: val })}
