            <div>
                <SectionTitle icon={<Layout size={18}/>}>Макет</SectionTitle>
                <div className="mb-5">
                    <label style={commonStyles.label}>Схема колонок</label>
                    <CustomSelect
                        value={data.preset || '50-50'}
                        onChange={handlePresetChange}
