                    >
                        {title}
                    </h2>
                )}
                
                {loading ? (
                    <div className="flex justify-center items-center p-12 w-full">
                        <div className="w-8 h-8 border-4 border-(--site-accent) border-t-transparent rounded-full animate-spin"></div>
