import CustomSelect from '../../../../shared/ui/elements/CustomSelect';
import apiClient from '../../../../shared/api/api';
import AlignmentControl from '../../ui/components/AlignmentControl';
import FontSelector from '../../ui/components/FontSelector';
import { LayoutGrid, ShoppingBag, Type, List, Layers, } from 'lucide-react';

const ShowCaseSettings = ({ data, onChange, siteData }) => { 
    const [isPickerOpen, setIsPickerOpen] = useState(false);
    const [categories, setCategories] = useState([]);
    const [isLoadingCategories, setIsLoadingCategories] = useState(false);
    const themeSettings = siteData?.theme_settings || {};
    const currentSiteFonts = {
        heading: themeSettings.font_heading,
        body: themeSettings.font_body
    };
    const normalizedData = {
        title: '',
        columns: 4,
        source_type: 'category',
        category_id: 0,
        alignment: 'center',
        ...data
    };

    const updateData = (updates) => onChange({ ...normalizedData, ...updates });
    const handleProductSelection = (ids) => {
        updateData({ selected_product_ids: ids });
    };

    useEffect(() => {
        const fetchCategories = async () => {
            if (!siteData?.id) return;
            setIsLoadingCategories(true);
            try {
                const res = await apiClient.get(`/categories/site/${siteData.id}`);
                const options = [
                    { value: 0, label: 'Всі товари' },
                    ...res.data.map(cat => ({
                        value: cat.id,
                        label: cat.name
                    }))
                ];
                setCategories(options);
            } catch (error) {
                console.error("Failed to load categories", error);
                setCategories([{ value: 0, label: 'Помилка завантаження' }]);
            } finally {
                setIsLoadingCategories(false);
            }
        };

        fetchCategories();
    }, [siteData?.id]);

    return (
        <div className="flex flex-col gap-6">
            <ProductPickerModal 
                isOpen={isPickerOpen}
                onClose={() => setIsPickerOpen(false)}
                onSave={handleProductSelection}
                initialSelectedIds={normalizedData.selected_product_ids || []}
                siteId={siteData?.id}
            />
            <div>
                <SectionTitle icon={<Type size={18}/>}>Заголовок</SectionTitle>
                <div className="mb-5">
                    <Input 
                        value={normalizedData.title}
                        onChange={(e) => updateData({ title: e.target.value })}
                        placeholder="Наприклад: Новинки"
                    />
                </div>
                <div className="mb-5">
                    <FontSelector 
                        value={normalizedData.titleFontFamily}
                        onChange={(val) => updateData({ titleFontFamily: val })}
                        label="Шрифт заголовка"
                        siteFonts={currentSiteFonts}
                    />
                </div>
            </div>
            <div>
                <SectionTitle icon={<Layers size={18}/>}>Джерело товарів</SectionTitle>
                <div className="mb-5">
                    <label style={commonStyles.label}>Режим відображення</label>
                    <ToggleGroup 
                        options={[
                            { value: 'category', label: 'Категорія' },
                            { value: 'manual', label: 'Вручну' },
                        ]}
                        value={normalizedData.source_type}
                        onChange={(val) => updateData({ source_type: val })}
                    />
                </div>
                {normalizedData.source_type === 'manual' ? (
                    <div className="mb-5">
                        <div className="mb-3">
                            <Button 
                                variant="outline" 
                                className="w-full border-(--platform-accent) text-(--platform-accent)"
                                icon={<ShoppingBag size={16} />}
                                onClick={() => setIsPickerOpen(true)}
                            >
                                Обрати товари зі списку
                            </Button>
                        </div>
                        <small className="block text-center text-xs text-(--platform-text-secondary)">
                            {normalizedData.selected_product_ids?.length > 0 
                                ? `Обрано: ${normalizedData.selected_product_ids.length} шт.` 
                                : 'Товари не обрано'}
                        </small>
                    </div>
                ) : (
                    <div className="mb-5">
                        <label style={commonStyles.label}>Категорія</label>
                        <CustomSelect 
                            value={normalizedData.category_id}
                            onChange={(e) => updateData({ category_id: parseInt(e.target.value) })}
                            options={categories}
                            isLoading={isLoadingCategories}
                            leftIcon={<List size={16}/>}
                        />
                    </div>
                )}
                <div className="text-[0.8rem] text-(--platform-text-secondary) mt-2 p-3 bg-(--platform-bg) rounded-md border border-(--platform-border-color)">
                    * У блоці будуть відображатися перші <strong>20 товарів</strong> з вибраної категорії.
                </div>
            </div>
            <div>
                <SectionTitle icon={<LayoutGrid size={18}/>}>Вигляд сітки</SectionTitle>
                <div className="mb-5">
                    <AlignmentControl 
                        value={normalizedData.alignment}
                        onChange={(val) => updateData({ alignment: val })}
                        label="Вирівнювання заголовка"
                        showJustify={false}
                    />
                </div>
                <div className="mb-5">
                    <label style={commonStyles.label}>Кількість колонок</label>
                    <ToggleGroup 
                        options={[
                            { value: 2, label: '2' },
                            { value: 3, label: '3' },
                            { value: 4, label: '4' },
                            { value: 5, label: '5' },
                        ]}
                        value={normalizedData.columns}
                        onChange={(val) => updateData({ columns: val })}
                    />
                </div>
            </div>
        </div>
    );
};

export default ShowCaseSettings;

// frontend/src/modules/editor/blocks/SocialIcons/SocialIconsBlock.jsx
import React from 'react';
import { Facebook, Instagram, Send, Youtube, Music, Share2 } from 'lucide-react';
import { areBlockPropsEqual } from '../../core/blockProps';

const IconsMap = {
    facebook: Facebook,
    instagram: Instagram,
    telegram: Send,
    youtube: Youtube,
    tiktok: Music
};
const sanitizeUrl = (url) => {
    if (!url || typeof url !== 'string') return null;
    const trimmed = url.trim();
    if (trimmed.startsWith('http://') || trimmed.startsWith('https://') || trimmed.startsWith('mailto:')) {
        return trimmed;
    }
    if (!trimmed.startsWith('javascript:') && !trimmed.startsWith('data:')) {
        return `https://${trimmed}`;
    }
    return null;
};

const IconWrapper = ({ children, href, isEditorPreview, baseColor }) => (
    <a
        href={sanitizeUrl(href)}
        target="_blank"
        rel="noopener noreferrer"
        onClick={isEditorPreview ? (e) => e.preventDefault() : undefined}
        className="inline-flex items-center justify-center w-10 h-10 @2xl:w-12 @2xl:h-12 mx-1.5 my-1.5 @2xl:mx-2 no-underline transition-all duration-200 rounded-full hover:text-(--site-accent) hover:bg-black/5 dark:hover:bg-white/5 hover:-translate-y-1"
        style={{
            color: baseColor, 
            opacity: isEditorPreview ? 0.8 : 1, 
        }}
    >
        {children}
    </a>
);

const SocialIconsBlock = ({ blockData, isEditorPreview, style }) => {
    const { 
        alignment, 
        theme_mode = 'auto', 
        facebook, 
        instagram, 
        telegram, 
        youtube, 
        tiktok,
        height = 'auto'
    } = blockData;

    let baseColor = 'var(--site-text-primary)';
    if (theme_mode === 'light') baseColor = '#1a202c';
    if (theme_mode === 'dark') baseColor = '#ffffff';
    const socialLinks = [
        { key: 'facebook', href: facebook },
        { key: 'instagram', href: instagram },
        { key: 'telegram', href: telegram },
        { key: 'youtube', href: youtube },
        { key: 'tiktok', href: tiktok },
    ].filter(item => item.href && item.href.trim() !== ''); 
    
    const heightClasses = {
        small: 'min-h-[150px] @2xl:min-h-[250px]',
        medium: 'min-h-[250px] @2xl:min-h-[400px]',
        large: 'min-h-[400px] @2xl:min-h-[600px]',
        full: 'min-h-[calc(100vh-60px)]',
        auto: 'min-h-auto py-8 @2xl:py-12' 
    };

    const currentHeightClass = heightClasses[height] || heightClasses.auto;
    const hasLinks = socialLinks.length > 0;
    if (!hasLinks && isEditorPreview) {
        return (
            <div 
                className={`
                    w-full flex flex-col items-center justify-center gap-3 text-center p-8 mx-auto max-w-300 rounded-xl
                    bg-(--site-card-bg) text-(--site-text-secondary)
                    ${currentHeightClass}
                    border border-dashed border-(--site-border-color)
                `}
                style={style}
            >
                <div className="text-(--site-accent) opacity-70">
                    <Share2 size={40} className="@2xl:w-12 @2xl:h-12" />
                </div>
                <div>
                    <p className="m-0 font-semibold text-(--site-text-primary) text-base @2xl:text-lg">Соцмережі</p>
                    <small className="block mt-1 opacity-80 text-sm">Додайте посилання в налаштуваннях.</small>
                </div>
            </div>
        );
    }
    return (
        <div 
            className={`
                w-full flex flex-col justify-center bg-transparent
                ${currentHeightClass}
            `}
            style={{ 
                ...style,
                backgroundColor: 'var(--site-bg)'
            }}
        >
            <div 
                className="w-full max-w-300 mx-auto px-5 flex flex-wrap"
                style={{ 
                    justifyContent: alignment === 'left' ? 'flex-start' : (alignment === 'right' ? 'flex-end' : 'center') 
                }}
            >
                {socialLinks.map((net) => {
                    const IconComponent = IconsMap[net.key];
                    return (
                        <IconWrapper key={net.key} href={net.href} isEditorPreview={isEditorPreview} baseColor={baseColor}>
                            <IconComponent size={24} className="@2xl:w-7 @2xl:h-7" />
                        </IconWrapper>
                    );
                })}
            </div>
        </div>
    );
};

export default React.memo(SocialIconsBlock, areBlockPropsEqual);

// frontend/src/modules/editor/blocks/SocialIcons/SocialIconsSettings.jsx
import React from 'react';
import { commonStyles, ToggleGroup, SectionTitle } from '../../ui/configuration/SettingsUI';
import { Input } from '../../../../shared/ui/elements/Input';
import { AlignLeft, AlignCenter, AlignRight, Sun, Moon, Monitor, LayoutTemplate, Share2, Facebook, Instagram, Send, Youtube, Music } from 'lucide-react';

