                    <ToggleGroup 
                        options={[
                            { value: 'left', label: <AlignLeft size={18} /> },
                            { value: 'center', label: <AlignCenter size={18} /> },
                            { value: 'right', label: <AlignRight size={18} /> }
                        ]}
                        value={data.alignment || 'left'}
                        onChange={(val) => updateData({ alignment: val })}
                    />
                </div>

                <div className="mb-5">
                    <label style={commonStyles.label}>Тема</label>
                    <ToggleGroup 
                        options={[
                            { value: 'auto', label: <div className="flex gap-1.5 items-center"><Monitor size={16}/> Авто</div> },
