                            leftIcon={net.icon}
                        />
                    ))}
                </div>
            </div>
        </div>
    );
};

export default SocialIconsSettings;

// frontend/src/modules/editor/blocks/Text/TextBlock.jsx
import React from 'react';
import { useBlockFonts } from '../../../../shared/hooks/useBlockFonts';
import { areBlockPropsEqual } from '../../core/blockProps';

const TextBlock = ({ blockData, siteData, isEditorPreview, style }) => {
    const { 
        content = '', 
        tag = 'p', 
        fontFamily, 
        alignment = 'left',
        isBold = false,
        isItalic = false,
        isUnderline = false,
        height = 'small',
        textIndent = 0,
        styles = {}
    } = blockData;
    
    const { styles: fontStyles, RenderFonts, cssVariables } = useBlockFonts({
        main: fontFamily
    }, siteData);

    const ValidTag = ['p', 'h1', 'h2', 'h3'].includes(tag) ? tag : 'p';
    const tagClasses = {
        h1: 'text-4xl @2xl:text-5xl @3xl:text-6xl font-extrabold leading-[1.15] tracking-tight',
        h2: 'text-3xl @2xl:text-4xl @3xl:text-5xl font-bold leading-[1.2] tracking-tight',
        h3: 'text-2xl @2xl:text-3xl @3xl:text-4xl font-semibold leading-[1.3]',
        p:  'text-base @2xl:text-lg @3xl:text-xl font-normal leading-relaxed'
    };

    const heightClasses = { 
        small: 'min-h-auto', 
        medium: 'min-h-[40vh] @3xl:min-h-[400px]', 
        large: 'min-h-[60vh] @3xl:min-h-[600px]', 
        full: 'min-h-[calc(100vh-60px)]' 
    };

    const paragraphs = content ? content.split('\n') : [];
    const uniqueClass = `text-scope-${blockData.block_id || blockData.id || 'preview'}`;
    return (
        <div 
            className={`
                ${uniqueClass}
                w-full wrap-break-word flex flex-col justify-center 
                px-4 sm:px-6 md:px-8
                ${heightClasses[height] || heightClasses.small}
            `}
            style={{ 
                textAlign: alignment,
                backgroundColor: 'var(--site-bg, transparent)',
                color: 'var(--site-text-primary, inherit)',
                ...styles,
                ...style,
                ...cssVariables
            }}
        >
            <RenderFonts />
            <style>{`.${uniqueClass} { ${fontStyles.cssVars || ''} }`}</style>
            {paragraphs.length > 0 ? (
                paragraphs.map((line, index) => (
                    <ValidTag 
                        key={index}
                        className={`
                            ${tagClasses[ValidTag]}
                            ${isBold ? 'font-bold!' : ''} 
                            ${isItalic ? 'italic' : 'not-italic'}
                            ${isUnderline ? 'underline underline-offset-4' : 'no-underline'}
                            ${index === paragraphs.length - 1 ? 'mb-0' : 'mb-[1em]'}
                        `}
                        style={{
                            fontFamily: fontStyles.main,
                            color: 'inherit',
                            display: 'block',
                            marginTop: 0,
                            whiteSpace: 'pre-wrap', 
                            minHeight: line.trim() === '' ? '1em' : 'auto',
                            textIndent: textIndent ? `${textIndent}px` : '0'
                        }}
                    >
                        {line || <br/>} 
                    </ValidTag>
                ))
            ) : (
                isEditorPreview && (
                    <div className="opacity-50 italic py-2.5 text-(--site-text-secondary)">
                        Натисніть, щоб додати текст...
                    </div>
                )
            )}
        </div>
    );
};

export default React.memo(TextBlock, areBlockPropsEqual);

// frontend/src/modules/editor/blocks/Text/TextSettings.jsx
import React, { useRef, useEffect, useState } from 'react';
import { ToggleGroup, SectionTitle } from '../../ui/configuration/SettingsUI';
import AlignmentControl from '../../ui/components/AlignmentControl';
import FontSelector from '../../ui/components/FontSelector';
import { FileText, Type, Heading1, Heading2, Heading3, Pilcrow, Bold, Italic, Underline } from 'lucide-react';

const TextSettings = ({ data, onChange, siteData }) => {
    const textareaRef = useRef(null);
    const [localContent, setLocalContent] = useState(data.content || '');
    const themeSettings = siteData?.theme_settings || {};
    const currentSiteFonts = {
        heading: themeSettings.font_heading,
        body: themeSettings.font_body
    };

    useEffect(() => {
        setLocalContent(data.content || '');
    }, [data.content]);

    const handleChange = (key, value) => {
        onChange({ ...data, [key]: value }, true);
    };

    const toggleStyle = (key) => {
        onChange({ ...data, [key]: !data[key] }, true);
    };
    
    useEffect(() => {
        if (textareaRef.current) {
            textareaRef.current.style.height = 'auto';
            textareaRef.current.style.height = textareaRef.current.scrollHeight + 'px';
        }
    }, [localContent]);

    const tagOptions = [
        { value: 'p', label: <div title="Параграф"><Pilcrow size={18} /></div> },
        { value: 'h1', label: <div title="Заголовок H1"><Heading1 size={18} /></div> },
        { value: 'h2', label: <div title="Заголовок H2"><Heading2 size={18} /></div> },
        { value: 'h3', label: <div title="Заголовок H3"><Heading3 size={18} /></div> },
    ];

    return (
        <div>
            <div className="mb-8">
                <SectionTitle icon={<FileText size={18}/>}>Вміст</SectionTitle>
                <div className="form-group">
                    <textarea 
                        ref={textareaRef}
                        className="custom-input custom-scrollbar transition-colors shadow-none"
                        value={localContent}
                        onChange={(e) => {
                            setLocalContent(e.target.value);
                            onChange({ ...data, content: e.target.value }, false);
                        }} 
                        onBlur={() => onChange({ ...data, content: localContent }, true)}
                        placeholder="Введіть текст..."
                        style={{
                            minHeight: '100px',
                            resize: 'none',
                            lineHeight: '1.5',
                            marginBottom: '12px',
                            height: 'auto'
                        }}
                    />
                    <div className="flex justify-center gap-2">
                        <button 
                            onClick={() => toggleStyle('isBold')}
                            className={`btn btn-icon-square ${data.isBold ? 'btn-primary' : 'btn-outline'}`}
                            title="Напівжирний"
                        >
                            <Bold size={18} />
                        </button>
                        <button 
                            onClick={() => toggleStyle('isItalic')}
                            className={`btn btn-icon-square ${data.isItalic ? 'btn-primary' : 'btn-outline'}`}
                            title="Курсив"
                        >
                            <Italic size={18} />
                        </button>
                        <button 
                            onClick={() => toggleStyle('isUnderline')}
                            className={`btn btn-icon-square ${data.isUnderline ? 'btn-primary' : 'btn-outline'}`}
                            title="Підкреслений"
                        >
                            <Underline size={18} />
                        </button>
                    </div>
                </div>
                <div className="form-group">
                    <AlignmentControl 
                        value={data.alignment}
                        onChange={(val) => handleChange('alignment', val)}
                        showJustify={true} 
                    />
                </div>
            </div>
            <div>
                <SectionTitle icon={<Type size={18}/>}>Типографіка</SectionTitle>
                <div className="form-group">
                    <label className="form-label">Семантика</label>
                    <ToggleGroup 
                        options={tagOptions}
                        value={data.tag || 'p'}
                        onChange={(val) => handleChange('tag', val)}
                    />
                </div>
                <div className="form-group">
                    <FontSelector 
                        value={data.fontFamily}
                        onChange={(val) => handleChange('fontFamily', val)}
                        label="Шрифт"
                        siteFonts={currentSiteFonts}
                    />
                </div>
                <div className="form-group mt-5">
                    <div className="flex justify-between items-center mb-2">
                        <label className="form-label mb-0">Відступ першого рядка</label>
                        <span className="text-xs font-medium text-(--platform-text-secondary)">
                            {data.textIndent || 0} px
                        </span>
                    </div>
                    <input 
                        type="range" 
                        min="0" 
                        max="100" 
                        step="1"
                        value={data.textIndent || 0} 
                        onChange={(e) => onChange({ ...data, textIndent: parseInt(e.target.value) }, false)}
                        onMouseUp={(e) => onChange({ ...data, textIndent: parseInt(e.target.value) }, true)}
                        onTouchEnd={(e) => onChange({ ...data, textIndent: parseInt(e.target.value) }, true)}
                        className="w-full h-1.5 bg-black/10 dark:bg-white/10 rounded-lg appearance-none cursor-pointer accent-(--platform-accent)"
                    />
                </div>
            </div>
        </div>
    );
};

export default TextSettings;

// frontend/src/modules/editor/blocks/Video/VideoBlock.jsx
import React, { useRef, useEffect } from 'react';
import { BASE_URL } from '../../../../shared/config';
import { Video as VideoIcon } from 'lucide-react';
import { areBlockPropsEqual } from '../../core/blockProps';

const getYoutubeVideoId = (url) => {
    if (!url || typeof url !== 'string') return null;
    const regExp = /^(?:https?:\/\/)?(?:www\.)?(?:youtube\.com\/(?:[^\/\n\s]+\/\S+\/|(?:v|e(?:mbed)?)\/|\S*?[?&]v=)|youtu\.be\/)([a-zA-Z0-9_-]{11})/;
    const match = url.match(regExp);
    return match ? match[1] : null;
};

const VideoBlock = ({ blockData, isEditorPreview, style }) => {
    const { 
        url, 
        poster,
        height = 'medium', 
        overlay_color = '#000000',
        overlay_opacity,
        block_theme = 'auto',
        autoplay = true,
        muted = true,
        loop = true,
        controls = false,
        styles = {}
    } = blockData;
    
    const videoRef = useRef(null);
    const safeOpacity = (overlay_opacity === undefined || isNaN(Number(overlay_opacity))) 
        ? 0.5 
        : Number(overlay_opacity);
    const fullVideoUrl = url 
        ? (url.startsWith('http') ? url : `${BASE_URL}${url}`) 
        : null;
    const fullPosterUrl = poster 
        ? (poster.startsWith('http') ? poster : `${BASE_URL}${poster}`) 
        : null;
    const ytVideoId = getYoutubeVideoId(fullVideoUrl);
    useEffect(() => {
        if (ytVideoId) return; 
        const video = videoRef.current;
        if (!video) return;
        if (!controls && autoplay) {
            const playPromise = video.play();
            if (playPromise !== undefined) {
                playPromise.catch(() => {
                    if (muted) {
                        video.muted = true;
                        video.play().catch(e => console.error(e));
                    }
                });
            }
        }
    }, [controls, autoplay, muted, fullVideoUrl, ytVideoId]);
    const heightClasses = { 
        small: 'min-h-[250px] @3xl:min-h-[300px]', 
        medium: 'min-h-[300px] @3xl:min-h-[500px]', 
        large: 'min-h-[400px] @3xl:min-h-[700px]', 
        full: 'min-h-[calc(100vh-60px)]',
        auto: 'aspect-video w-full' 
    };
    
    const currentHeightClass = heightClasses[height] || heightClasses.medium;
    const isTransparent = overlay_color === 'transparent';
    const Placeholder = () => (
        <div className="absolute inset-0 w-full h-full p-8 @3xl:p-12 text-center bg-(--site-card-bg) border border-dashed border-(--site-border-color) text-(--site-text-secondary) flex flex-col items-center justify-center gap-3 box-border">
            <div className="opacity-40 text-(--site-text-primary)">
                <VideoIcon size={48} className="@3xl:w-16 @3xl:h-16" />
            </div>
            <div className="text-sm @3xl:text-base font-medium">
                Відео не вибрано
            </div>
        </div>
    );
    
    const renderContent = () => {
        if (ytVideoId) {
            const ytParams = new URLSearchParams({
                autoplay: autoplay ? '1' : '0',
                mute: muted ? '1' : '0',
                controls: controls ? '1' : '0',
                loop: loop ? '1' : '0',
                playlist: ytVideoId,
                playsinline: '1',
                rel: '0'
            });
            return (
                <div className={`absolute inset-0 w-full h-full overflow-hidden ${!controls ? 'pointer-events-none' : ''}`}>
                    <iframe
                        src={`https://www.youtube.com/embed/${ytVideoId}?${ytParams.toString()}`}
                        title="YouTube video player"
                        frameBorder="0"
                        allow="accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture"
                        allowFullScreen
                        className="w-full h-full"
                        style={{
                            transform: !controls ? 'scale(1.25)' : 'none'
                        }}
                    />
                </div>
            );
        }
        if (fullVideoUrl) {
            return (
                <video
                    ref={videoRef}
                    src={fullVideoUrl}
                    poster={fullPosterUrl}
                    autoPlay={autoplay}
                    muted={muted}
                    loop={loop}
                    controls={controls}
                    playsInline
                    className="absolute inset-0 w-full h-full object-cover block"
                />
            );
        }
        if (fullPosterUrl) {
            return (
                <img 
                    src={fullPosterUrl}
                    alt="Video poster"
                    className="absolute inset-0 w-full h-full object-cover block"
                />
            );
        }
        if (isEditorPreview) {
            return <Placeholder />;
        }
        return <div className="absolute inset-0 w-full h-full bg-black/10"></div>;
    };

    return (
        <div 
            className={`
                block-theme-${block_theme} relative w-full overflow-hidden
                ${currentHeightClass}
            `}
            style={{
                backgroundColor: 'var(--site-bg)',
                ...styles,
                ...style 
            }}
        >
            {renderContent()}
            {(fullVideoUrl || fullPosterUrl || ytVideoId) && !isTransparent && (
                <div 
                    className="absolute inset-0 z-10 pointer-events-none transition-all duration-300"
                    style={{
                        backgroundColor: overlay_color,
                        opacity: safeOpacity,
                    }}
                ></div>
            )}
        </div>
    );
};

export default React.memo(VideoBlock, areBlockPropsEqual);

