                                            }}
                                        >
                                            {item.label}
                                        </Link>
                                    ))
                                ) : (
                                    <p className="text-center" style={{ color: textSecondary }}>Меню порожнє</p>
                                )}
                            </nav>
                        </div>
                    </div>
                )}
            </div>
        </BlockRendererContext.Provider>
    );
};

