import { createContext, useContext } from 'react';

export const BlockRendererContext = createContext(null);
export const EditableBlockContext = createContext(null);

export const useBlockRenderer = () => useContext(BlockRendererContext);
export const useEditableBlock = () => useContext(EditableBlockContext);

// frontend/src/modules/editor/core/blockId.js
export const generateBlockId = () => {
    if (crypto && crypto.randomUUID) {
        return crypto.randomUUID();
    }
    return `id-${Date.now()}-${Math.random().toString(36).substring(2, 9)}`;
};

// frontend/src/modules/editor/core/blockProps.js
import { isEqual } from 'lodash';

export const areBlockPropsEqual = (prev, next) =>
    isEqual(prev.blockData, next.blockData) &&
    prev.isEditorPreview === next.isEditorPreview &&
    prev.siteData?.id === next.siteData?.id;

