// frontend/src/modules/editor/core/globalBlocks.js
import { getDefaultBlockData } from './blockRegistry';
import { isHeaderType, isFooterType } from './globalBlockTypes';

const KINDS = [
    {
        type: 'global-header',
        field: 'header_content',
        label: 'Header',
        matches: isHeaderType,
        fillMissing: (data, defaults) => {
            if (!data.nav_items || data.nav_items.length === 0) data.nav_items = defaults.nav_items;
            if (data.site_title === undefined) data.site_title = defaults.site_title;
        }
    },
    {
        type: 'global-footer',
        field: 'footer_content',
        label: 'Footer',
        matches: isFooterType,
        fillMissing: null
    }
];

const kindOf = (type) => KINDS.find((kind) => kind.matches(type));

export const parseGlobalContent = (raw) => (typeof raw === 'string' ? JSON.parse(raw || '{}') : (raw || {}));

export const resolveGlobalData = (raw, type) => {
    const data = parseGlobalContent(raw);
    return Object.keys(data).length === 0 ? getDefaultBlockData(type) : data;
};

export const normalizeGlobalBlocks = (blocks, siteData) =>
    blocks.map((block) => {
        const kind = kindOf(block.type);
        if (!kind) return block;
        return { ...block, type: kind.type, data: resolveGlobalData(siteData[kind.field], kind.type) };
    });

const mergeGlobalContent = (block, raw, kind) => {
    let data = { ...(block.data || {}) };
    if (raw) {
        try {
            const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
            if (Array.isArray(parsed)) {
                const found = parsed.find((item) => kind.matches(item.type));
                if (found?.data) data = { ...data, ...found.data };
            } else if (typeof parsed === 'object' && parsed !== null) {
                if (parsed['0'] && parsed['0'].data) {
                    data = { ...data, ...parsed['0'].data };
                }
                const rootProps = { ...parsed };
                delete rootProps['0']; delete rootProps.type; delete rootProps.block_id;
                data = { ...data, ...rootProps };
            }
        } catch (e) {
            console.error(`${kind.label} parse error`, e);
        }
    }
    const defaults = getDefaultBlockData(kind.type);
    if (Object.keys(data).length === 0) {
        data = defaults;
    } else if (kind.fillMissing) {
        kind.fillMissing(data, defaults);
    }
    return { ...block, type: kind.type, data };
};

export const mergeGlobalBlocks = (blocks, siteData) => {
    if (!Array.isArray(blocks)) return [];
    return blocks.map((block) => {
        const kind = kindOf(block.type);
        if (!kind) return block;
        return mergeGlobalContent(block, siteData[kind.field], kind);
    });
};

// frontend/src/modules/editor/core/useBlockDrop.js
import { useState, useEffect } from 'react';
import { useDrop } from 'react-dnd';

export const DND_TYPE_EXISTING = 'BLOCK';
export const DND_TYPE_NEW = 'NEW_BLOCK';
export const useBlockDrop = ({
    ref,
    path,
    onMoveBlock,
    onAddBlock,
    canDropOnSelf = false 
}) => {
    const [dropPosition, setDropPosition] = useState(null);
    const [{ isOver, handlerId }, drop] = useDrop({
        accept: [DND_TYPE_EXISTING, DND_TYPE_NEW],
        collect(monitor) {
            return {
                handlerId: monitor.getHandlerId(),
                isOver: monitor.isOver({ shallow: true }), 
            };
        },
        hover(item, monitor) {
            if (!ref.current) return;
            if (!monitor.isOver({ shallow: true })) {
                setDropPosition(null);
                return;
            }
            const dragPath = item.path;
            const hoverPath = path;
            const hoverBoundingRect = ref.current?.getBoundingClientRect();
            const clientOffset = monitor.getClientOffset();
            if (!clientOffset) return;
            const hoverMiddleY = (hoverBoundingRect.bottom - hoverBoundingRect.top) / 2;
            const hoverClientY = clientOffset.y - hoverBoundingRect.top;
            let newPosition = hoverClientY < hoverMiddleY ? 'top' : 'bottom';
            if (dragPath && item.type !== DND_TYPE_NEW) {
                const dragIndex = dragPath[dragPath.length - 1];
                const hoverIndex = hoverPath[hoverPath.length - 1];
                const isSameParent = dragPath.slice(0, -1).join(',') === hoverPath.slice(0, -1).join(',');
                if (isSameParent) {
                    if (dragIndex === hoverIndex) {
                        setDropPosition('center');
                        return;
                    }
                    if (newPosition === 'bottom' && hoverIndex === dragIndex - 1) {
                        setDropPosition(null);
                        return;
                    }
                    if (newPosition === 'top' && hoverIndex === dragIndex + 1) {
                        setDropPosition(null);
                        return;
                    }
                }
            }
            setDropPosition(newPosition);
        },
        drop(item, monitor) {
            const currentPos = dropPosition; 
            setDropPosition(null);
            if (monitor.didDrop()) return;
            if (!currentPos) return;
            const dragType = monitor.getItemType();
            if (dragType === DND_TYPE_NEW && onAddBlock && monitor.isOver({ shallow: true })) {
                const currentPathIndex = path[path.length - 1];
                const parentPath = path.slice(0, -1);
                let insertIndex = currentPathIndex;
                if (currentPos === 'bottom') {
                    insertIndex = currentPathIndex + 1;
                }
                const insertPath = [...parentPath, insertIndex];
                onAddBlock(insertPath, item.blockType, item.presetData);
                return { handled: true };
            }

            if (dragType === DND_TYPE_EXISTING && onMoveBlock && monitor.isOver({ shallow: true })) {
                const dragPath = item.path;
                const hoverPath = path;
                if (dragPath.join(',') === hoverPath.join(',')) return;
                const parentPath = hoverPath.slice(0, -1);
                const dragParentPath = dragPath.slice(0, -1);
                const hoverIndex = hoverPath[hoverPath.length - 1];
                const dragIndex = dragPath[dragPath.length - 1];
                let targetIndex = hoverIndex;
                if (currentPos === 'bottom') {
                    targetIndex = hoverIndex + 1;
                }
                const isSameParent = dragParentPath.join(',') === parentPath.join(',');
                if (isSameParent && dragIndex < hoverIndex) {
                    targetIndex -= 1;
                }
                const targetPath = [...parentPath, targetIndex];
                onMoveBlock(dragPath, targetPath);
                item.path = targetPath;
            }
        }
    });

    useEffect(() => {
        if (!isOver) setDropPosition(null);
    }, [isOver]);

    return {
        drop,
        dropPosition,
        handlerId,
        isOver
    };
};

