            title: isGlobal ? "Видалення глобального блоку" : "Видалення блоку",
            message: msg,
            type: "danger",
            confirmLabel: "Видалити"
        });
        if (isConfirmed) {
            onDeleteBlock(path);
            toast.info("Блок видалено");
        }
    };

    const handleSelectAndScroll = (e) => {
        e.stopPropagation();
        onSelectBlock(path);
