        { value: 'phone', icon: <Phone size={18} />, label: 'Дзвінок' },
        { value: 'check', icon: <Check size={18} />, label: 'Ок' },
        { value: 'star', icon: <Star size={18} />, label: 'Зірка' },
        { value: 'pointer', icon: <MousePointer2 size={18} />, label: 'Клік' },
