                            `}
                            style={{
                                background: 'var(--site-accent)',
                                color: 'var(--site-accent-text)',
                                border: 'none',
                            }}
                            title={hasVariants ? "Вибрати опції" : "Додати в кошик"}
                        >
                            {hasVariants ? <Settings size={18} /> : <ShoppingCart size={18} />}
                        </button>
                    </div>
                </div>
            </div>
        </Link>
    );
};

