const SavedBlockItem = ({ block, onDelete, onRename, onClickAdd }) => {
    const [isEditing, setIsEditing] = useState(false);
    const [newName, setNewName] = useState(block.name);
    const [isSaving, setIsSaving] = useState(false);
    const handleStartEdit = (e) => {
        e.preventDefault();
        e.stopPropagation();
        setNewName(block.name);
        setIsEditing(true);
    };

    const handleCancelEdit = (e) => {
        e.preventDefault();
        e.stopPropagation();
        setIsEditing(false);
        setNewName(block.name);
    };

    const handleSaveEdit = async (e) => {
        e.preventDefault();
        e.stopPropagation();
        if (!newName.trim() || newName === block.name) {
            setIsEditing(false);
            return;
        }
        setIsSaving(true);
        await onRename(block.id, newName);
        setIsSaving(false);
        setIsEditing(false);
    };

    const handleDeleteClick = (e) => {
        e.preventDefault();
        e.stopPropagation();
        onDelete(e, block.id, block.name);
