// frontend/src/modules/media/components/MediaInspector.jsx
import React, { useState, useEffect, useRef } from 'react';
import { Button } from '../../../shared/ui/elements/Button';
import apiClient from '../../../shared/api/api';
import { toast } from 'react-toastify';
import MediaFilePreview from '../../../shared/ui/complex/MediaFilePreview';
import { API_URL, getFileExtension } from '../../../shared/utils/mediaUtils';
import { Download, Trash2, Copy, ExternalLink, X, Type, Save } from 'lucide-react';

const MediaInspector = ({ file, onUpdate, onDelete, onClose }) => {
    const [formData, setFormData] = useState({
        display_name: '',
        alt_text: '',
        description: ''
    });
    const [isSaving, setIsSaving] = useState(false);
    const isSavingRef = useRef(false);
    const getValidUrl = (path) => {
        if (!path) return '';
        return path.startsWith('http') ? path : `${API_URL}${path}`;
    };

    const hasChanges = file && (
        formData.display_name !== (file.display_name || '') ||
        formData.alt_text !== (file.alt_text || '') ||
        formData.description !== (file.description || '')
    );

    const isFont = file && (file.mime_type.includes('font') || /\.(ttf|otf|woff|woff2)$/i.test(file.original_file_name));
    useEffect(() => {
        if (isFont && file) {
            const fontUrl = getValidUrl(file.path_full);
            const fontName = `PreviewFont-${file.id}`;
            const fontFace = new FontFace(fontName, `url(${fontUrl})`);
            
            fontFace.load().then((loadedFace) => {
                document.fonts.add(loadedFace);
                const previewEl = document.getElementById(`font-preview-${file.id}`);
                if (previewEl) {
                    previewEl.style.fontFamily = fontName;
                }
            }).catch(err => {
                console.error("Не вдалося завантажити шрифт для перегляду:", err);
            });
        }
    }, [file, isFont]);

    useEffect(() => {
        if (file) {
            setFormData({
                display_name: file.display_name || '',
                alt_text: file.alt_text || '',
                description: file.description || ''
            });
        }
    }, [file]);

    if (!file) return null;
    const saveChanges = async () => {
        if (!hasChanges || isSavingRef.current) return;
        isSavingRef.current = true;
        setIsSaving(true);
        try {
            const res = await apiClient.put(`/media/${file.id}`, formData);
            onUpdate(res.data);
            toast.success('Зміни збережено');
        } catch (error) {
            console.error(error);
            toast.error('Помилка збереження');
        } finally {
            isSavingRef.current = false;
            setIsSaving(false);
        }
    };

    const handleBlur = () => {
        if (hasChanges) saveChanges();
    };

    const handleSaveClick = (e) => {
        e.preventDefault(); 
        saveChanges();
    };

    const copyUrl = () => {
        const url = getValidUrl(file.path_full);
        navigator.clipboard.writeText(url);
        toast.info('URL скопійовано');
    };

    const openInNewWindow = () => {
        window.open(getValidUrl(file.path_full), '_blank');
    };

    const handleForceDownload = async (e) => {
        e.preventDefault();
        try {
            const response = await fetch(getValidUrl(file.path_full));
            const blob = await response.blob();
            const url = window.URL.createObjectURL(blob);
            const link = document.createElement('a');
            link.href = url;
            link.download = file.original_file_name || 'download';
            document.body.appendChild(link);
            link.click();
            window.URL.revokeObjectURL(url);
            document.body.removeChild(link);
            toast.success('Завантаження почалось');
        } catch (err) {
            console.error(err);
            toast.error('Помилка завантаження файлу');
        }
    };

    const renderPreview = () => {
        if (isFont) {
            return (
                <div className="text-center w-full">
                    <div className="flex justify-center mb-3">
                        <Type size={48} className="text-(--platform-accent) shrink-0" />
                    </div>
                    <div 
                        id={`font-preview-${file.id}`} 
                        className="text-xl sm:text-2xl wrap-break-word p-3 text-(--platform-text-primary)"
                    >
                        Aa Bb Cc 123
                        <br/>
                        <span className="text-sm sm:text-base">Привіт світ!</span>
                    </div>
                </div>
            );
        }
        return (
            <div className="w-full h-full sm:h-55">
                <MediaFilePreview 
                    file={file} 
                    showVideoControls={true} 
                    className="rounded-lg object-contain w-full h-full"
                />
            </div>
        );
    };

    return (
        <div className="flex flex-col w-full h-full min-h-screen sm:min-h-full bg-(--platform-sidebar-bg) sm:border-l sm:border-(--platform-border-color)">
            <div className="p-4 border-b border-(--platform-border-color) flex justify-between items-center bg-(--platform-bg) text-(--platform-text-primary) shrink-0 sticky top-0 z-20">
                <span className="font-bold text-base">Властивості файлу</span>
                <Button 
                    variant="ghost" 
                    onClick={onClose} 
                    title="Закрити"
                    className="p-0 w-8 h-8 rounded-full min-w-auto shrink-0 flex items-center justify-center hover:bg-black/5"
                >
                    <X size={20} className="shrink-0" />
                </Button>
            </div>
            <div 
                className="p-4 sm:p-5 bg-(--platform-bg) border-b border-(--platform-border-color) flex justify-center items-center min-h-55 relative"
                style={{ backgroundImage: "url('https://transparenttextures.com/patterns/cubes.png')", backgroundRepeat: 'repeat' }}
            >
                {renderPreview()}
            </div>
            <div className="p-4 sm:p-5 flex flex-col gap-3.5 flex-1">
                <div className="grid grid-cols-2 gap-2.5 p-3 bg-(--platform-bg) rounded-lg border border-(--platform-border-color) text-xs sm:text-[0.8rem] text-(--platform-text-secondary)">
                    <div className="flex flex-col gap-0.5 overflow-hidden">
                        <span className="text-[10px] sm:text-[11px] opacity-80 uppercase tracking-wider">Тип</span>
                        <span className="text-(--platform-text-primary) font-medium truncate" title={file.mime_type}>
                            {getFileExtension(file.original_file_name)}
                        </span>
                    </div>
                    <div className="flex flex-col gap-0.5 overflow-hidden">
                        <span className="text-[10px] sm:text-[11px] opacity-80 uppercase tracking-wider">Розмір</span>
                        <span className="text-(--platform-text-primary) font-medium truncate">{file.file_size_kb} KB</span>
                    </div>
                    <div className="flex flex-col gap-0.5 overflow-hidden">
                        <span className="text-[10px] sm:text-[11px] opacity-80 uppercase tracking-wider">Дата</span>
                        <span className="text-(--platform-text-primary) font-medium truncate">{new Date(file.created_at).toLocaleDateString()}</span>
                    </div>
                    <div className="flex flex-col gap-0.5 overflow-hidden">
                        <span className="text-[10px] sm:text-[11px] opacity-80 uppercase tracking-wider">Розміри</span>
                        <span className="text-(--platform-text-primary) font-medium truncate">{file.width ? `${file.width}x${file.height}` : '-'}</span>
                    </div>
                </div>
                <div className="flex flex-col gap-1">
                    <label className="text-[11px] sm:text-xs font-semibold uppercase tracking-wide text-(--platform-text-secondary)">Ім'я файлу</label>
                    <input 
                        type="text" 
                        value={formData.display_name} 
                        onChange={e => setFormData({...formData, display_name: e.target.value})}
                        onBlur={handleBlur}
                        className="w-full p-2.5 rounded-lg border border-(--platform-border-color) bg-(--platform-input-bg) text-(--platform-text-primary) text-sm focus:outline-none focus:border-(--platform-accent) transition-colors"
                    />
                </div>
                {!isFont && (
                    <div className="flex flex-col gap-1">
                        <label className="text-[11px] sm:text-xs font-semibold uppercase tracking-wide text-(--platform-text-secondary)">Alt текст (SEO)</label>
                        <input 
                            type="text" 
                            value={formData.alt_text} 
                            onChange={e => setFormData({...formData, alt_text: e.target.value})}
                            onBlur={handleBlur}
                            placeholder="Опис для пошуковиків"
                            className="w-full p-2.5 rounded-lg border border-(--platform-border-color) bg-(--platform-input-bg) text-(--platform-text-primary) text-sm focus:outline-none focus:border-(--platform-accent) transition-colors"
                        />
                    </div>
                )}
                <div className="flex flex-col gap-1">
                    <label className="text-[11px] sm:text-xs font-semibold uppercase tracking-wide text-(--platform-text-secondary)">Нотатки</label>
                    <textarea 
                        value={formData.description} 
                        onChange={e => setFormData({...formData, description: e.target.value})}
                        onBlur={handleBlur}
                        placeholder="Для внутрішнього користування..."
                        className="w-full p-2.5 rounded-lg border border-(--platform-border-color) bg-(--platform-input-bg) text-(--platform-text-primary) text-sm focus:outline-none focus:border-(--platform-accent) transition-colors resize-y min-h-15 sm:min-h-20"
                    />
                </div>
                <Button 
                    variant="primary" 
                    onClick={handleSaveClick}
                    disabled={!hasChanges || isSaving}
                    className="w-full mt-2 min-h-11 sm:min-h-10 shadow-sm"
                >
                    <Save size={16} className="mr-2 shrink-0" /> {isSaving ? 'Збереження...' : 'Зберегти зміни'}
                </Button>
                <div className="grid grid-cols-2 gap-2.5 mt-3 pt-5 border-t border-(--platform-border-color) pb-6">
                    <Button 
                        variant="outline"
                        onClick={copyUrl} 
                        title="Копіювати посилання"
                        className="w-full justify-center text-[13px] sm:text-sm min-h-10"
                    >
                        <Copy size={16} className="mr-1.5 shrink-0" /> Копіювати
                    </Button>
                    <Button 
                        variant="outline"
                        onClick={openInNewWindow} 
                        title="Відкрити в новій вкладці"
                        className="w-full justify-center text-[13px] sm:text-sm min-h-10"
                    >
                        <ExternalLink size={16} className="mr-1.5 shrink-0" /> Відкрити
                    </Button>
                    <Button 
                        variant="outline"
                        onClick={handleForceDownload} 
                        title="Завантажити файл на комп'ютер"
                        className="w-full justify-center text-[13px] sm:text-sm min-h-10"
                    >
                        <Download size={16} className="mr-1.5 shrink-0" /> Завантажити
                    </Button>
                    <Button 
                        variant="danger"
                        onClick={() => onDelete(file)} 
                        title="Видалити"
                        className="w-full justify-center text-[13px] sm:text-sm min-h-10"
                    >
                        <Trash2 size={16} className="mr-1.5 shrink-0" /> Видалити
                    </Button>
                </div>
            </div>
        </div>
    );
};

export default MediaInspector;

// frontend/src/modules/media/components/MediaPickerModal.jsx
import React, { useState, useEffect, useRef } from 'react';
import ReactDOM from 'react-dom';
import apiClient from '../../../shared/api/api';
import { toast } from 'react-toastify';
import MediaFilePreview from '../../../shared/ui/complex/MediaFilePreview';
import { getMediaUrl } from '../../../shared/utils/mediaUtils';
import ImageCropperModal from '../../../shared/ui/complex/ImageCropperModal';
import DragDropWrapper from '../../../shared/ui/complex/DragDropWrapper';
import LoadingState from '../../../shared/ui/complex/LoadingState';
import { Button } from '../../../shared/ui/elements/Button';
import { Search, X, Upload, Check, Image, Calendar, FileText, Clock, HardDrive } from 'lucide-react';

const MediaPickerModal = ({ 
    isOpen, 
    onClose, 
    onSelect, 
    multiple = false, 
    title = "Вибір медіа",
    allowedTypes = ['image'],
    aspect = null
}) => {
    const [files, setFiles] = useState([]);
    const [loading, setLoading] = useState(true);
    const [limits, setLimits] = useState(null);
    const [selectedIds, setSelectedIds] = useState(new Set());
    const [searchQuery, setSearchQuery] = useState('');
    const [activeFile, setActiveFile] = useState(null);
    const [videoDuration, setVideoDuration] = useState(null);
    const fileInputRef = useRef(null);
    const [cropModalOpen, setCropModalOpen] = useState(false);
    const [imageToCrop, setImageToCrop] = useState(null);
    const [isUploadingCrop, setIsUploadingCrop] = useState(false);
    useEffect(() => {
        if (isOpen) {
            fetchMedia();
            setSelectedIds(new Set());
            setActiveFile(null);
            document.body.style.overflow = 'hidden';
        } else {
            document.body.style.overflow = '';
        }
        return () => { document.body.style.overflow = ''; };
    }, [isOpen]);

    useEffect(() => {
        setVideoDuration(null);
    }, [activeFile]);

    const fetchMedia = async () => {
        setLoading(true);
        try {
            const [mediaRes, limitsRes] = await Promise.all([
                apiClient.get('/media'),
                apiClient.get('/media/limits')
            ]);
            const data = Array.isArray(mediaRes.data) ? mediaRes.data : [];
            const filtered = data.filter(f => {
                if (allowedTypes.includes('all')) return true;
                return allowedTypes.some(type => {
                    if (f.file_type === type) return true;
                    if (f.mime_type === type) return true;
                    if (type.startsWith('.')) {
                        return f.original_file_name.toLowerCase().endsWith(type.toLowerCase());
                    }
                    return false;
                });
            });
            setFiles(filtered);
            setLimits(limitsRes.data);
        } catch (error) {
            console.error(error);
            toast.error('Помилка завантаження медіатеки');
        } finally {
            setLoading(false);
        }
    };

    const handleUpload = async (eOrFiles) => {
        const fileList = eOrFiles.target ? eOrFiles.target.files : eOrFiles;
        if (!fileList || fileList.length === 0) return;
        const toastId = toast.loading("Завантаження...");
        let successCount = 0;
        let failedFiles = [];
        for (let i = 0; i < fileList.length; i++) {
            const file = fileList[i];
            const formData = new FormData();
            formData.append('mediaFile', file);
            try {
                const res = await apiClient.post('/media/upload', formData);
                if (res.data && res.data.error) {
                    failedFiles.push({ name: file.name, reason: res.data.message });
                    if (res.data.code === 'MAX_FILES_REACHED') break;
                    continue; 
                }
                if (res && res.data && res.data.id) {
                    successCount++;
                }
            } catch (err) {
                console.error("Помилка завантаження:", err);
                failedFiles.push({ 
                    name: file.name, 
                    reason: err.response?.data?.message || "Непередбачена помилка сервера" 
                });
            }
        }
        toast.dismiss(toastId);
        if (successCount > 0) {
            toast.success(`Успішно завантажено: ${successCount} файлів`);
            await fetchMedia(); 
        }
        if (failedFiles.length > 0) {
            const limit = 3; 
            const errorList = failedFiles.slice(0, limit)
                .map(f => `• ${f.name} (${f.reason})`)
                .join('\n');
            const moreCount = failedFiles.length - limit;
            const finalMessage = moreCount > 0 
                ? `Не завантажено ${failedFiles.length} файлів:\n${errorList}\n...та ще ${moreCount}`
                : `Не завантажено:\n${errorList}`;
            toast.error(
                <div style={{ whiteSpace: 'pre-wrap', fontSize: '0.85rem', lineHeight: '1.4' }}>
                    {finalMessage}
                </div>, 
                { autoClose: 7000 } 
            );
        }
        
        if (fileInputRef.current) fileInputRef.current.value = '';
    };

    const handleFileClick = (file) => {
        const isCurrentlySelected = selectedIds.has(file.id);
        const isCurrentlyActive = activeFile?.id === file.id;
        const newSelectedIds = new Set(selectedIds);
        if (multiple) {
            if (isCurrentlySelected) newSelectedIds.delete(file.id);
            else newSelectedIds.add(file.id);
        } else {
            if (isCurrentlySelected) {
                newSelectedIds.clear(); 
            } else {
                newSelectedIds.clear();
                newSelectedIds.add(file.id); 
            }
        }
        
        setSelectedIds(newSelectedIds);
        if (!multiple) {
            setActiveFile(newSelectedIds.has(file.id) ? file : null);
        } else {
            if (!isCurrentlySelected) {
                setActiveFile(file);
            } else {
                if (isCurrentlyActive) {
                    if (newSelectedIds.size === 0) {
                        setActiveFile(null);
                    } else {
                        const idsArray = Array.from(newSelectedIds);
                        const lastId = idsArray[idsArray.length - 1];
                        const lastFile = files.find(f => f.id === lastId);
                        setActiveFile(lastFile || null);
                    }
                }
            }
        }
    };

    const handleSubmit = () => {
        const selectedFiles = files.filter(f => selectedIds.has(f.id));
        if (selectedFiles.length === 0) {
            onClose();
            return;
        }
        if (aspect && !multiple && selectedFiles.length === 1) {
            const file = selectedFiles[0];
            if (file.file_type === 'image' || file.mime_type?.startsWith('image/')) {
                const fullUrl = getMediaUrl(file);
                setImageToCrop(fullUrl);
                setCropModalOpen(true);
                return;
            }
        }
        onSelect(multiple ? selectedFiles : selectedFiles[0]);
        onClose();
    };

    const handleCropFinished = async (croppedFileBlob) => {
        setIsUploadingCrop(true);
        try {
            const formData = new FormData();
            const originalName = activeFile?.original_file_name || 'image.jpg';
            const nameParts = originalName.split('.');
            const ext = nameParts.length > 1 ? nameParts.pop() : 'jpg';
            const newName = `${nameParts.join('.')}_crop.${ext}`;
            formData.append('mediaFile', croppedFileBlob, newName);
            const res = await apiClient.post('/media/upload', formData);
            if (res.data && res.data.error) {
                toast.error(res.data.message);
                return;
            }
            const uploadedFile = res.data;
            setFiles(prev => [uploadedFile, ...prev]);
            onSelect(uploadedFile);
            setCropModalOpen(false);
            onClose(); 
            toast.success('Зображення обрізано та збережено');
        } catch (error) {
            console.error('Upload crop error:', error);
            toast.error(error.response?.data?.message || 'Не вдалося зберегти обрізане зображення');
        } finally {
            setIsUploadingCrop(false);
        }
    };

    const formatDuration = (seconds) => {
        if (!seconds) return '--:--';
        const m = Math.floor(seconds / 60);
        const s = Math.floor(seconds % 60);
        return `${m}:${s.toString().padStart(2, '0')}`;
    };

    if (!isOpen) return null;
    const filteredFiles = files.filter(f => 
        (f.original_file_name || '').toLowerCase().includes(searchQuery.toLowerCase())
    );

    const isLimitReached = limits && !limits.isUnlimited && limits.currentFiles >= limits.maxFiles;
    const isCropMode = aspect && !multiple && selectedIds.size === 1 && activeFile?.file_type === 'image';
    return ReactDOM.createPortal(
        <>
            <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-30000 p-4 sm:p-6">
                <DragDropWrapper 
                    onDropFiles={handleUpload}
                    isError={isLimitReached}
                    errorText="Ліміт файлів вичерпано!"
                    className="relative bg-(--platform-bg) w-full max-w-5xl h-[90vh] sm:h-[85vh] rounded-2xl flex flex-col shadow-2xl border border-(--platform-border-color) overflow-hidden animate-in zoom-in-95 duration-200"
                >
                    <div className="p-4 sm:px-6 sm:py-4 bg-(--platform-card-bg) border-b border-(--platform-border-color) flex justify-between items-center shrink-0">
                        <div className="flex items-center gap-3 font-semibold text-(--platform-text-primary)">
                            <Image size={24} className="text-(--platform-accent) hidden sm:block" />
                            <h3 className="m-0 text-lg sm:text-xl">{title}</h3>
                        </div>
                        <div className="flex items-center gap-3">
                            {limits && (
                                <div className={`hidden sm:flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-medium border transition-all
                                    ${(!limits.isUnlimited && limits.percentageUsed >= 90) 
                                        ? 'bg-[color-mix(in_srgb,var(--platform-accent),transparent_90%)] text-(--platform-accent) border-[color-mix(in_srgb,var(--platform-accent),transparent_70%)]' 
                                        : 'text-(--platform-text-secondary) bg-(--platform-hover-bg) border-(--platform-border-color)'
                                    }
                                `}>
                                    <HardDrive size={14} className="shrink-0" />
                                    <span>Сховище: {limits.isUnlimited ? `${limits.currentFiles} / ∞` : `${limits.currentFiles} / ${limits.maxFiles}`}</span>
                                </div>
                            )}
                            <button 
                                className="w-8 h-8 rounded-full flex items-center justify-center bg-transparent hover:bg-black/5 dark:hover:bg-white/5 border-none text-(--platform-text-secondary) transition-colors cursor-pointer"
                                onClick={onClose}
                                title="Закрити"
                            >
                                <X size={20}/>
                            </button>
                        </div>
                    </div>
                    <div className="p-3 sm:px-6 sm:py-3 flex flex-col sm:flex-row gap-3 bg-(--platform-bg) border-b border-(--platform-border-color) shrink-0 items-stretch sm:items-center">
                        <div className="relative flex-1">
                            <div className="absolute left-0 top-0 bottom-0 w-10 flex items-center justify-center text-(--platform-text-secondary) pointer-events-none">
                                <Search size={18} />
                            </div>
                            <input 
                                type="text" 
                                placeholder="Пошук у медіатеці..." 
                                value={searchQuery} 
                                onChange={e => setSearchQuery(e.target.value)} 
                                className="w-full h-10 pl-10 pr-3 rounded-lg border border-(--platform-border-color) bg-(--platform-input-bg) text-(--platform-text-primary) text-sm focus:outline-none focus:border-(--platform-accent) transition-colors"
                            />
                        </div>
                        <Button 
                            variant="primary"
                            icon={<Upload size={16} className="mr-1.5 shrink-0" />}
                            className="h-10 whitespace-nowrap justify-center w-full sm:w-auto"
                            onClick={() => fileInputRef.current?.click()}
                            disabled={isLimitReached}
                            title={isLimitReached ? "Ліміт файлів вичерпано" : ""}
                        >
                            {isLimitReached ? 'Ліміт вичерпано' : 'Завантажити'}
                        </Button>
                        <input 
                            type="file" 
                            multiple 
                            ref={fileInputRef} 
                            className="hidden"
                            onChange={handleUpload} 
                            accept={limits ? limits.allowedExtensions.join(',') : undefined} 
                        />
                    </div>
                    <div className="flex flex-col sm:flex-row flex-1 overflow-hidden relative">
                        <div className="flex-1 overflow-y-auto p-4 sm:p-6 hide-scrollbar relative">
                            {loading ? (
                                <div className="flex items-center justify-center h-full min-h-50 text-(--platform-text-secondary) italic">
                                    <LoadingState />
                                </div>
                            ) : filteredFiles.length === 0 ? (
                                <div className="flex items-center justify-center h-full min-h-50 text-center text-(--platform-text-secondary) italic px-4">
                                    {files.length === 0 
                                        ? `Немає файлів типу: ${allowedTypes.join(', ')}` 
                                        : 'Нічого не знайдено за запитом'}
                                </div>
                            ) : (
                                <div className="grid grid-cols-[repeat(auto-fill,minmax(110px,1fr))] sm:grid-cols-[repeat(auto-fill,minmax(140px,1fr))] gap-3 sm:gap-4 pb-20 sm:pb-0">
                                    {filteredFiles.map(file => {
                                        const isSelected = selectedIds.has(file.id);
                                        const isActive = activeFile?.id === file.id;
                                        return (
                                            <div 
                                                key={file.id} 
                                                className={`
                                                    relative aspect-square rounded-xl bg-(--platform-card-bg) overflow-hidden cursor-pointer transition-all duration-200
                                                    ${isSelected ? 'border-2 border-(--platform-accent) scale-95 shadow-md' : 'border border-transparent shadow-sm'}
                                                    ${isActive && !isSelected ? 'ring-2 ring-(--platform-accent)/50 shadow-lg' : ''}
                                                `}
                                                style={{ backgroundImage: "url('https://transparenttextures.com/patterns/cubes.png')", backgroundRepeat: 'repeat' }}
                                                onClick={() => handleFileClick(file)}
                                            >
                                                <MediaFilePreview file={file} className="w-full h-full object-cover" />
                                                {isSelected && (
                                                    <div className="absolute top-1.5 right-1.5 sm:top-2 sm:right-2 w-6 h-6 rounded-full bg-(--platform-accent) text-white flex items-center justify-center z-10 shadow-sm animate-in zoom-in">
                                                        <Check size={14} className="shrink-0" />
                                                    </div>
                                                )}
                                                <div className="absolute bottom-0 left-0 right-0 bg-linear-to-t from-black/85 to-transparent p-2 pt-6 text-white text-[11px] sm:text-xs whitespace-nowrap overflow-hidden text-ellipsis pointer-events-none">
                                                    {file.original_file_name}
                                                </div>
                                            </div>
                                        );
                                    })}
                                </div>
                            )}
                        </div>
                        {activeFile && (
                            <div className="absolute bottom-0 left-0 right-0 sm:relative sm:w-[320px] shrink-0 sm:border-l border-t sm:border-t-0 border-(--platform-border-color) bg-(--platform-sidebar-bg) p-4 sm:p-6 flex flex-row sm:flex-col gap-4 overflow-y-auto hide-scrollbar z-20 shadow-[0_-10px_20px_rgba(0,0,0,0.1)] sm:shadow-none max-h-[40vh] sm:max-h-none">
                                <div className="w-24 h-24 sm:w-full sm:h-auto sm:aspect-16/10 rounded-lg overflow-hidden border border-(--platform-border-color) flex items-center justify-center shrink-0 relative bg-(--platform-bg)" style={{ backgroundImage: "url('https://transparenttextures.com/patterns/cubes.png')" }}>
                                    <MediaFilePreview 
                                        file={activeFile} 
                                        showVideoControls={true} 
                                        onVideoMetadata={(e) => setVideoDuration(e.target.duration)} 
                                        className="w-full h-full object-cover"
                                    />
                                </div>
                                <div className="flex flex-col gap-2 overflow-hidden flex-1">
                                    <p className="font-semibold m-0 break-all text-(--platform-text-primary) text-sm sm:text-base leading-tight">
                                        {activeFile.original_file_name}
                                    </p>
                                    <div className="flex flex-col gap-1.5 text-xs sm:text-sm text-(--platform-text-secondary) mt-1">
                                        <span className="flex items-center gap-2 truncate">
                                            <FileText size={14} className="opacity-70 shrink-0" /> {activeFile.file_size_kb} KB
                                        </span>
                                        <span className="flex items-center gap-2 truncate">
                                            <Calendar size={14} className="opacity-70 shrink-0" /> {new Date(activeFile.created_at).toLocaleDateString()}
                                        </span>
                                        {activeFile.file_type === 'video' && videoDuration && (
                                            <span className="flex items-center gap-2 text-(--platform-accent) truncate">
                                                <Clock size={14} className="shrink-0" /> Тривалість: {formatDuration(videoDuration)}
                                            </span>
                                        )}
                                    </div>
                                </div>
                            </div>
                        )}
                    </div>
                    <div className="p-4 sm:px-6 sm:py-4 border-t border-(--platform-border-color) bg-(--platform-card-bg) flex flex-row justify-between items-center shrink-0 z-30">
                        <div className="text-sm font-medium text-(--platform-text-primary) whitespace-nowrap">
                            Вибрано: <span className="text-(--platform-accent) font-bold">{selectedIds.size}</span>
                            <span className="hidden sm:inline"> {multiple ? 'файлів' : 'файл'}</span>
                        </div>
                        <div className="flex gap-2 sm:gap-3">
                            <Button variant="outline" onClick={onClose} className="h-10 px-3 sm:px-4">
                                Скасувати
                            </Button>
                            <Button 
                                variant="primary" 
                                onClick={handleSubmit} 
                                disabled={selectedIds.size === 0}
                                className="h-10 px-4 sm:px-6 min-w-25 justify-center"
                            >
                                {isCropMode ? 'Далі' : 'Підтвердити'}
                            </Button>
                        </div>
                    </div>
                </DragDropWrapper>
            </div>
            <ImageCropperModal
                isOpen={cropModalOpen}
                imageSrc={imageToCrop}
                aspect={aspect}
                onClose={() => setCropModalOpen(false)}
                onCropComplete={handleCropFinished}
            />
            <style>{`
                .hide-scrollbar::-webkit-scrollbar { display: none; }
                .hide-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }
            `}</style>
        </>,
        document.body
    );
};

export default MediaPickerModal;

// frontend/src/modules/media/pages/MediaLibraryPage.jsx
import React, { useState, useEffect, useRef, useMemo, useCallback } from 'react';
import apiClient from '../../../shared/api/api';
import MediaGridItem from '../components/MediaGridItem';
import MediaInspector from '../components/MediaInspector';
import SiteFilters from '../../../shared/ui/complex/SiteFilters';
import EmptyState from '../../../shared/ui/complex/EmptyState';
import LoadingState from '../../../shared/ui/complex/LoadingState';
import DragDropWrapper from '../../../shared/ui/complex/DragDropWrapper';
import { toast } from 'react-toastify';
import { useConfirm } from '../../../shared/hooks/useConfirm';
import { Button } from '../../../shared/ui/elements';
import { BASE_URL } from '../../../shared/config';
import { FILE_LIMITS } from '../../../shared/config/limits';
import JSZip from 'jszip';
import { saveAs } from 'file-saver';
import { Upload, Search, Download, Trash2, Check, X as XIcon, HardDrive } from 'lucide-react';

const FILE_TYPES = [
    { id: 'image', name: 'Фото' },
    { id: 'video', name: 'Відео' },
    { id: 'font', name: 'Шрифти' }
];

const FORMATS_BY_TYPE = {
    image: ['jpg', 'jpeg', 'png', 'gif', 'webp', 'svg', 'ico', 'bmp'],
    video: ['mp4', 'webm', 'mov', 'avi', 'mkv'],
    font: ['ttf', 'otf', 'woff', 'woff2'],
    all: []
};

const SORT_OPTIONS = [
    { value: 'created_at:desc', label: 'Дата' },
    { value: 'created_at:asc', label: 'Дата' },
    { value: 'file_size_kb:desc', label: 'Розмір' },
    { value: 'file_size_kb:asc', label: 'Розмір' },
    { value: 'original_file_name:asc', label: 'Назва' },
    { value: 'original_file_name:desc', label: 'Назва' }
];

const MediaLibraryPage = () => {
    const [files, setFiles] = useState([]);
    const [loading, setLoading] = useState(true);
    const [limits, setLimits] = useState(null);
    const [searchTerm, setSearchTerm] = useState('');
    const [activeType, setActiveType] = useState(null);
    const [activeFormat, setActiveFormat] = useState(null);
    const [sortOption, setSortOption] = useState('created_at:desc');
    const [onlyFavorites, setOnlyFavorites] = useState(false);
    const [visibleCount, setVisibleCount] = useState(48);
    const [selectedFile, setSelectedFile] = useState(null);
    const [checkedFiles, setCheckedFiles] = useState(new Set());
    const lastSelectedIndex = useRef(null);
    const fileInputRef = useRef(null);
    const { confirm } = useConfirm();
    useEffect(() => {
        fetchData();
    }, []);

    const fetchData = async () => {
        setLoading(true);
        try {
            const [mediaRes, limitsRes] = await Promise.all([
                apiClient.get('/media'),
                apiClient.get('/media/limits')
            ]);
            setFiles(Array.isArray(mediaRes.data) ? mediaRes.data : []);
            setLimits(limitsRes.data);
        } catch (error) {
            console.error(error);
            toast.error('Помилка завантаження медіатеки');
        } finally {
            setLoading(false);
        }
    };

    const fetchLimits = async () => {
        try {
            const res = await apiClient.get('/media/limits');
            setLimits(res.data);
        } catch (error) {
            console.error("Помилка оновлення лімітів", error);
        }
    };

    useEffect(() => {
        setActiveFormat(null);
    }, [activeType]);

    const filteredFiles = useMemo(() => {
        if (!files) return [];
        let result = [...files];
        if (searchTerm) {
            const lowerQuery = searchTerm.toLowerCase();
            result = result.filter(f => 
                (f.display_name || f.original_file_name || '').toLowerCase().includes(lowerQuery)
            );
        }
        if (onlyFavorites) {
            result = result.filter(f => f.is_favorite);
        }
        if (activeType) {
            result = result.filter(f => {
                if (f.file_type === activeType) return true;
                const ext = (f.original_file_name || '').split('.').pop().toLowerCase();
                return FORMATS_BY_TYPE[activeType]?.includes(ext);
            });
        }
        if (activeFormat) {
            result = result.filter(f => {
                const ext = (f.original_file_name || '').split('.').pop().toLowerCase();
                if (activeFormat === 'jpg' && ext === 'jpeg') return true;
                return ext === activeFormat;
            });
        }
        const [key, dir] = sortOption.split(':');
        result.sort((a, b) => {
            let valA = a[key];
            let valB = b[key];
            if (key === 'original_file_name' || key === 'display_name') {
                valA = (valA || '').toLowerCase();
                valB = (valB || '').toLowerCase();
                return dir === 'asc' ? valA.localeCompare(valB) : valB.localeCompare(valA);
            }
            if (key === 'created_at') {
                valA = new Date(valA || 0).getTime();
                valB = new Date(valB || 0).getTime();
            } else {
                valA = Number(valA || 0);
                valB = Number(valB || 0);
            }
            if (valA < valB) return dir === 'asc' ? -1 : 1;
            if (valA > valB) return dir === 'asc' ? 1 : -1;
            return 0;
        });
        return result;
    }, [files, searchTerm, activeType, activeFormat, sortOption, onlyFavorites]);

    const visibleFiles = filteredFiles.slice(0, visibleCount);
    const remainingCount = filteredFiles.length - visibleFiles.length;
    const handleUpload = async (eOrFiles) => {
        const fileList = eOrFiles.target ? eOrFiles.target.files : eOrFiles;
        if (!fileList || fileList.length === 0) return;
        const toastId = toast.loading("Завантаження...");
        let successCount = 0;
        let failedFiles = [];
        for (let i = 0; i < fileList.length; i++) {
            const file = fileList[i];
            if (file.size > FILE_LIMITS.MEDIA_LIBRARY.MAX_SIZE) {
                failedFiles.push({ 
                    name: file.name, 
                    reason: `Розмір перевищує ${FILE_LIMITS.MEDIA_LIBRARY.MAX_SIZE / (1024 * 1024)}MB` 
                });
                continue;
            }
            const formData = new FormData();
            formData.append('mediaFile', file);
            try {
                const res = await apiClient.post('/media/upload', formData);
                if (res.data && res.data.error) {
                    failedFiles.push({ name: file.name, reason: res.data.message });
                    if (res.data.code === 'MAX_FILES_REACHED') {
                        break;
                    }
                    continue; 
                }
                if (res && res.data && res.data.id) {
                    setFiles(prev => [res.data, ...prev]);
                    successCount++;
                }
            } catch (err) {
                console.error("Справжня помилка завантаження:", err);
                failedFiles.push({ 
                    name: file.name, 
                    reason: err.response?.data?.message || "Непередбачена помилка сервера" 
                });
            }
        }
        toast.dismiss(toastId);
        if (successCount > 0) {
            toast.success(`Успішно завантажено: ${successCount} файлів`);
            fetchLimits(); 
        }
        if (failedFiles.length > 0) {
            const limit = 3; 
            const errorList = failedFiles.slice(0, limit)
                .map(f => `• ${f.name} (${f.reason})`)
                .join('\n');
            const moreCount = failedFiles.length - limit;
            const finalMessage = moreCount > 0 
                ? `Не завантажено ${failedFiles.length} файлів:\n${errorList}\n...та ще ${moreCount}`
                : `Не завантажено:\n${errorList}`;
            toast.error(
                <div style={{ whiteSpace: 'pre-wrap', fontSize: '0.85rem', lineHeight: '1.4' }}>
                    {finalMessage}
                </div>, 
                { autoClose: 7000 } 
            );
        }
        if (fileInputRef.current) fileInputRef.current.value = '';
    };

    const handleUpdateFile = useCallback((updatedFile) => {
        setFiles(prev => prev.map(f => f.id === updatedFile.id ? updatedFile : f));
        setSelectedFile(prev => prev?.id === updatedFile.id ? updatedFile : prev);
    }, []);

    const handleToggleFavorite = useCallback(async (file) => {
        const newStatus = !file.is_favorite;
        handleUpdateFile({ ...file, is_favorite: newStatus });
        try {
            await apiClient.put(`/media/${file.id}`, { is_favorite: newStatus });
        } catch (error) {
            handleUpdateFile({ ...file, is_favorite: !newStatus });
        }
    }, [handleUpdateFile]);

    const handleDelete = async (file) => {
        if (await confirm({ title: "Видалити файл?", message: "Ця дія незворотна.", type: "danger", confirmLabel: "Видалити" })) {
            try {
                await apiClient.delete(`/media/${file.id}`);
                setFiles(prev => prev.filter(f => f.id !== file.id));
                setSelectedFile(null);
                setCheckedFiles(prev => {
                    const next = new Set(prev);
                    next.delete(file.id);
                    return next;
                });
                toast.success('Файл видалено');
                fetchLimits();
            } catch (error) {
            }
        }
    };

    const handleCheckFile = useCallback((file, index, e) => {
        if (e?.shiftKey && lastSelectedIndex.current !== null) {
            const start = Math.min(lastSelectedIndex.current, index);
            const end = Math.max(lastSelectedIndex.current, index);
            const filesRange = visibleFiles.slice(start, end + 1);
            setCheckedFiles(prev => {
                const next = new Set(prev);
                filesRange.forEach(f => next.add(f.id));
                return next;
            });
        } else {
            setCheckedFiles(prev => {
                const next = new Set(prev);
                next.has(file.id) ? next.delete(file.id) : next.add(file.id);
                return next;
            });
        }
        lastSelectedIndex.current = index;
    }, [visibleFiles]);

    const handleCardClick = useCallback((file, index, e) => {
        if (e?.ctrlKey || e?.metaKey) {
            handleCheckFile(file, index, e);
        } else {
            setSelectedFile(prev => (prev && prev.id === file.id ? null : file));
            lastSelectedIndex.current = index;
        }
    }, [handleCheckFile]);

    const handleGridBackgroundClick = (e) => {
        if (e.target === e.currentTarget) {
            setSelectedFile(null);
        }
    };

    const handleSelectAll = () => {
        setCheckedFiles(new Set(filteredFiles.map(f => f.id)));
    };

    const handleDeselectAll = () => {
        setCheckedFiles(new Set());
    };

    const getDownloadUrl = (path) => {
        if (!path) return '';
        return path.startsWith('http') ? path : `${BASE_URL}${path}`;
    };

    const handleBulkDownload = async () => {
        const filesToDownload = files.filter(f => checkedFiles.has(f.id));
        if (filesToDownload.length === 0) return;
        if (filesToDownload.length === 1) {
            const file = filesToDownload[0];
            try {
                const response = await fetch(getDownloadUrl(file.path_full));
                if (!response.ok) throw new Error('Network error');
                const blob = await response.blob();
                const url = window.URL.createObjectURL(blob);
                const a = document.createElement('a');
                a.style.display = 'none';
                a.href = url;
                a.download = file.original_file_name || `download-${Date.now()}`;
                document.body.appendChild(a);
                a.click();
                window.URL.revokeObjectURL(url);
                document.body.removeChild(a);
            } catch (error) {
                console.error("Download failed:", error);
                toast.error("Помилка при завантаженні файлу");
            }
            setCheckedFiles(new Set());
            return;
        }
        const toastId = toast.loading(`Збираємо архів з ${filesToDownload.length} файлів...`);
        try {
            const zip = new JSZip();
            const fetchPromises = filesToDownload.map(async (file) => {
                const response = await fetch(getDownloadUrl(file.path_full));
                if (!response.ok) throw new Error(`Failed to fetch ${file.original_file_name}`);
                const blob = await response.blob();
                const fileName = file.original_file_name || `file_${file.id}`;
                zip.file(fileName, blob);
            });
            await Promise.all(fetchPromises);
            const zipContent = await zip.generateAsync({ type: 'blob' });
            saveAs(zipContent, `media_export_${Date.now()}.zip`);
            toast.update(toastId, { render: "Архів успішно завантажено!", type: "success", isLoading: false, autoClose: 3000 });
            setCheckedFiles(new Set());
        } catch (error) {
            console.error("ZIP Generation failed:", error);
            toast.update(toastId, { render: "Помилка при створенні архіву", type: "error", isLoading: false, autoClose: 3000 });
        }
    };

    const handleBulkDelete = async () => {
        const filesToDelete = files.filter(f => checkedFiles.has(f.id));
        if (filesToDelete.length === 0) return;
        if (await confirm({ title: "Видалити вибрані файли?", message: `Ви впевнені, що хочете видалити ${filesToDelete.length} файлів? Ця дія незворотна.`, type: "danger", confirmLabel: "Видалити" })) {
            const toastId = toast.loading(`Видалення ${filesToDelete.length} файлів...`);
            try {
                const deletePromises = filesToDelete.map(file => apiClient.delete(`/media/${file.id}`));
                await Promise.all(deletePromises);
                setFiles(prev => prev.filter(f => !checkedFiles.has(f.id)));
                setCheckedFiles(new Set());
                setSelectedFile(null);
                toast.update(toastId, { render: "Файли успішно видалено", type: "success", isLoading: false, autoClose: 3000 });
                fetchLimits();
            } catch (error) {
                console.error("Bulk delete failed:", error);
                toast.update(toastId, { render: "Помилка при видаленні файлів", type: "error", isLoading: false, autoClose: 3000 });
            }
        }
    };

    const formatButtons = (activeType && FORMATS_BY_TYPE[activeType]?.length > 0) ? (
        <div className="flex gap-2 items-center shrink-0">
            <button 
                className={`h-8 px-3 rounded-full text-xs font-medium uppercase transition-colors whitespace-nowrap border shrink-0 ${!activeFormat ? 'border-(--platform-accent) text-(--platform-accent) bg-[color-mix(in_srgb,var(--platform-accent),transparent_90%)]' : 'border-(--platform-border-color) text-(--platform-text-secondary) bg-transparent hover:bg-(--platform-hover-bg)'}`} 
                onClick={() => setActiveFormat(null)}
            >
                Всі формати
            </button>
            {FORMATS_BY_TYPE[activeType].map(fmt => (
                <button 
                    key={fmt} 
                    className={`h-8 px-3 rounded-full text-xs font-medium uppercase transition-colors whitespace-nowrap border shrink-0 ${activeFormat === fmt ? 'border-(--platform-accent) text-(--platform-accent) bg-[color-mix(in_srgb,var(--platform-accent),transparent_90%)]' : 'border-(--platform-border-color) text-(--platform-text-secondary) bg-transparent hover:bg-(--platform-hover-bg)'}`} 
                    onClick={() => setActiveFormat(activeFormat === fmt ? null : fmt)}
                >
                    {fmt}
                </button>
            ))}
        </div>
    ) : null;

    const isLimitReached = limits && !limits.isUnlimited && limits.currentFiles >= limits.maxFiles;
    return (
        <DragDropWrapper 
            onDropFiles={handleUpload}
            isError={isLimitReached}
            errorText="Ліміт файлів вичерпано!"
            className="flex flex-col flex-1 min-h-0 bg-(--platform-bg) relative"
        >
            <div className="shrink-0 bg-(--platform-bg) z-10 flex flex-col">
                <div className="h-auto sm:h-16 px-4 py-4 sm:px-8 lg:px-10 sm:py-0 border-b border-(--platform-border-color) flex flex-col sm:flex-row items-center justify-between gap-4 w-full">
                    <div className="w-full sm:w-1/3 flex justify-center sm:justify-start shrink-0">
                        {limits && (
                            <div className={`flex items-center gap-2 px-3.5 py-1.5 rounded-full text-xs font-medium border shadow-sm transition-colors ${(!limits.isUnlimited && limits.percentageUsed >= 90) ? 'bg-[color-mix(in_srgb,var(--platform-accent),transparent_90%)] text-(--platform-accent) border-[color-mix(in_srgb,var(--platform-accent),transparent_70%)]' : 'text-(--platform-text-secondary) bg-(--platform-card-bg) border-(--platform-border-color)'}`}>
                                <HardDrive size={16} className="shrink-0" />
                                <span>Сховище: {limits.isUnlimited ? `${limits.currentFiles} / ∞` : `${limits.currentFiles} / ${limits.maxFiles}`}</span>
                            </div>
                        )}
                    </div>
                    <div className="w-full sm:w-1/3 flex justify-center shrink-0">
                        <h1 className="text-xl font-bold m-0 text-(--platform-text-primary)">
                            Медіатека
                        </h1>
                    </div>
                    <div className="w-full sm:w-1/3 flex justify-center sm:justify-end shrink-0">
                        <Button 
                            variant="primary" 
                            type="button" 
                            onClick={() => fileInputRef.current.click()}
                            disabled={isLimitReached}
                            className="w-full sm:w-auto h-10 shadow-sm"
                        >
                            <Upload size={18} className="shrink-0 mr-1.5" /> 
                            <span>{isLimitReached ? 'Ліміт вичерпано' : 'Завантажити'}</span>
                        </Button>
                        <input 
                            type="file" 
                            multiple 
                            ref={fileInputRef} 
                            className="hidden" 
                            onChange={handleUpload}
                            accept={limits ? limits.allowedExtensions.join(',') : undefined} 
                        />
                    </div>
                </div>
                <SiteFilters 
                    searchTerm={searchTerm}
                    onSearchChange={setSearchTerm}
                    sortOption={sortOption}
                    onSortChange={setSortOption}
                    sortOptions={SORT_OPTIONS}
                    tags={FILE_TYPES}
                    selectedTag={activeType}
                    onTagSelect={setActiveType}
                    showStarFilter={true}
                    isStarActive={onlyFavorites}
                    onStarClick={() => setOnlyFavorites(!onlyFavorites)}
                    afterTags={formatButtons}
                />
            </div>
            <div className="flex flex-1 min-h-0 overflow-hidden relative">
                <div 
                    className={`flex-1 p-4 sm:p-8 lg:p-10 overflow-y-auto min-w-0 ${!loading && filteredFiles.length === 0 ? 'flex flex-col items-center justify-center' : ''}`}
                    onClick={handleGridBackgroundClick}
                >
                    {loading ? (
                        <LoadingState />
                    ) : filteredFiles.length === 0 ? (
                        <EmptyState 
                            title="Файлів не знайдено"
                            description="Спробуйте змінити фільтри або завантажити нові файли"
                            icon={Search}
                            action={
                                (searchTerm || activeType || onlyFavorites) && (
                                    <Button variant="ghost" onClick={() => { setSearchTerm(''); setActiveType(null); setOnlyFavorites(false); }}>
                                        Очистити фільтри
                                    </Button>
                                )
                            }
                        />
                    ) : (
                        <>
                            <div className="grid grid-cols-[repeat(auto-fill,minmax(110px,1fr))] sm:grid-cols-[repeat(auto-fill,minmax(140px,1fr))] gap-3 sm:gap-4 pb-6">
                                {visibleFiles.map((file, index) => (
                                    <MediaGridItem 
                                        key={file.id} 
                                        file={file} 
                                        selected={selectedFile?.id === file.id}
                                        onSelect={(f, e) => handleCardClick(f, index, e)}
                                        onToggleFavorite={() => handleToggleFavorite(file)}
                                        isChecked={checkedFiles.has(file.id)}
                                        onCheck={(f, e) => handleCheckFile(f, index, e)}
                                    />
                                ))}
                            </div>
                            {remainingCount > 0 && (
                                <div className="text-center mt-6 pb-6">
                                    <Button variant="outline" onClick={() => setVisibleCount(p => p + 48)} className="rounded-full px-6">
                                        Показати ще ({remainingCount})
                                    </Button>
                                </div>
                            )}
                        </>
                    )}
                </div>
                {selectedFile && (
                    <div className="fixed inset-0 z-100 sm:relative sm:inset-auto w-full sm:w-90 border-l border-(--platform-border-color) bg-(--platform-sidebar-bg) overflow-y-auto shrink-0 hide-scrollbar transition-transform duration-300">
                        <MediaInspector 
                            file={selectedFile} 
                            onUpdate={handleUpdateFile}
                            onDelete={handleDelete}
                            onClose={() => setSelectedFile(null)}
                        />
                    </div>
                )}
            </div>
            <div className="shrink-0 px-4 sm:px-8 lg:px-10 py-3 sm:py-0 min-h-12 border-t border-(--platform-border-color) bg-(--platform-bg) flex flex-col sm:flex-row justify-between items-stretch sm:items-center text-xs sm:text-sm text-(--platform-text-secondary) z-10 gap-3 sm:gap-0">
                <div className="flex flex-wrap items-center gap-2 sm:gap-3">
                    <span className="whitespace-nowrap font-medium">Виділено: {checkedFiles.size} з {files.length}</span>
                    <div className="hidden sm:block w-px h-4 bg-(--platform-border-color)" />
                    <Button variant="ghost" onClick={handleSelectAll} className="h-8 px-2.5">
                        <Check size={14} className="mr-1.5" /> Вибрати все
                    </Button>
                    {checkedFiles.size > 0 && (
                        <Button 
                            variant="ghost" 
                            onClick={handleDeselectAll} 
                            className="h-8 px-2.5 text-(--platform-text-secondary)"
                            title="Скинути виділення"
                        >
                            <XIcon size={14} className="mr-1.5" /> Скинути ({checkedFiles.size})
                        </Button>
                    )}
                </div>
                {checkedFiles.size > 0 ? (
                    <div className="flex flex-wrap items-center gap-2 justify-end border-t sm:border-none border-(--platform-border-color) pt-2 sm:pt-0">
                        <Button variant="ghost" onClick={handleBulkDownload} className="h-8 px-3 text-(--platform-text-primary)">
                            <Download size={14} className="mr-1.5" /> Завантажити
                        </Button>
                        <Button 
                            variant="ghost"
                            onClick={handleBulkDelete} 
                            className="h-8 px-3 text-(--platform-danger) hover:bg-red-50"
                        >
                            <Trash2 size={14} className="mr-1.5" /> Видалити
                        </Button>
                    </div>
                ) : (
                    <div className="max-w-50 sm:max-w-75 truncate text-right hidden sm:block font-medium">
                        {selectedFile ? (selectedFile.original_file_name || selectedFile.display_name) : 'Файл не обрано'}
                    </div>
                )}
            </div>
            <style>{`
                .hide-scrollbar::-webkit-scrollbar { display: none; }
                .hide-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }
            `}</style>
        </DragDropWrapper>
    );
};

export default MediaLibraryPage;

// frontend/src/modules/profile/pages/ProfilePage.jsx
import React, { useState, useEffect, useContext, useCallback } from 'react';
import { useParams, Link, useNavigate } from 'react-router-dom';
import { Helmet } from 'react-helmet-async';
import { toast } from 'react-toastify';
import apiClient, { suspendUser, restoreUser } from '../../../shared/api/api';
import { AuthContext } from '../../../app/providers/AuthContext';
import { useConfirm } from '../../../shared/hooks/useConfirm';
import { Button } from '../../../shared/ui/elements/Button';
import Avatar from '../../../shared/ui/elements/Avatar';
import SiteGridCard from '../../../shared/ui/complex/SiteGridCard'; 
import SiteFilters from '../../../shared/ui/complex/SiteFilters';
import LoadingState from '../../../shared/ui/complex/LoadingState';
import UserDetailsPanel from '../../admin/components/UserDetailsPanel';
import NotFoundPage from '../../../pages/NotFoundPage';
import { Send, Instagram, Globe, Settings, Calendar, Grid, User as UserIcon, ExternalLink, EyeOff, Layout, ShieldAlert, AlertTriangle, Shield } from 'lucide-react';

const SORT_OPTIONS = [
    { value: 'created_at:desc', label: 'Нові' },
    { value: 'created_at:asc', label: 'Старі' },
    { value: 'views:desc', label: 'Популярні' },
    { value: 'title:asc', label: 'Назва (А-Я)' },
];

const getFormattedDate = (dateString) => {
    if (!dateString) return 'Невідомо';
    try {
        let safeString = typeof dateString === 'string' ? dateString.trim() : dateString;
        if (typeof safeString === 'string' && /^\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2}/.test(safeString)) {
            safeString = safeString.replace(' ', 'T');
        }
        const date = new Date(safeString);
        if (isNaN(date.getTime())) {
            console.error("Не вдалося розпарсити дату на хостингу:", dateString);
            return 'Невідомо';
        }
        return date.toLocaleDateString('uk-UA');
    } catch (e) {
        return 'Невідомо';
    }
};

const ProfilePage = () => {
    const { slug } = useParams();
    const navigate = useNavigate();
    const { confirm } = useConfirm();
    const { user: authUser } = useContext(AuthContext);
    const [profileData, setProfileData] = useState(null);
    const [loadingProfile, setLoadingProfile] = useState(true);
    const [errorStatus, setErrorStatus] = useState(null);
    const [userSites, setUserSites] = useState([]);
    const [sitesLoading, setSitesLoading] = useState(false);
    const [searchTerm, setSearchTerm] = useState('');
    const [sortOption, setSortOption] = useState('created_at:desc');
    const [isAdminPanelOpen, setIsAdminPanelOpen] = useState(false);
    const isOwner = authUser && authUser.slug === slug;
    useEffect(() => {
        if (isOwner && (authUser?.role === 'admin' || authUser?.role === 'moderator')) {
            setErrorStatus(404);
            setLoadingProfile(false);
            return;
        }
        const fetchProfile = async () => {
            try {
                setLoadingProfile(true);
                setErrorStatus(null);
                const response = await apiClient.get(`/users/${slug}`, {
                    suppressToast: true
                });
                const data = response.data?.user || response.data?.data || response.data;
                if (data && (data.role === 'admin' || data.role === 'moderator')) {
                    setErrorStatus(404);
                    return;
                }
                setProfileData(data);
            } catch (err) {
                if (err.response) {
                    setErrorStatus(err.response.status);
                } else {
                    setErrorStatus(500);
                }
            } finally {
                setLoadingProfile(false);
            }
        };
        fetchProfile();
    }, [slug, isOwner, authUser]);

    const fetchUserSites = useCallback(async () => {
        if (!profileData) return;
        try {
            setSitesLoading(true);
            const params = {
                userId: profileData.id,
                search: searchTerm,
                sort: sortOption,
            };
            const res = await apiClient.get('/sites/catalog', { params });
            setUserSites(res.data);
        } catch (error) {
            console.error("Failed to load user sites", error);
        } finally {
            setSitesLoading(false);
        }
    }, [profileData, searchTerm, sortOption]);

    useEffect(() => {
        if (profileData) {
            const timer = setTimeout(() => {
                fetchUserSites();
            }, 300);
            return () => clearTimeout(timer);
        }
    }, [fetchUserSites]);

    const handleDeleteUser = (userId) => {
        confirm({ 
            title: 'Видалити акаунт?', 
            message: 'Ця дія незворотна. Всі дані будуть видалені. Введіть "DELETE" для підтвердження.', 
            requireInput: true,
            expectedInput: 'DELETE',
            confirmText: 'Видалити повністю', 
            danger: true,
            onConfirm: async (inputValue) => { 
                if (inputValue !== 'DELETE') return toast.error('Невірне підтвердження.');
                try { 
                    await apiClient.delete(`/admin/users/${userId}`); 
                    toast.success('Користувача видалено'); 
                    setIsAdminPanelOpen(false);
                    navigate('/'); 
                } catch { toast.error('Помилка видалення'); } 
            } 
        });
    };

    const handleSuspendUser = (userId) => {
        confirm({ 
            title: 'Заблокувати назавжди?', 
            message: 'Пошта залишиться в блеклісті, але сайти, медіафайли та персональні дані будуть незворотно стерті. Введіть "SUSPEND" для підтвердження.', 
            requireInput: true,
            expectedInput: 'SUSPEND',
            confirmText: 'Заблокувати', 
            danger: true,
            onConfirm: async (inputValue) => { 
                if (inputValue !== 'SUSPEND') return toast.error('Невірне підтвердження.');
                try { 
                    await suspendUser(userId); 
                    toast.success('Користувача заблоковано'); 
                    setProfileData(prev => ({ ...prev, status: 'suspended' }));
                    setIsAdminPanelOpen(false);
                } catch (error) { toast.error(error.response?.data?.message || 'Помилка блокування'); } 
            } 
        });
    };

    const handleRestoreUser = (userId) => {
        confirm({ 
            title: 'Розблокувати акаунт?', 
            message: 'Користувач знову зможе користуватися платформою. Введіть "RESTORE" для підтвердження.', 
            type: 'success',
            requireInput: true,
            expectedInput: 'RESTORE',
            confirmText: 'Розблокувати',
            onConfirm: async (inputValue) => { 
                if (inputValue !== 'RESTORE') return toast.error('Невірне підтвердження.');
                try { 
                    await restoreUser(userId); 
                    toast.success('Користувача розблоковано'); 
                    setProfileData(prev => ({ ...prev, status: 'published' }));
                    setIsAdminPanelOpen(false);
                } catch (error) { toast.error(error.response?.data?.message || 'Помилка розблокування'); } 
            } 
        });
    };

    if (loadingProfile) return <LoadingState />;
    if (errorStatus === 403) {
        return (
            <div className="flex flex-col items-center justify-center min-h-[calc(100vh-150px)] w-full text-center text-(--platform-text-secondary) p-6 sm:p-8">
                <Helmet><title>Приватний профіль | Kendr</title></Helmet>
                <div className="w-20 h-20 bg-(--platform-bg) rounded-full flex items-center justify-center mb-6 border border-(--platform-border-color)">
                    <EyeOff size={40} />
                </div>
                <h2 className="text-xl sm:text-2xl text-(--platform-text-primary) font-bold mb-2">Цей профіль закритий</h2>
                <p className="max-w-100 leading-relaxed text-sm sm:text-base mb-6">Користувач обмежив доступ до своєї сторінки.</p>
                <Link to="/" className="no-underline"><Button variant="secondary">На головну</Button></Link>
            </div>
        );
    }
    
    if (errorStatus === 404) return <NotFoundPage />;
    if (errorStatus) return <div className="text-center p-16 text-(--platform-danger)">Сталася помилка при завантаженні профілю.</div>;
    const displayUsername = profileData?.username || 'Користувач';
    const displayAvatarUrl = isOwner ? authUser?.avatar_url : profileData?.avatar_url;
    const displayDate = profileData?.createdAt || profileData?.created_at || (isOwner ? authUser?.created_at : null);
    const displaySiteCount = profileData?.siteCount !== undefined ? profileData.siteCount : (sitesLoading ? '-' : userSites.length);
    const displayTotalViews = profileData?.totalViews !== undefined ? profileData.totalViews : (sitesLoading ? '-' : userSites.reduce((sum, site) => sum + (site.view_count || 0), 0));
    const userAccentColor = profileData?.accent_color || 'var(--platform-accent)';
    return (
        <div className="w-full max-w-7xl mx-auto px-4 sm:px-6 py-6 sm:py-8 min-h-[80vh]">
            <Helmet>
                <title>{`${displayUsername} | Профіль Kendr`}</title>
            </Helmet>
            <div className="bg-(--platform-card-bg) rounded-2xl sm:rounded-3xl border border-(--platform-border-color) overflow-hidden mb-6 sm:mb-8 shadow-sm">
                <div 
                    className="h-32 sm:h-48 md:h-60 w-full relative" 
                    style={{ background: `linear-gradient(to bottom, ${userAccentColor}, var(--platform-card-bg))` }}
                ></div>
                <div className="px-4 sm:px-6 md:px-8 pb-6 sm:pb-8 flex flex-col sm:flex-row items-center sm:items-end gap-4 sm:gap-6 md:gap-8 relative z-10 -mt-16 sm:-mt-20">
                    <div className="rounded-full border-4 sm:border-6 border-(--platform-card-bg) bg-(--platform-bg) shadow-lg shrink-0 flex items-center justify-center">
                        <Avatar 
                            url={displayAvatarUrl} 
                            name={displayUsername} 
                            size={120} 
                            fontSize="48px" 
                            className="w-24 h-24 sm:w-32 sm:h-32 md:w-40 md:h-40"
                            style={{ filter: profileData.status === 'suspended' ? 'grayscale(100%)' : 'none' }}
                        />
                    </div>
                    <div className="flex-1 w-full flex flex-col sm:flex-row justify-between items-center sm:items-end gap-4 sm:gap-0 text-center sm:text-left pt-2 sm:pt-0">
                        <div>
                            <div className="flex items-center justify-center sm:justify-start gap-2 sm:gap-3 mb-1 sm:mb-2">
                                <h1 className="text-2xl sm:text-3xl md:text-4xl font-extrabold text-(--platform-text-primary) m-0 leading-tight">
                                    {displayUsername}
                                </h1>
                                {authUser?.role === 'admin' && (
                                    <Button 
                                        variant="ghost" 
                                        onClick={() => setIsAdminPanelOpen(true)}
                                        className="p-1.5 text-(--platform-accent) hover:bg-(--platform-hover-bg) rounded-lg"
                                        title="Керування профілем (Адмін)"
                                    >
                                        <Shield size={20} className="sm:w-5 sm:h-5 w-4 h-4" />
                                    </Button>
                                )}
                                {!profileData.is_profile_public && isOwner && (
                                    <div title="Приватний профіль (бачите тільки ви)" className="pb-1">
                                        <EyeOff size={20} className="text-(--platform-text-secondary) sm:w-6 sm:h-6 w-5 h-5" />
                                    </div>
                                )}
                            </div>
                            <p className="text-(--platform-text-secondary) m-0 flex items-center justify-center sm:justify-start gap-2 text-xs sm:text-sm md:text-base">
                                <Calendar size={16} className="text-(--platform-accent) shrink-0"/> 
                                <span>На платформі з {getFormattedDate(displayDate)}</span>
                            </p>
                        </div>
                        {isOwner && (
                            <Link to="/settings" className="no-underline shrink-0 w-full sm:w-auto mt-2 sm:mt-0">
                                <Button variant="secondary" icon={<Settings size={18}/>} className="w-full sm:w-auto">Налаштувати</Button>
                            </Link>
                        )}
                    </div>
                </div>
            </div>
            {profileData.status === 'suspended' && (
                <div className="bg-[color-mix(in_srgb,var(--platform-danger),transparent_95%)] border border-(--platform-danger) rounded-2xl p-4 sm:p-6 flex flex-col sm:flex-row items-center sm:items-start gap-3 sm:gap-4 mb-6 shadow-sm text-center sm:text-left">
                     <AlertTriangle size={24} className="text-(--platform-danger) shrink-0" />
                     <div className="font-semibold text-(--platform-danger) text-sm sm:text-base">Цей акаунт заблоковано за порушення правил платформи.</div>
                </div>
            )}
            {profileData.warnings && profileData.warnings.length > 0 && (
                <div className="bg-[color-mix(in_srgb,var(--platform-danger),transparent_95%)] border border-(--platform-danger) rounded-2xl overflow-hidden mb-6 sm:mb-8 shadow-sm">
                    <div className="p-4 sm:p-6 border-b border-[color-mix(in_srgb,var(--platform-danger),transparent_80%)] flex items-center gap-3">
                        <ShieldAlert size={24} className="text-(--platform-danger) shrink-0" />
                        <h3 className="text-lg sm:text-xl font-bold text-(--platform-danger) m-0">
                            Активні страйки ({profileData.warnings.length}/3)
                        </h3>
                    </div>
                    <div className="p-4 sm:p-6">
                        <div className="flex gap-2 mb-6">
                             {[1, 2, 3].map(i => (
                                <div key={i} className={`h-2 flex-1 rounded-full ${i <= profileData.warnings.length ? 'bg-(--platform-danger)' : 'bg-(--platform-border-color)'}`}></div>
                             ))}
                        </div>
                        <div className="flex flex-col gap-3 sm:gap-4">
                            {profileData.warnings.map((warning, index) => (
                                <div key={warning.id || index} className="p-3 sm:p-4 rounded-xl bg-(--platform-bg) border border-(--platform-border-color) flex flex-col sm:flex-row items-start gap-3">
                                    <AlertTriangle size={20} className="text-(--platform-warning) shrink-0 mt-0.5 hidden sm:block" />
                                    <div>
                                        <div className="font-semibold text-(--platform-text-primary) mb-1 flex items-center gap-2">
                                            <AlertTriangle size={16} className="text-(--platform-warning) sm:hidden" />
                                            Попередження #{index + 1}
                                        </div>
                                        {warning.reason_note && (
                                            <div className="text-sm sm:text-base text-(--platform-text-primary) mb-1">
                                                {warning.reason_note}
                                            </div>
                                        )}
                                        <div className="text-xs sm:text-sm text-(--platform-text-secondary)">
                                            Отримано: {getFormattedDate(warning.created_at)}
                                        </div>
                                    </div>
                                </div>
                            ))}
                        </div>
                        {isOwner && (
                            <div className="mt-6 text-xs sm:text-sm text-(--platform-text-secondary) italic text-center sm:text-left">
                                При досягненні 3-х страйків ваш акаунт буде заблоковано або видалено.
                            </div>
                        )}
                    </div>
                </div>
            )}
            {profileData.bio && (
                <div className="bg-(--platform-card-bg) rounded-2xl sm:rounded-3xl border border-(--platform-border-color) overflow-hidden mb-6 sm:mb-8 shadow-sm">
                    <div className="p-4 sm:p-6 border-b border-(--platform-border-color) flex items-center gap-3">
                        <UserIcon size={24} className="text-(--platform-accent) shrink-0" />
                        <h3 className="text-lg sm:text-xl font-bold text-(--platform-text-primary) m-0">Про мене</h3>
                    </div>
                    <div className="p-4 sm:p-6">
                        <p className="text-sm sm:text-base text-(--platform-text-secondary) leading-relaxed whitespace-pre-wrap m-0">{profileData.bio}</p>
                    </div>
                </div>
            )}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6 sm:gap-8 mb-6 sm:mb-8">
                <div className="bg-(--platform-card-bg) rounded-2xl sm:rounded-3xl border border-(--platform-border-color) overflow-hidden shadow-sm h-full flex flex-col">
                    <div className="p-4 sm:p-6 border-b border-(--platform-border-color) flex items-center gap-3 shrink-0">
                        <Grid size={24} className="text-(--platform-accent) shrink-0" />
                        <h3 className="text-lg sm:text-xl font-bold text-(--platform-text-primary) m-0">Статистика</h3>
                    </div>
                    <div className="p-4 sm:p-6 flex-1 flex flex-col justify-center">
                        <div className="flex justify-between items-center py-3 sm:py-4 border-b border-(--platform-border-color) text-sm sm:text-base text-(--platform-text-secondary)">
                            <span>Опубліковано сайтів</span>
                            <span className="font-bold text-lg sm:text-xl text-(--platform-text-primary)">
                                {displaySiteCount}
                            </span>
                        </div>
                        <div className="flex justify-between items-center py-3 sm:py-4 text-sm sm:text-base text-(--platform-text-secondary)">
                            <span>Всього переглядів</span>
                            <span className="font-bold text-lg sm:text-xl text-(--platform-accent)">
                                {displayTotalViews}
                            </span>
                        </div>
                    </div>
                </div>
                {profileData.socials && Object.values(profileData.socials).some(v => v) ? (
                    <div className="bg-(--platform-card-bg) rounded-2xl sm:rounded-3xl border border-(--platform-border-color) overflow-hidden shadow-sm h-full flex flex-col">
                        <div className="p-4 sm:p-6 border-b border-(--platform-border-color) flex items-center gap-3 shrink-0">
                            <Globe size={24} className="text-(--platform-accent) shrink-0" />
                            <h3 className="text-lg sm:text-xl font-bold text-(--platform-text-primary) m-0">Контакти</h3>
                        </div>
                        <div className="p-4 sm:p-6 flex-1 flex flex-col gap-3 justify-center">
                            {profileData.socials.telegram && (
                                <a href={`https://t.me/${profileData.socials.telegram.replace('@', '')}`} target="_blank" rel="noreferrer" className="flex items-center gap-3 p-3 sm:p-4 rounded-xl bg-(--platform-bg) hover:bg-(--platform-hover-bg) text-(--platform-text-primary) no-underline text-sm sm:text-base font-medium transition-colors border border-transparent">
                                    <Send size={20} style={{ color: '#0088cc' }} className="shrink-0"/> 
                                    <span className="truncate">Telegram</span>
                                    <ExternalLink size={16} className="ml-auto opacity-50 shrink-0"/>
                                </a>
                            )}
                            {profileData.socials.instagram && (
                                <a href={`https://instagram.com/${profileData.socials.instagram.replace('@', '')}`} target="_blank" rel="noreferrer" className="flex items-center gap-3 p-3 sm:p-4 rounded-xl bg-(--platform-bg) hover:bg-(--platform-hover-bg) text-(--platform-text-primary) no-underline text-sm sm:text-base font-medium transition-colors border border-transparent">
                                    <Instagram size={20} style={{ color: '#E1306C' }} className="shrink-0"/> 
                                    <span className="truncate">Instagram</span>
                                    <ExternalLink size={16} className="ml-auto opacity-50 shrink-0"/>
                                </a>
                            )}
                            {profileData.socials.website && (
                                <a href={profileData.socials.website} target="_blank" rel="noreferrer" className="flex items-center gap-3 p-3 sm:p-4 rounded-xl bg-(--platform-bg) hover:bg-(--platform-hover-bg) text-(--platform-text-primary) no-underline text-sm sm:text-base font-medium transition-colors border border-transparent">
                                    <Globe size={20} className="text-(--platform-text-secondary) shrink-0"/> 
                                    <span className="truncate">Веб-сайт</span>
                                    <ExternalLink size={16} className="ml-auto opacity-50 shrink-0"/>
                                </a>
                            )}
                        </div>
                    </div>
                ) : (
                    <div className="bg-(--platform-card-bg) rounded-2xl sm:rounded-3xl border border-(--platform-border-color) overflow-hidden shadow-sm h-full flex items-center justify-center p-8">
                         <div className="text-center text-(--platform-text-secondary) text-sm sm:text-base">
                            <p>Контакти відсутні</p>
                        </div>
                    </div>
                )}
            </div>
            <div className="bg-(--platform-card-bg) rounded-2xl sm:rounded-3xl border border-(--platform-border-color) overflow-hidden shadow-sm">
                <div className="p-4 sm:p-6 border-b border-(--platform-border-color) flex items-center gap-3">
                    <Layout size={24} className="text-(--platform-accent) shrink-0" />
                    <h3 className="text-lg sm:text-xl font-bold text-(--platform-text-primary) m-0">Публічні сайти</h3>
                </div>
                <SiteFilters 
                    searchTerm={searchTerm} 
                    onSearchChange={setSearchTerm} 
                    sortOption={sortOption} 
                    onSortChange={setSortOption}
                    sortOptions={SORT_OPTIONS}
                    tags={[]} 
                    showStarFilter={false}
                />
                
                {sitesLoading ? (
                    <div className="py-8">
                        <LoadingState layout="component" iconSize={32} />
                    </div>
                ) : (
                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4 sm:gap-5 p-4 sm:p-6">
                        {userSites.length > 0 ? (
                            userSites.map(site => (
                                <SiteGridCard 
                                    key={site.id} 
                                    site={site} 
                                    variant="public"
                                    formatDate={(d) => getFormattedDate(d)}
                                />
                            ))
                        ) : (
                            <div className="col-span-full text-center py-12 sm:py-16 px-4 text-(--platform-text-secondary)">
                                 <div className="mb-4 opacity-50 flex justify-center">
                                    <Globe size={40} className="sm:w-12 sm:h-12" />
                                 </div>
                                 <p className="text-sm sm:text-base lg:text-lg m-0">
                                     {searchTerm ? 'Нічого не знайдено за вашим запитом' : 'У користувача поки немає публічних сайтів'}
                                 </p>
                            </div>
                        )}
                    </div>
                )}
            </div>

            {isAdminPanelOpen && profileData && (
                <UserDetailsPanel 
                    user={profileData} 
                    onClose={() => setIsAdminPanelOpen(false)} 
                    onDelete={handleDeleteUser} 
                    onSuspend={handleSuspendUser} 
                    onRestore={handleRestoreUser} 
                />
            )}
        </div>
    );
};

export default ProfilePage;

// frontend/src/modules/profile/pages/SettingsPage.jsx
import React, { useState, useContext, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { AuthContext } from '../../../app/providers/AuthContext';
import ProfileGeneralTab from '../tabs/ProfileGeneralTab';
import ProfileSecurityTab from '../tabs/ProfileSecurityTab';
import ProfileAppearanceTab from '../tabs/ProfileAppearanceTab';
import ProfilePublicTab from '../tabs/ProfilePublicTab';
import { User, Shield, Palette, Globe, ExternalLink } from 'lucide-react';

const SettingsPage = () => {
    const { user } = useContext(AuthContext);
    const isStaff = user?.role === 'admin' || user?.role === 'moderator';
    const [activeTab, setActiveTab] = useState(() => {
        const savedTab = localStorage.getItem('settings_active_tab');
        const allowedTabs = isStaff 
            ? ['general', 'security', 'appearance'] 
            : ['general', 'security', 'public', 'appearance'];
            
        return allowedTabs.includes(savedTab) ? savedTab : 'general';
    });

    useEffect(() => {
        localStorage.setItem('settings_active_tab', activeTab);
    }, [activeTab]);

    const tabs = [
        { id: 'general', label: 'Загальні', icon: <User /> },
        { id: 'security', label: 'Безпека', icon: <Shield /> },
        ...(isStaff ? [] : [{ id: 'public', label: 'Публічність', icon: <Globe /> }]),
        { id: 'appearance', label: 'Вигляд', icon: <Palette /> },
    ];

    return (
        <div className="-m-4 sm:-m-8 w-[calc(100%+2rem)] sm:w-[calc(100%+4rem)] min-h-[calc(100vh-64px+4rem)] flex flex-col bg-(--platform-bg)"> 
            <header className="sticky top-0 z-50 bg-(--platform-card-bg) border-b border-(--platform-border-color) h-(--header-height,60px) px-4 sm:px-6 flex items-center justify-between gap-4 transition-colors duration-300">
                <div className="flex-1 min-w-0"></div>
                <div className="flex-initial flex justify-center min-w-0">
                    <nav className="flex bg-(--platform-bg) p-1 rounded-lg gap-1 border border-(--platform-border-color) overflow-hidden shadow-sm">
                        {tabs.map(tab => {
                            const isActive = activeTab === tab.id;
                            return (
                                <button
                                    key={tab.id}
                                    onClick={() => setActiveTab(tab.id)}
                                    className={`
                                        flex items-center justify-center gap-2 px-3 sm:px-4 py-1.5 sm:py-2 rounded-md text-xs sm:text-sm font-medium border-none cursor-pointer transition-all duration-200 min-h-8 sm:min-h-9 whitespace-nowrap outline-none
                                        ${isActive 
                                            ? 'bg-(--platform-card-bg) text-(--platform-accent) shadow-[0_1px_3px_rgba(0,0,0,0.1)] font-semibold' 
                                            : 'bg-transparent text-(--platform-text-secondary) hover:bg-(--platform-hover-bg) hover:text-(--platform-text-primary)'
                                        }
                                    `}
                                    title={tab.label}
                                >
                                    <span className="flex items-center justify-center w-4 h-4 sm:w-4.5 sm:h-4.5 shrink-0">
                                        {React.cloneElement(tab.icon, { 
                                            className: 'w-full h-full fill-none stroke-current stroke-2' 
                                        })}
                                    </span>
                                    <span className="hidden xl:inline-block mt-px">{tab.label}</span>
                                </button>
                            );
                        })}
                    </nav>
                </div>
                <div className="flex-1 flex items-center justify-end min-w-0 gap-2">
                    {user && !isStaff && (
                        <Link 
                            to={`/profile/${user.slug}`} 
                            target="_blank"
                            title="Мій профіль"
                            className="flex items-center justify-center w-8 h-8 sm:w-9 sm:h-9 rounded-lg border border-(--platform-border-color) bg-(--platform-bg) text-(--platform-text-secondary) hover:bg-(--platform-card-bg) hover:text-(--platform-accent) hover:border-(--platform-accent) transition-all no-underline shrink-0"
                        >
                            <ExternalLink className="w-4 h-4 sm:w-4.5 sm:h-4.5 shrink-0" />
                        </Link>
                    )}
                </div>
            </header>
            <div className="flex-1 pb-8">
                <div className="max-w-4xl mx-auto px-4 py-6 md:px-8 md:py-8">
                    <div className="animate-fade-in-up">
                        {activeTab === 'general' && <ProfileGeneralTab />}
                        {activeTab === 'security' && <ProfileSecurityTab />}
                        {activeTab === 'appearance' && <ProfileAppearanceTab />}
                        {!isStaff && activeTab === 'public' && <ProfilePublicTab />}
                    </div>
                </div>
            </div>
            <style>{`
                @keyframes fadeInUp {
                    from { opacity: 0; transform: translateY(10px); }
                    to { opacity: 1; transform: translateY(0); }
                }
                .animate-fade-in-up {
                    animation: fadeInUp 0.3s ease-in-out;
                }
                @media (max-width: 1100px) {
                    .xl\\:inline-block {
                        display: none !important;
                    }
                }
                @media (max-width: 768px) {
                    .sticky {
                        height: 56px;
                        padding: 0 12px;
                        gap: 8px;
                    }
                }
                @media (max-width: 480px) {
                    .sticky {
                        padding: 0 8px;
                        gap: 4px;
                    }
                }
            `}</style>
        </div>
    );
};

