// frontend/src/modules/profile/tabs/ProfileSecurityTab.jsx
import React, { useState, useContext, useEffect } from 'react';
import { toast } from 'react-toastify';
import { AuthContext } from '../../../app/providers/AuthContext';
import { useConfirm } from '../../../shared/hooks/useConfirm';
import apiClient from '../../../shared/api/api';
import { Input, Button } from '../../../shared/ui/elements';
import PasswordStrengthMeter from '../../../shared/ui/complex/PasswordStrengthMeter';
import { analyzePassword } from '../../../shared/utils/validationUtils';
import { useCooldown } from '../../../shared/hooks/useCooldown';
import { Lock, Trash2, AlertCircle, Timer } from 'lucide-react';

const ProfileSecurityTab = () => {
    const { user, updateUser, logout } = useContext(AuthContext);
    const { confirm } = useConfirm(); 
    const [isLoading, setIsLoading] = useState(false);
    const hasPassword = user.has_password === true;
    const isAdmin = user?.role === 'admin';
    const [passwords, setPasswords] = useState({
        currentPassword: '',
        newPassword: '',
        confirmPassword: ''
    });
    const [securityCooldown, startSecurityCooldown] = useCooldown('kendr_security_update_cooldown');
    useEffect(() => {
        setPasswords({ currentPassword: '', newPassword: '', confirmPassword: '' });
    }, [hasPassword]);
    const handleChange = (e) => {
        const { name, value } = e.target;
        setPasswords(prev => ({ ...prev, [name]: value }));
    };
    const handleSubmit = async (e) => {
        e.preventDefault();
        if (securityCooldown > 0) {
            toast.warning(`Зачекайте ${securityCooldown}с перед наступною зміною.`);
            return;
        }
        if (hasPassword && !passwords.currentPassword) {
            toast.error("Введіть поточний пароль для підтвердження.");
            return;
        }
        if (hasPassword && passwords.currentPassword === passwords.newPassword) {
            toast.warning("Новий пароль не може бути таким самим, як поточний.");
            return;
        }
        const validation = analyzePassword(passwords.newPassword);
        if (validation.isSimple) {
            toast.warning("Пароль містить занадто просту послідовність (наприклад, 123456 або qwerty). Придумайте складніший пароль.");
            return;
        }
        if (!validation.isValid) {
            toast.warning("Пароль має містити мінімум 8 символів, велику літеру, малу літеру та цифру.");
            return;
        }
        if (passwords.newPassword !== passwords.confirmPassword) {
            toast.error("Нові паролі не співпадають");
            return;
        }
        setIsLoading(true);
        try {
            const payload = { newPassword: passwords.newPassword };
            if (hasPassword) {
                payload.currentPassword = passwords.currentPassword;
            }
            const response = await apiClient.put('/users/profile/password', payload);
            toast.success(hasPassword ? "Пароль успішно змінено!" : "Пароль успішно встановлено!");
            const updatedUser = {
                ...user,                  
                ...(response.data.user || {}), 
                has_password: true        
            };
            updateUser(updatedUser); 
            setPasswords({ currentPassword: '', newPassword: '', confirmPassword: '' });
            startSecurityCooldown(30);
        } catch (error) {
            if (error.response?.status === 429) {
                toast.error("Забагато спроб зміни пароля. Спробуйте пізніше через годину.");
            } else {
                toast.error(error.response?.data?.message || "Помилка збереження пароля.");
            }
        } finally {
            setIsLoading(false);
        }
    };
    
    const handleDeleteAccount = () => {
        confirm({
            title: 'Видалити акаунт?',
            message: 'Ця дія незворотна. Всі ваші сайти будуть видалені. Напишіть "DELETE" для підтвердження.',
            requireInput: true,
            confirmText: 'Видалити акаунт',
            danger: true,
            onConfirm: async (inputValue) => {
                if (inputValue !== 'DELETE') return toast.error('Невірне підтвердження.');
                try {
                    await apiClient.delete('/users/me', { data: { confirmation: 'DELETE' } });
                    toast.success('Акаунт видалено, у вас є 14 днів на відновлення.');
                    logout();
                } catch (err) {
                    console.error(err);
                    toast.error('Помилка при видаленні акаунту');
                }
            }
        });
    };
    
    return (
        <div className="w-full max-w-200 mx-auto">
            <div className="bg-(--platform-card-bg) rounded-2xl border border-(--platform-border-color) p-5 sm:p-8 mb-5 sm:mb-6 shadow-sm">
                <div className="text-center mb-6 sm:mb-8">
                    <h3 className="text-lg sm:text-xl font-semibold text-(--platform-text-primary) flex items-center justify-center gap-2.5 mb-2 m-0">
                        <Lock className="w-5 h-5 sm:w-6 sm:h-6 text-(--platform-accent)" />
                        {hasPassword ? 'Зміна паролю' : 'Встановлення паролю'}
                    </h3>
                    <p className="text-sm text-(--platform-text-secondary) m-0 leading-relaxed">
                        {hasPassword 
                            ? 'Введіть поточний пароль, щоб встановити новий.'
                            : 'У вас не встановлено пароль (вхід через Google). Створіть його для входу через Email.'
                        }
                    </p>
                </div>
                <form onSubmit={handleSubmit}>
                    <div className="flex flex-col gap-4 sm:gap-5 w-full max-w-100 mx-auto">
                        {hasPassword && (
                            <Input 
                                name="currentPassword" 
                                label="Поточний пароль" 
                                type="password" 
                                placeholder="••••••••" 
                                value={passwords.currentPassword} 
                                onChange={handleChange} 
                                required 
                            />
                        )}
                        <div>
                            <Input 
                                name="newPassword" 
                                label={hasPassword ? "Новий пароль" : "Придумайте пароль"}
                                type="password" 
                                placeholder="••••••••" 
                                value={passwords.newPassword} 
                                onChange={handleChange} 
                                required 
                            />
                            <div className="mt-1 sm:mt-1.5">
                                <PasswordStrengthMeter password={passwords.newPassword} />
                            </div>
                        </div>
                        <Input 
                            name="confirmPassword" 
                            label="Підтвердження" 
                            type="password" 
                            placeholder="••••••••" 
                            value={passwords.confirmPassword} 
                            onChange={handleChange} 
                            required
                            error={passwords.confirmPassword && passwords.newPassword !== passwords.confirmPassword ? "Паролі не співпадають" : ""}
                        />
                        <div className="mt-2">
                            <Button 
                                type="submit" 
                                disabled={isLoading || securityCooldown > 0} 
                                className="w-full min-h-11 flex justify-center items-center gap-2"
                            >
                                {isLoading 
                                    ? 'Збереження...' 
                                    : (securityCooldown > 0 
                                        ? <><Timer size={18} /> Зачекайте {securityCooldown}с</>
                                        : (hasPassword ? 'Оновити пароль' : 'Встановити пароль')
                                    )
                                }
                            </Button>
                        </div>
                    </div>
                </form>
            </div>
            {!isAdmin && (
                <div className="rounded-2xl border border-(--platform-danger) p-5 sm:p-8 shadow-sm bg-[color-mix(in_srgb,var(--platform-danger),transparent_95%)]">
                    <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4 sm:gap-6">
                        <div className="flex-1">
                            <h3 className="text-lg sm:text-xl font-semibold text-(--platform-danger) flex items-center gap-2.5 mb-1.5 m-0">
                                <AlertCircle className="w-5 h-5 sm:w-5.5 sm:h-5.5" />
                                ВИДАЛЕННЯ АКАУНТУ
                            </h3>
                            <p className="text-sm sm:text-[0.9rem] text-(--platform-danger) opacity-80 m-0 leading-relaxed">
                                Видалення акаунту призведе до <strong>незворотної</strong> втрати всіх ваших сайтів та даних.
                            </p>
                        </div>
                        <Button 
                            variant="danger"
                            onClick={handleDeleteAccount}
                            icon={<Trash2 size={18} />}
                            className="w-full sm:w-auto min-h-11 flex items-center justify-center shrink-0"
                        >
                            Видалити акаунт
                        </Button>
                    </div>
                </div>
            )}
        </div>
    );
};

export default ProfileSecurityTab;

// frontend/src/modules/renderer/components/AnimationWrapper.jsx
import React from 'react';
import { motion } from 'framer-motion';

const variants = {
    none: { hidden: {}, visible: {} },
    fadeIn: { 
        hidden: { opacity: 0 }, 
        visible: { opacity: 1 } 
    },
    fadeUp: { 
        hidden: { opacity: 0, y: 50 }, 
        visible: { opacity: 1, y: 0 } 
    },
    fadeDown: { 
        hidden: { opacity: 0, y: -50 }, 
        visible: { opacity: 1, y: 0 } 
    },
    fadeLeft: { 
        hidden: { opacity: 0, x: -50 }, 
        visible: { opacity: 1, x: 0 } 
    },
    fadeRight: { 
        hidden: { opacity: 0, x: 50 }, 
        visible: { opacity: 1, x: 0 } 
    },
    zoomIn: { 
        hidden: { opacity: 0, scale: 0.8 }, 
        visible: { opacity: 1, scale: 1 } 
    }
};

const AnimationWrapper = ({ children, animationConfig }) => {
    const type = animationConfig?.type || 'none';
    const duration = parseFloat(animationConfig?.duration || 0.6);
    const delay = parseFloat(animationConfig?.delay || 0);
    const repeat = animationConfig?.repeat || false;

    if (type === 'none') {
        return <>{children}</>;
    }

    return (
        <motion.div
            initial="hidden"
            whileInView="visible"
            viewport={{ once: !repeat, amount: 0.2 }} 
            transition={{ duration, delay, ease: "easeOut" }}
            variants={variants[type]}
            style={{ width: '100%' }}
        >
            {children}
        </motion.div>
    );
};

export default AnimationWrapper;

// frontend/src/modules/renderer/components/CookieBanner.jsx
import React, { useState, useEffect } from 'react';

const CookieBanner = ({ 
    enabled, 
    text, 
    siteId, 
    size = 'medium', 
    position = 'bottom-center', 
    blur = false 
}) => {
    const [isVisible, setIsVisible] = useState(false);
    useEffect(() => {
        if (!enabled || !siteId) return;
        const storageKey = `cookie_consent_site_${siteId}`;
        const consentStatus = localStorage.getItem(storageKey);
        if (consentStatus === null) {
            const timer = setTimeout(() => setIsVisible(true), 1000);
            return () => clearTimeout(timer);
        }
    }, [enabled, siteId]);

    const handleAction = (status) => {
        const storageKey = `cookie_consent_site_${siteId}`;
        localStorage.setItem(storageKey, status);
        setIsVisible(false);
    };

    if (!isVisible) return null;
    const getSizeStyles = () => {
        switch (size) {
            case 'small': return { maxWidth: '400px', padding: '16px', fontSize: '13px' };
            case 'large': return { maxWidth: '800px', padding: '24px', fontSize: '16px' };
            case 'medium':
            default: return { maxWidth: '600px', padding: '20px', fontSize: '14px' };
        }
    };

    const getPositionStyles = () => {
        let styles = { position: 'fixed', zIndex: 10001 };
        if (position.includes('top')) styles.top = '20px';
        if (position.includes('bottom')) styles.bottom = '20px';
        if (position.includes('middle')) {
            styles.top = '50%';
            styles.transform = 'translateY(-50%)';
        }
        if (position.includes('left')) styles.left = '20px';
        if (position.includes('right')) styles.right = '20px';
        if (position.includes('center')) {
            styles.left = '50%';
            if (styles.transform) {
                styles.transform = 'translate(-50%, -50%)';
            } else {
                styles.transform = 'translateX(-50%)';
            }
        }
        return styles;
    };

    const sizeStyles = getSizeStyles();
    const bannerContent = (
        <div style={{
            ...getPositionStyles(),
            width: '90%',
            maxWidth: sizeStyles.maxWidth,
            backgroundColor: 'var(--site-bg)', 
            color: 'var(--site-text-primary)',
            padding: sizeStyles.padding,
            boxShadow: '0 10px 40px rgba(0,0,0,0.2)',
            display: 'flex',
            flexDirection: 'column',
            gap: '15px',
            border: '1px solid var(--site-border-color)',
            borderRadius: '12px',
            animation: 'cookieFadeIn 0.5s ease-out'
        }}>
            <p style={{ margin: 0, fontSize: sizeStyles.fontSize, lineHeight: '1.5' }}>
                {text || "Цей сайт використовує файли cookie для покращення користувацького досвіду."}
            </p>
            <div style={{ display: 'flex', gap: '10px', justifyContent: 'flex-end', flexWrap: 'wrap' }}>
                <button 
                    onClick={() => handleAction('denied')}
                    style={{
                        backgroundColor: 'transparent',
                        color: 'var(--site-text-secondary)',
                        border: '1px solid var(--site-border-color)',
                        padding: '8px 20px',
                        borderRadius: '6px',
                        cursor: 'pointer',
                        fontSize: '14px',
                        fontWeight: '600',
                        transition: 'all 0.2s ease',
                        flex: '1 1 auto',
                    }}
                    onMouseEnter={(e) => {
                        e.target.style.color = 'var(--site-text-primary)';
                        e.target.style.borderColor = 'var(--site-text-primary)';
                        e.target.style.backgroundColor = 'rgba(0,0,0,0.05)';
                    }}
                    onMouseLeave={(e) => {
                        e.target.style.color = 'var(--site-text-secondary)';
                        e.target.style.borderColor = 'var(--site-border-color)';
                        e.target.style.backgroundColor = 'transparent';
                    }}
                >
                    Відхилити
                </button>
                <button 
                    onClick={() => handleAction('granted')}
                    style={{
                        backgroundColor: 'var(--site-accent)',
                        color: '#ffffff',
                        border: 'none',
                        padding: '8px 20px',
                        borderRadius: '6px',
                        cursor: 'pointer',
                        fontWeight: 'bold',
                        fontSize: '14px',
                        transition: 'all 0.2s ease',
                        flex: '1 1 auto',
                        boxShadow: '0 2px 4px rgba(0,0,0,0.2)'
                    }}
                    onMouseEnter={(e) => {
                        e.target.style.filter = 'brightness(1.1)';
                        e.target.style.transform = 'translateY(-1px)';
                    }}
                    onMouseLeave={(e) => {
                        e.target.style.filter = 'none';
                        e.target.style.transform = 'translateY(0)';
                    }}
                >
                    Зрозуміло
                </button>
            </div>
            <style>{`
                @keyframes cookieFadeIn {
                    from { opacity: 0; }
                    to { opacity: 1; }
                }
            `}</style>
        </div>
    );
    if (blur) {
        return (
            <div style={{
                position: 'fixed',
                top: 0, left: 0, right: 0, bottom: 0,
                backgroundColor: 'rgba(0,0,0,0.15)',
                backdropFilter: 'blur(6px)',
                WebkitBackdropFilter: 'blur(6px)',
                zIndex: 10000,
                animation: 'cookieFadeIn 0.5s ease-out'
            }}>
                {bannerContent}
            </div>
        );
    }

    return bannerContent;
};

export default CookieBanner;

// frontend/src/modules/renderer/components/FontLoader.jsx
import React from 'react';
import { Helmet } from 'react-helmet-async';
import { BASE_URL } from '../../../shared/config';

const FontLoader = ({ fontHeading, fontBody }) => {
    const getFontCss = (fontFamily, type) => {
        if (!fontFamily || fontFamily === 'global') return null;
        const isCustomFont = fontFamily.includes('uploads') || fontFamily.includes('http');
        if (isCustomFont) {
            let fontUrl = fontFamily;
            if (!fontFamily.startsWith('http')) {
                const path = fontFamily.startsWith('/') ? fontFamily : `/${fontFamily}`;
                fontUrl = `${BASE_URL}${path}`;
            }
            
            const fontName = `CustomFont-${type}`;
            let format = 'truetype';
            if (fontUrl.endsWith('.woff2')) format = 'woff2';
            else if (fontUrl.endsWith('.woff')) format = 'woff';
            else if (fontUrl.endsWith('.otf')) format = 'opentype';
            return {
                isCustom: true,
                name: fontName,
                link: null,
                style: `
                    @font-face {
                        font-family: '${fontName}';
                        src: url('${fontUrl}') format('${format}');
                        font-weight: normal;
                        font-style: normal;
                        font-display: swap;
                    }
                `
            };
        } else {
            const cleanName = fontFamily.split(',')[0].replace(/['"]/g, '');
            return {
                isCustom: false,
                name: cleanName,
                style: null,
                link: `https://fonts.googleapis.com/css2?family=${cleanName.replace(/ /g, '+')}:wght@400;500;600;700&display=swap`
            };
        }
    };

    const headingFont = getFontCss(fontHeading, 'heading');
    const bodyFont = getFontCss(fontBody, 'body');
    return (
        <Helmet>
            {headingFont && !headingFont.isCustom && (
                <link rel="stylesheet" href={headingFont.link} />
            )}
            {bodyFont && !bodyFont.isCustom && (
                <link rel="stylesheet" href={bodyFont.link} />
            )}

            {headingFont && headingFont.isCustom && (
                <style type="text/css">{headingFont.style}</style>
            )}
            {bodyFont && bodyFont.isCustom && (
                <style type="text/css">{bodyFont.style}</style>
            )}
            <style type="text/css">{`
                :root {
                    --site-font-heading: ${headingFont ? `'${headingFont.name}', sans-serif` : 'inherit'};
                    --site-font-body: ${bodyFont ? `'${bodyFont.name}', sans-serif` : 'inherit'};
                }
            `}</style>
        </Helmet>
    );
};

