            const newX = touch.clientX - dragStart.x;
            const newY = touch.clientY - dragStart.y;
            const maxDrag = 200 * imageScale;
            setImagePosition({
                x: Math.max(Math.min(newX, maxDrag), -maxDrag),
                y: Math.max(Math.min(newY, maxDrag), -maxDrag)
            });
