// frontend/src/shared/hooks/useCooldown.js
import { useState, useEffect, useCallback } from 'react';
export const useCooldown = (storageKey) => {
    const [cooldown, setCooldown] = useState(() => {
        const savedTime = localStorage.getItem(storageKey);
        if (savedTime) {
            const remaining = Math.ceil((parseInt(savedTime) - Date.now()) / 1000);
            return remaining > 0 ? remaining : 0;
        }
        return 0;
    });
    useEffect(() => {
        let timer;
        if (cooldown > 0) {
            timer = setTimeout(() => setCooldown(prev => prev - 1), 1000);
        } else if (cooldown === 0) {
            const savedTime = localStorage.getItem(storageKey);
            if (savedTime && Date.now() > parseInt(savedTime)) {
                localStorage.removeItem(storageKey);
            }
        }
        return () => clearTimeout(timer);
    }, [cooldown, storageKey]);
    const startCooldown = useCallback((seconds) => {
        setCooldown(seconds);
        localStorage.setItem(storageKey, (Date.now() + seconds * 1000).toString());
    }, [storageKey]);

    return [cooldown, startCooldown];
};

// frontend/src/shared/hooks/useDataList.js
import { useState, useEffect, useMemo, useCallback } from 'react';
import { toast } from 'react-toastify';
import apiClient from '../api/api';

export const useDataList = (endpoint, searchFields = []) => {
    const [data, setData] = useState([]);
    const [loading, setLoading] = useState(true);
    const [searchQuery, setSearchQuery] = useState('');

    const fetchData = useCallback(async () => {
        setLoading(true);
        try {
            const response = await apiClient.get(endpoint);
            setData(response.data);
        } catch (error) {
            console.error(error);
            toast.error('Помилка завантаження даних');
        } finally {
            setLoading(false);
        }
    }, [endpoint]);

    useEffect(() => {
        fetchData();
    }, [fetchData]);

    const filteredData = useMemo(() => {
        if (!searchQuery) return data;
        const lowerQ = searchQuery.toLowerCase();
        
        return data.filter(item => {
            return searchFields.some(field => {
                const value = item[field];
                return value && String(value).toLowerCase().includes(lowerQ);
            });
        });
    }, [data, searchQuery, searchFields]);

    return {
        data,
        filteredData,
        loading,
        searchQuery,
        setSearchQuery,
        refresh: fetchData
    };
};

// frontend/src/shared/hooks/useHistory.js
import { useState, useCallback } from 'react';

const useHistory = (initialState) => {
    const [past, setPast] = useState([]);
    const [present, setPresent] = useState(initialState);
    const [future, setFuture] = useState([]);
    const setState = useCallback((newState, isHistoryEvent = true) => {
        const resolvedState = typeof newState === 'function' ? newState(present) : newState;

        if (isHistoryEvent) {
            if (JSON.stringify(present) === JSON.stringify(resolvedState)) {
                return;
            }
            setPast((prev) => [...prev, present]);
            setFuture([]);
        }
        setPresent(resolvedState);
    }, [present]);

    const undo = useCallback(() => {
        if (past.length === 0) return;
        const previous = past[past.length - 1];
        const newPast = past.slice(0, past.length - 1);
        setFuture((prev) => [present, ...prev]);
        setPresent(previous);
        setPast(newPast);
    }, [past, present]);

    const redo = useCallback(() => {
        if (future.length === 0) return;
        const next = future[0];
        const newFuture = future.slice(1);
        setPast((prev) => [...prev, present]);
        setPresent(next);
        setFuture(newFuture);
    }, [future, present]);

    return [
        present,
        setState,
        undo,
        redo,
        {
            canUndo: past.length > 0,
            canRedo: future.length > 0,
            history: past 
        }
    ];
};

export default useHistory;

