                setTimeout(() => {
                    element.scrollIntoView({ behavior: 'smooth', block: 'start' });
                }, 100);
            }
        } else {
            window.scrollTo(0, 0);
        }
    }, [hash]);
};

export default useScrollToHash;

// frontend/src/shared/hooks/useTemplateManager.js
import { useState, useEffect, useMemo, useCallback, useContext } from 'react';
import { toast } from 'react-toastify';
import apiClient from '../api/api';
import { AuthContext } from '../../app/providers/AuthContext';
export const useTemplateManager = ({ isAdmin = false, initialSourceTab = 'system' } = {}) => {
    const { user } = useContext(AuthContext);
    const [systemTemplates, setSystemTemplates] = useState([]);
    const [personalTemplates, setPersonalTemplates] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const [templateSourceTab, setTemplateSourceTab] = useState(initialSourceTab);
    const [activeSystemTab, setActiveSystemTab] = useState('all');
    const [ownershipFilter, setOwnershipFilter] = useState('all');
    const [selectedCategory, setSelectedCategory] = useState('All');
    const [searchQuery, setSearchQuery] = useState('');
    const [selectedTemplateId, setSelectedTemplateId] = useState(null);
    const [editingTemplate, setEditingTemplate] = useState(null);
    const [isEditModalOpen, setIsEditModalOpen] = useState(false);
    const [confirmModal, setConfirmModal] = useState({ isOpen: false, template: null, actionType: null });
    const [isToggling, setIsToggling] = useState(null);
    const fetchTemplates = useCallback(async () => {
        setIsLoading(true);
        try {
            if (isAdmin) {
                const res = await apiClient.get('/admin/templates?include_drafts=true');
                setSystemTemplates(res.data);
                if (res.data.length > 0 && !selectedTemplateId) {
                    setSelectedTemplateId(res.data[0].id);
                }
            } else {
                const [personalRes, systemRes] = await Promise.all([
                    apiClient.get('/user-templates'),
                    apiClient.get('/sites/templates')
                ]);
                setPersonalTemplates(personalRes.data);
                setSystemTemplates(systemRes.data);
                const allTpls = [...personalRes.data, ...systemRes.data];
                if (allTpls.length > 0 && !selectedTemplateId) {
                    setSelectedTemplateId(personalRes.data.length > 0 ? personalRes.data[0].id : systemRes.data[0].id);
                }
            }
        } catch (error) {
            toast.error("Помилка завантаження шаблонів");
        } finally {
            setIsLoading(false);
        }
    }, [isAdmin, selectedTemplateId]);
    useEffect(() => {
        fetchTemplates();
    }, [fetchTemplates]);

    const filteredTemplates = useMemo(() => {
        let source = templateSourceTab === 'system' ? systemTemplates : personalTemplates;
        if (searchQuery) {
            source = source.filter(t => t.name.toLowerCase().includes(searchQuery.toLowerCase()));
        }
        if (selectedCategory !== 'All') {
            const cat = selectedCategory.toLowerCase();
            source = source.filter(t => 
                (t.category && t.category.toLowerCase() === cat) || 
                t.name.toLowerCase().includes(cat) || 
                (t.description && t.description.toLowerCase().includes(cat))
            );
        }
        if (templateSourceTab === 'system' && isAdmin) {
            source = source.filter(t => {
                let matchesTab = true;
                if (activeSystemTab === 'drafts') matchesTab = !t.is_ready;
                if (activeSystemTab === 'staging') matchesTab = t.is_ready && t.access_level === 'admin_only';
                if (activeSystemTab === 'public') matchesTab = t.is_ready && t.access_level === 'public';
                
                let matchesOwnership = true;
                const isMine = t.user_id === user?.id || t.author_id === user?.id;
                if (ownershipFilter === 'mine') matchesOwnership = isMine;
                if (ownershipFilter === 'others') matchesOwnership = !isMine;
                
                return matchesTab && matchesOwnership;
            });
        }
        
        return source;
    }, [templateSourceTab, systemTemplates, personalTemplates, searchQuery, selectedCategory, activeSystemTab, ownershipFilter, isAdmin, user]);
    const selectedTemplate = useMemo(() => {
        const all = [...systemTemplates, ...personalTemplates];
        return all.find(t => t.id === selectedTemplateId);
    }, [systemTemplates, personalTemplates, selectedTemplateId]);
    const handleAction = async (actionType, template, extraData = {}) => {
        try {
            switch (actionType) {
                case 'delete':
                    if (isAdmin && templateSourceTab === 'system') await apiClient.delete(`/admin/templates/${template.id}`);
                    else await apiClient.delete(`/user-templates/${template.id}`);
                    toast.success("Шаблон видалено");
                    break;
                case 'copy':
                    await apiClient.post(`/admin/templates/${template.id}/copy`);
                    toast.success("Шаблон скопійовано у чернетки!");
                    break;
                case 'markReady':
                    await apiClient.put(`/admin/templates/${template.id}`, { is_ready: 1, access_level: 'admin_only' });
                    toast.success("Шаблон відправлено на перевірку!");
                    break;
                case 'revertDraft':
                    await apiClient.put(`/admin/templates/${template.id}`, { is_ready: 0, access_level: 'private' });
                    toast.success("Шаблон повернуто в чернетки!");
                    break;
                case 'togglePublish':
                    setIsToggling(template.id);
                    const newAccess = template.access_level === 'public' ? 'admin_only' : 'public';
                    await apiClient.put(`/admin/templates/${template.id}`, { access_level: newAccess });
                    toast.success(newAccess === 'public' ? "Шаблон опубліковано!" : "Шаблон приховано");
                    setIsToggling(null);
                    break;
                case 'apply':
                    if (!extraData.siteId) throw new Error("ID сайту не знайдено");
                    const toastId = toast.loading("Застосування шаблону...");
                    await apiClient.put(`/sites/${extraData.siteId}/reset-template`, { templateId: template.id });
                    toast.update(toastId, { render: `Шаблон застосовано!`, type: "success", isLoading: false, autoClose: 2000 });
                    setTimeout(() => window.location.reload(), 2000);
                    return;
            }
            await fetchTemplates();
        } catch (error) {
            setIsToggling(null);
            toast.error(error.response?.data?.message || "Помилка при виконанні дії");
        }
    };

    const handleSaveTemplateChanges = async (name, description, thumbnailUrl, category) => {
        if (!editingTemplate) return;
        try {
            const updateData = { templateName: name, name, description, thumbnail_url: thumbnailUrl, category };
            if (isAdmin && templateSourceTab === 'system') {
                await apiClient.put(`/admin/templates/${editingTemplate.id}`, updateData);
            } else {
                await apiClient.put(`/user-templates/${editingTemplate.id}`, updateData);
            }
            toast.success('Шаблон оновлено');
            setIsEditModalOpen(false);
            setEditingTemplate(null);
            fetchTemplates();
        } catch (error) {
            toast.error('Помилка збереження');
        }
    };
    return {
        templates: filteredTemplates,
        isLoading,
        selectedTemplate,
        selectedTemplateId,
        setSelectedTemplateId,
        filters: {
            templateSourceTab, setTemplateSourceTab,
            activeSystemTab, setActiveSystemTab,
            ownershipFilter, setOwnershipFilter,
            selectedCategory, setSelectedCategory,
            searchQuery, setSearchQuery
        },
        modals: {
            editingTemplate, setEditingTemplate,
            isEditModalOpen, setIsEditModalOpen,
            confirmModal, setConfirmModal
        },
        actions: {
            handleAction,
            handleSaveTemplateChanges,
            isToggling
        },
        fetchTemplates
    };
};

// frontend/src/shared/ui/complex/AccentColorSelector.jsx
import React, { useState, useEffect, useRef } from 'react';
import { PRESET_COLORS, resolveAccentColor, isLightColor } from '../../utils/themeUtils';
import { Edit, Plus } from 'lucide-react';

const AccentColorSelector = ({ value, onChange, enableCustom = false }) => {
    const [hoveredValue, setHoveredValue] = useState(null);
    const [localColor, setLocalColor] = useState(() => resolveAccentColor(value));
    const timeoutRef = useRef(null);
    const visiblePresets = PRESET_COLORS.filter(p => p.id !== 'black' && p.color !== '#000000');
    useEffect(() => {
        setLocalColor(resolveAccentColor(value));
    }, [value]);

    const handleCustomColorChange = (newColor) => {
        setLocalColor(newColor);
        
        if (timeoutRef.current) clearTimeout(timeoutRef.current);
        timeoutRef.current = setTimeout(() => {
            onChange(newColor);
        }, 100);
    };

    const handlePresetClick = (presetId, presetColor) => {
        setLocalColor(presetColor);
        onChange(presetId);
    };

    const isPreset = visiblePresets.some(p => p.id === value);
    const currentPresetName = visiblePresets.find(p => p.id === value)?.name;
    const displayHex = localColor;
    return (
        <div>
            <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-3 mb-5">
                <h3 className="text-base sm:text-lg font-semibold text-(--platform-text-primary) m-0">Акцентний колір</h3>
                <div 
                    className="text-xs sm:text-sm font-semibold flex items-center gap-2 bg-(--platform-bg) px-3 py-1.5 rounded-lg border border-(--platform-border-color)"
                    style={{ color: displayHex }}
                >
                    <div 
                        className="w-3.5 h-3.5 sm:w-4 sm:h-4 rounded bg-current shadow-sm"
                        style={{ backgroundColor: displayHex }}
                    ></div>
                    <span>{isPreset ? currentPresetName : (enableCustom ? 'Власний колір' : 'Обраний колір')}</span>
                    {!isPreset && <span className="text-(--platform-text-secondary) font-normal">({displayHex})</span>}
                </div>
            </div>
            <div className="flex gap-3 sm:gap-4 flex-wrap py-2 justify-center">
                {visiblePresets.map(preset => {
                    const isSelected = value === preset.id;
                    const isHovered = hoveredValue === preset.id;
                    return (
                        <button 
                            key={preset.id}
                            onClick={() => handlePresetClick(preset.id, preset.color)}
                            onMouseEnter={() => setHoveredValue(preset.id)}
                            onMouseLeave={() => setHoveredValue(null)}
                            title={preset.name}
                            className={`
                                w-10 h-10 sm:w-11 sm:h-11 rounded-[10px] cursor-pointer flex items-center justify-center p-0 transition-transform duration-200 ease-in-out
                                ${isSelected || isHovered ? 'scale-110' : 'scale-100'}
                            `}
                            style={{
                                background: preset.color,
                                border: isSelected 
                                    ? `3px solid var(--platform-card-bg)` 
                                    : `1px solid ${isHovered ? preset.color : 'var(--platform-border-color)'}`,
                                boxShadow: isSelected 
                                    ? `0 0 0 2px ${preset.color}` 
                                    : (isHovered ? `0 0 0 1px ${preset.color}` : 'none'),
                            }}
                        />
                    );
                })}

                {enableCustom && (
                    <label 
                        className={`
                            w-10 h-10 sm:w-11 sm:h-11 rounded-[10px] cursor-pointer flex items-center justify-center relative transition-transform duration-200 ease-in-out
                            ${(!isPreset || hoveredValue === 'custom') ? 'scale-110' : 'scale-100'}
                        `}
                        style={{
                            border: !isPreset 
                                ? `3px solid var(--platform-card-bg)` 
                                : (hoveredValue === 'custom' ? `1px solid ${displayHex}` : '2px dashed var(--platform-border-color)'),
                            boxShadow: !isPreset 
                                ? `0 0 0 2px ${displayHex}` 
                                : (hoveredValue === 'custom' ? `0 0 0 1px ${displayHex}` : 'none'),
                            backgroundColor: !isPreset ? displayHex : 'transparent',
                        }}
                        onMouseEnter={() => setHoveredValue('custom')}
                        onMouseLeave={() => setHoveredValue(null)}
                        title="Власний колір"
                    >
                        <input 
                            type="color" 
                            value={displayHex} 
                            onChange={(e) => handleCustomColorChange(e.target.value)}
                            className="absolute opacity-0 w-full h-full cursor-pointer top-0 left-0"
                        />
                        {!isPreset ? (
                            <Edit size={16} className="sm:w-4.5 sm:h-4.5" color={isLightColor(displayHex) ? '#000' : '#fff'} />
                        ) : (
                            <Plus size={18} className="sm:w-5 sm:h-5 text-(--platform-text-secondary)" />
                        )}
                    </label>
                )}
            </div>
            <div className="mt-6 sm:mt-8 flex flex-col sm:flex-row gap-3 sm:gap-4 items-stretch sm:items-center justify-center p-4 sm:p-6 bg-(--platform-bg) rounded-xl border border-(--platform-border-color)">
                <button 
                    className="w-full sm:w-auto py-3 sm:py-2.5 px-5 rounded-lg border-none cursor-default font-medium text-sm shadow-sm transition-opacity hover:opacity-90"
                    style={{
                        background: displayHex,
                        color: isLightColor(displayHex) ? '#000' : '#fff'
                    }}
                >
                    Основна кнопка
                </button>
                <button 
                    className="w-full sm:w-auto py-3 sm:py-2.5 px-5 rounded-lg cursor-default font-medium text-sm bg-transparent transition-colors hover:bg-black/5"
                    style={{
                        border: `1px solid ${displayHex}`,
                        color: displayHex
                    }}
                >
                    Другорядна кнопка
                </button>
                <div 
                    className="w-full sm:w-auto text-center py-2 px-3 rounded-lg text-xs font-semibold"
                    style={{ background: displayHex + '20', color: displayHex }}
                >
                    Активний елемент
                </div>
            </div>
        </div>
    );
};

