// frontend/src/shared/ui/complex/ConfirmModal.jsx
import React, { useEffect, useRef, useState } from 'react';
import { Button } from '../elements/Button';
import { Input } from '../elements/Input';
import { AlertCircle, HelpCircle, CheckCircle } from 'lucide-react';

const ConfirmModal = ({ 
    isOpen, 
    title, 
    message, 
    confirmLabel = 'Підтвердити',
    cancelLabel = 'Скасувати',
    onConfirm, 
    onCancel, 
    type = 'danger',
    requireInput = false,
    expectedInput = 'DELETE',
    requireReason = false,
    reasonPlaceholder = 'Введіть причину...'
}) => {
    const overlayRef = useRef(null);
    const [isVisible, setIsVisible] = useState(false);
    const [inputValue, setInputValue] = useState('');
    const [reasonValue, setReasonValue] = useState('');
    useEffect(() => {
        if (isOpen) {
            setIsVisible(true);
            setInputValue('');
            setReasonValue('');
            document.body.style.overflow = 'hidden';
        } else {
            const timer = setTimeout(() => setIsVisible(false), 200);
            document.body.style.overflow = 'unset';
            return () => clearTimeout(timer);
        }
        return () => { document.body.style.overflow = 'unset'; };
    }, [isOpen]);

    useEffect(() => {
        const handleEsc = (e) => {
            if (e.key === 'Escape' && isOpen) onCancel();
        };
        window.addEventListener('keydown', handleEsc);
        return () => window.removeEventListener('keydown', handleEsc);
    }, [isOpen, onCancel]);

    if (!isVisible && !isOpen) return null;
    const getTypeConfig = () => {
        switch (type) {
            case 'danger':
                return {
                    icon: <AlertCircle className="w-6 h-6 sm:w-7 sm:h-7" />,
                    iconColor: 'var(--platform-danger)',
                    iconBg: 'rgba(229, 62, 62, 0.1)',
                    confirmVariant: 'danger',
                    confirmStyle: {} 
                };
            case 'success':
                return {
                    icon: <CheckCircle className="w-6 h-6 sm:w-7 sm:h-7" />,
                    iconColor: 'var(--platform-success)',
                    iconBg: 'rgba(56, 161, 105, 0.1)',
                    confirmVariant: 'primary',
                    confirmStyle: { backgroundColor: 'var(--platform-success)', borderColor: 'var(--platform-success)', color: '#fff' }
                };
            case 'warning':
                return {
                    icon: <AlertCircle className="w-6 h-6 sm:w-7 sm:h-7" />,
                    iconColor: 'var(--platform-warning)',
                    iconBg: 'rgba(221, 107, 32, 0.1)',
                    confirmVariant: 'warning',
                    confirmStyle: { backgroundColor: 'var(--platform-warning)', borderColor: 'var(--platform-warning)', color: '#fff' }
                };
            default:
                return {
                    icon: <HelpCircle className="w-6 h-6 sm:w-7 sm:h-7" />,
                    iconColor: 'var(--platform-accent)',
                    iconBg: 'rgba(66, 153, 225, 0.1)',
                    confirmVariant: 'primary',
                    confirmStyle: {}
                };
        }
    };

    const config = getTypeConfig();
    const isConfirmDisabled = (requireInput && inputValue !== expectedInput) || (requireReason && reasonValue.trim() === '');
    return (
        <div 
            ref={overlayRef} 
            className={`
                fixed inset-0 flex items-center justify-center bg-black/50 backdrop-blur-[2px] transition-opacity duration-200 p-4
                ${isOpen ? 'opacity-100' : 'opacity-0'}
            `}
            style={{ zIndex: 30000 }} 
            onClick={(e) => e.target === overlayRef.current && onCancel()}
        >
            <div 
                className={`
                    bg-(--platform-card-bg) text-(--platform-text-primary) border border-(--platform-border-color) rounded-2xl w-full max-w-105 shadow-2xl overflow-hidden flex flex-col transition-all duration-200
                    ${isOpen ? 'scale-100 translate-y-0 opacity-100' : 'scale-95 translate-y-4 opacity-0'}
                `}
            >
                <div className="p-5 sm:p-6 flex-1">
                    <div className="flex flex-col sm:flex-row gap-4 items-center sm:items-start text-center sm:text-left">
                        <div 
                            className="w-12 h-12 sm:w-12 sm:h-12 rounded-xl flex items-center justify-center shrink-0"
                            style={{ backgroundColor: config.iconBg, color: config.iconColor }}
                        >
                            {config.icon}
                        </div>
                        <div className="flex flex-col gap-2 w-full">
                            <h3 className="text-lg sm:text-xl font-semibold m-0 leading-tight">
                                {title}
                            </h3>
                            <p className="m-0 text-sm sm:text-[0.95rem] leading-relaxed text-(--platform-text-secondary)">
                                {message}
                            </p>
                            <div className="flex flex-col gap-3 mt-3 w-full">
                                {requireReason && (
                                    <Input 
                                        type="text"
                                        placeholder={reasonPlaceholder}
                                        value={reasonValue}
                                        onChange={(e) => setReasonValue(e.target.value)}
                                        autoFocus={!requireInput}
                                        className="w-full"
                                    />
                                )}
                                {requireInput && (
                                    <Input 
                                        type="text"
                                        placeholder={`Введіть ${expectedInput}`}
                                        value={inputValue}
                                        onChange={(e) => setInputValue(e.target.value)}
                                        autoFocus={requireInput}
                                        className="w-full"
                                    />
                                )}
                            </div>
                        </div>
                    </div>
                </div>
                <div className="px-5 py-4 sm:px-6 sm:py-5 flex flex-col-reverse sm:flex-row justify-end items-stretch sm:items-center gap-3 bg-(--platform-bg) border-t border-(--platform-border-color)">
                    <Button 
                        variant="outline" 
                        onClick={onCancel}
                        className="w-full sm:w-auto min-h-11 sm:min-h-10 sm:min-w-25"
                    >
                        {cancelLabel}
                    </Button>
                    <Button 
                        variant={config.confirmVariant}
                        onClick={() => onConfirm(
                            requireInput ? inputValue : undefined, 
                            requireReason ? reasonValue.trim() : undefined
                        )} 
                        autoFocus={!requireInput && !requireReason}
                        disabled={isConfirmDisabled}
                        className={`w-full sm:w-auto min-h-11 sm:min-h-10 sm:min-w-30 shadow-sm text-white transition-all ${isConfirmDisabled ? 'opacity-50 cursor-not-allowed grayscale-30' : ''}`}
                        style={config.confirmStyle}
                    >
                        {confirmLabel}
                    </Button>
                </div>
            </div>
        </div>
    );
};

export default ConfirmModal;

// frontend/src/shared/ui/complex/DragDropWrapper.jsx
import React, { useState, useRef } from 'react';

const DragDropWrapper = ({
    onDropFiles,
    disabled = false,
    overlayText = "Перетягніть файли сюди",
    errorText = "Неможливо завантажити",
    isError = false,
    children,
    style = {},
    className = ''
}) => {
    const [isDragging, setIsDragging] = useState(false);
    const dragCounter = useRef(0);
    const handleDrag = (e, active) => {
        e.preventDefault();
        e.stopPropagation();
        if (disabled) return;

        if (active !== undefined) {
            if (active) dragCounter.current += 1;
            else dragCounter.current -= 1;
            setIsDragging(dragCounter.current > 0);
        }
    };
    const handleDrop = (e) => {
        e.preventDefault();
        e.stopPropagation();
        if (disabled) return;

        setIsDragging(false);
        dragCounter.current = 0;

        const files = e.dataTransfer.files;
        if (files && files.length > 0) {
            onDropFiles(files);
        }
    };
    return (
        <div
            style={style}
            className={className}
            onDragEnter={(e) => handleDrag(e, true)}
            onDragLeave={(e) => handleDrag(e, false)}
            onDragOver={(e) => { e.preventDefault(); e.stopPropagation(); }}
            onDrop={handleDrop}
        >
            {isDragging && !isError && (
                <div style={{
                    position: 'absolute', inset: 0, zIndex: 200,
                    backgroundColor: 'color-mix(in srgb, var(--platform-accent), transparent 90%)',
                    border: '4px dashed var(--platform-accent)',
                    display: 'flex', alignItems: 'center', justifyContent: 'center',
                    color: 'var(--platform-accent)', fontSize: '1.5rem', fontWeight: 'bold', pointerEvents: 'none',
                    margin: '1rem', borderRadius: '16px'
                }}>
                    {overlayText}
                </div>
            )}
            {isDragging && isError && (
                <div style={{
                    position: 'absolute', inset: 0, zIndex: 200,
                    backgroundColor: 'color-mix(in srgb, var(--platform-danger), transparent 90%)',
                    border: '4px dashed var(--platform-danger)',
                    display: 'flex', alignItems: 'center', justifyContent: 'center',
                    color: 'var(--platform-danger)', fontSize: '1.5rem', fontWeight: 'bold', pointerEvents: 'none',
                    margin: '1rem', borderRadius: '16px'
                }}>
                    {errorText}
                </div>
            )}
            {children}
        </div>
    );
};

export default DragDropWrapper;

