// frontend/src/shared/ui/complex/MediaFilePreview.jsx
import React from 'react';
import { getFileConfig, getFileExtension, getMediaUrl } from '../../../shared/utils/mediaUtils';
import { Play, Video } from 'lucide-react';

const MediaFilePreview = ({ file, className = '', style = {}, showVideoControls = false, onVideoMetadata }) => {
    const config = getFileConfig(file);
    const ext = getFileExtension(file.original_file_name);
    const containerClasses = `w-full h-full flex items-center justify-center overflow-hidden relative rounded-[inherit] ${className}`;
    if (config.type === 'image') {
        return (
            <div 
                className={containerClasses}
                style={style} 
            >
                <img
                    src={getMediaUrl(file, true)} 
                    alt={file.display_name} 
                    className="w-full h-full object-contain"
                />
            </div>
        );
    }

    if (config.type === 'video') {
        if (showVideoControls) {
            return (
                <div 
                    className={`${containerClasses} bg-black`}
                    style={style}
                >
                    <video 
                        src={getMediaUrl(file)} 
                        controls 
                        autoPlay 
                        muted
                        className="w-full h-full object-contain"
                        onLoadedMetadata={onVideoMetadata}
                    />
                </div>
            );
        }

        return (
            <div 
                className={`${containerClasses} bg-[#1a202c]`}
                style={style}
            >
                <div className="absolute inset-0 opacity-10 pointer-events-none" style={{ backgroundImage: 'radial-gradient(circle, #fff 1px, transparent 1px)', backgroundSize: '20px 20px' }}></div>
                <div className="absolute opacity-10 scale-150 pointer-events-none">
                    <Video size={80} color="white" />
                </div>
                <div className="bg-white/15 rounded-full p-3 backdrop-blur-xs border border-white/10 z-2 flex items-center justify-center">
                    <Play size={24} color="white" className="ml-1"/>
                </div>
                <span className="absolute bottom-2.5 text-[0.65rem] font-bold text-white/80 uppercase tracking-wider z-2 bg-black/50 px-2 py-0.5 rounded">
                    {ext}
                </span>
            </div>
        );
    }

    const { IconComponent, themeColor, bgColor, badgeBg } = config;
    return (
        <div 
            className={`${containerClasses} flex-col gap-2`}
            style={{ ...style, background: bgColor }} 
        >
            <div 
                className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 scale-[3] -rotate-10 opacity-[0.07] pointer-events-none"
                style={{ color: themeColor }}
            >
                <IconComponent size={64} />
            </div>

            <div className="bg-(--platform-card-bg) rounded-xl p-2 shadow-sm flex items-center justify-center relative z-2">
                <IconComponent size={24} color={themeColor} />
            </div>
            <span 
                className="text-[0.65rem] font-bold uppercase tracking-wider z-2 px-2 py-0.5 rounded-lg min-w-9 text-center"
                style={{ color: themeColor, background: badgeBg }}
            >
                {ext}
            </span>
        </div>
    );
};

export default MediaFilePreview;

// frontend/src/shared/ui/complex/NovaPoshtaMapModal.jsx
import React, { useState, useEffect } from 'react';
import { MapContainer, TileLayer, Marker, Popup, useMap } from 'react-leaflet';
import 'leaflet/dist/leaflet.css';
import L from 'leaflet';
import apiClient from '../../api/api';
import { Input } from '../elements/Input';
import { Button } from '../elements/Button';
import markerIcon2x from 'leaflet/dist/images/marker-icon-2x.png';
import markerIcon from 'leaflet/dist/images/marker-icon.png';
import markerShadow from 'leaflet/dist/images/marker-shadow.png';
import { X, Search, MapPin, Loader2, CheckCircle2, Navigation } from 'lucide-react';

delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
    iconUrl: markerIcon,
    iconRetinaUrl: markerIcon2x,
    shadowUrl: markerShadow,
});

const MapUpdater = ({ center }) => {
    const map = useMap();
    useEffect(() => {
        if (center) map.flyTo(center, 13);
    }, [center, map]);
    return null;
};

const POPULAR_CITIES = [
    'Київ', 'Львів', 'Одеса', 'Дніпро', 
    'Харків', 'Запоріжжя', 'Житомир', 
    'Вінниця', 'Івано-Франківськ', 'Тернопіль'
];

const NovaPoshtaMapModal = ({ isOpen, onClose, onSelect }) => {
    const [citySearch, setCitySearch] = useState('');
    const [cities, setCities] = useState([]);
    const [selectedCity, setSelectedCity] = useState(null);
    const [isCitiesLoading, setIsCitiesLoading] = useState(false);
    const [warehouses, setWarehouses] = useState([]);
    const [isWarehousesLoading, setIsWarehousesLoading] = useState(false);
    const [mapCenter, setMapCenter] = useState([50.4501, 30.5234]); 
    useEffect(() => {
        if (!isOpen) return;
        const delayDebounceFn = setTimeout(async () => {
            if (citySearch.length < 2 || selectedCity) {
                if (!selectedCity) setCities([]);
                return;
            }
            setIsCitiesLoading(true);
            try {
                const res = await apiClient.get(`/delivery/cities?search=${encodeURIComponent(citySearch)}`);
                setCities(res.data);
            } catch (err) {
                console.error('Failed to load cities', err);
            } finally {
                setIsCitiesLoading(false);
            }
        }, 400);
        return () => clearTimeout(delayDebounceFn);
    }, [citySearch, isOpen, selectedCity]);

    useEffect(() => {
        const fetchWarehouses = async () => {
            if (!selectedCity) return;
            setIsWarehousesLoading(true);
            try {
                const res = await apiClient.get(`/delivery/warehouses?cityRef=${selectedCity.ref}`);
                setWarehouses(res.data);
                if (res.data.length > 0) {
                    setMapCenter([parseFloat(res.data[0].latitude), parseFloat(res.data[0].longitude)]);
                }
            } catch (err) {
                console.error('Failed to load warehouses', err);
            } finally {
                setIsWarehousesLoading(false);
            }
        };
        fetchWarehouses();
    }, [selectedCity]);

    const handlePopularCityClick = async (cityName) => {
        setCitySearch(cityName);
        setIsCitiesLoading(true);
        try {
            const res = await apiClient.get(`/delivery/cities?search=${encodeURIComponent(cityName)}`);
            if (res.data && res.data.length > 0) {
                const exactMatch = res.data.find(c => c.description === cityName) || res.data[0];
                setSelectedCity(exactMatch);
                setCities([]);
            }
        } catch (err) {
            console.error('Failed to load popular city', err);
        } finally {
            setIsCitiesLoading(false);
        }
    };

    if (!isOpen) return null;
    const handleConfirm = (warehouse) => {
        onSelect(`Нова Пошта: м. ${selectedCity.description}, ${warehouse.description}`);
        onClose();
    };

    return (
        <div 
            className="fixed inset-0 flex items-center justify-center p-4 sm:p-6 bg-black/60 backdrop-blur-sm"
            style={{ zIndex: 30000 }}
        >
            <div className="bg-(--platform-bg) w-full max-w-5xl h-[85vh] rounded-2xl shadow-2xl flex flex-col md:flex-row overflow-hidden relative animate-in fade-in zoom-in-95 duration-200">
                <div className="w-full md:w-1/3 h-1/2 md:h-full flex flex-col border-r border-(--platform-border-color) bg-(--platform-card-bg)">
                    <div className="p-4 border-b border-(--platform-border-color) flex items-center justify-between">
                        <h2 className="text-lg font-bold text-(--platform-text-primary) flex items-center gap-2">
                            <MapPin className="text-(--platform-accent)" /> Вибір відділення
                        </h2>
