// frontend/src/shared/ui/complex/UniversalMediaInput.jsx
import React, { useState } from 'react';
import MediaPickerModal from '../../../modules/media/components/MediaPickerModal'; 
import ImageCropperModal from './ImageCropperModal'; 
import apiClient from '../../api/api';
import { toast } from 'react-toastify';
import { getMediaUrl } from '../../utils/mediaUtils';
import { Upload, X, Image as ImageIcon, Video, FileText, Music, Type, Play, FileSpreadsheet } from 'lucide-react';

const UniversalMediaInput = ({ 
    value, 
    onChange, 
    type = 'image',
    placeholder = "Вибрати файл...",
    aspect = null,
    circularCrop = false, 
    triggerStyle = {},
    className = '',
    children
}) => {
    const [isPickerOpen, setIsPickerOpen] = useState(false);
    const [isCropperOpen, setIsCropperOpen] = useState(false);
    const [cropImageSrc, setCropImageSrc] = useState(null);
    const [isHovered, setIsHovered] = useState(false);
    const safeValue = typeof value === 'string' ? value : '';
    const getFullUrl = (path) => {
        if (!path) return '';
        return getMediaUrl({ path_full: path });
    };

    const getFileName = (path) => {
        if (!path) return '';
        return path.split('/').pop();
    };

    const getFileExtension = (path) => {
        if (!path) return '';
        return path.split('.').pop().toLowerCase();
    };

    const triggerChange = (newValue) => {
        if (onChange) {
            onChange(newValue);
        }
    };

    const handleSelectFromPicker = (file) => {
        if (!file) return;
        const fullPath = getMediaUrl(file);
        const relativePath = file.path_full;
        setIsPickerOpen(false);
        if (type === 'image') {
            setCropImageSrc(fullPath);
            setIsCropperOpen(true);
        } else {
            triggerChange(relativePath);
        }
    };

    const handleCropComplete = async (croppedFile) => {
        const formData = new FormData();
        formData.append('mediaFile', croppedFile); 
        try {
            const res = await apiClient.post('/media/upload?isSystem=true', formData);
            let newPath = res.data.path_full || res.data.filePath;

            if (newPath) {
                triggerChange(newPath);
                toast.success('Зображення оновлено');
            } else {
                toast.error('Помилка отримання шляху файлу');
            }
        } catch (error) {
            console.error("Upload cropped error:", error);
            toast.error('Помилка завантаження');
        } finally {
            setIsCropperOpen(false);
            setCropImageSrc(null);
        }
    };

    const handleClear = (e) => {
        e && e.stopPropagation();
        triggerChange('');
    };

    const renderPreview = () => {
        const url = getFullUrl(safeValue);
        const ext = getFileExtension(safeValue);
        const name = getFileName(safeValue);
        if (type === 'image' || ['jpg', 'jpeg', 'png', 'webp', 'gif', 'svg'].includes(ext)) {
            return (
                <div className="w-full h-full p-3 flex items-center justify-center relative z-10">
                    <img 
                        src={url} 
                        alt="Preview" 
                        className="max-w-full max-h-full object-contain block drop-shadow-sm"
                        onError={(e) => { 
                            e.target.onerror = null; 
                            e.target.src = "https://placehold.co/400x300?text=Error"; 
                        }}
                    />
                </div>
            );
        }
        
        if (type === 'video' || ['mp4', 'webm', 'mov'].includes(ext)) {
            return (
                <div className="w-full h-full relative bg-black flex items-center justify-center z-10">
                    <video src={url} className="w-full h-full object-contain" muted />
                    <div className="absolute inset-0 flex items-center justify-center">
                        <div className="bg-black/50 rounded-full p-2 backdrop-blur-sm">
                            <Play size={20} className="text-white fill-white" />
                        </div>
                    </div>
                </div>
            );
        }
        
        let Icon = FileText;
        if (['pdf'].includes(ext)) Icon = FileText;
        if (['xls', 'xlsx', 'csv'].includes(ext)) Icon = FileSpreadsheet;
        if (['ttf', 'otf', 'woff', 'woff2'].includes(ext)) Icon = Type;
        if (['mp3', 'wav'].includes(ext)) Icon = Music;
        return (
            <div className="w-full h-full flex flex-col items-center justify-center p-4 bg-(--platform-bg) text-(--platform-text-primary) z-10 relative">
                <Icon size={32} className="text-(--platform-accent) mb-2" />
                <span className="text-xs text-center font-medium break-all line-clamp-2 px-2">
                    {name}
                </span>
                <span className="text-[10px] text-(--platform-text-secondary) uppercase mt-1 px-1.5 py-0.5 bg-(--platform-border-color) rounded">
                    {ext}
                </span>
            </div>
        );
    };

    if (children) {
        return (
            <>
                <div onClick={() => setIsPickerOpen(true)} style={triggerStyle} className={className}>
                    {children}
                </div>
                <MediaPickerModal 
                    isOpen={isPickerOpen}
                    onClose={() => setIsPickerOpen(false)}
                    onSelect={handleSelectFromPicker}
                    allowedTypes={[type]}
                />
                <ImageCropperModal 
                    isOpen={isCropperOpen}
                    onClose={() => setIsCropperOpen(false)}
                    imageSrc={cropImageSrc}
                    onCropComplete={handleCropComplete}
                    aspect={aspect === null ? undefined : aspect}
                    circularCrop={circularCrop}
                />
            </>
        );
    }

    return (
        <div className={`w-full h-full ${className}`}>
            <div 
                className={`
                    w-full h-full relative rounded-lg overflow-hidden flex justify-center items-center cursor-pointer transition-all duration-200 text-(--platform-text-secondary)
                    bg-[url('https://transparenttextures.com/patterns/cubes.png')] bg-repeat
                    ${safeValue ? 'border border-solid' : 'border-2 border-dashed'}
                    ${isHovered ? 'border-(--platform-accent)' : 'border-(--platform-border-color)'}
                    ${isHovered && !safeValue ? 'bg-(--platform-card-bg)' : 'bg-(--platform-bg)'}
                    ${type === 'file' ? 'min-h-25' : 'min-h-full'}
                `}
                style={triggerStyle}
                onClick={() => setIsPickerOpen(true)}
                onMouseEnter={() => setIsHovered(true)}
                onMouseLeave={() => setIsHovered(false)}
            >
                {safeValue ? (
                    <>
                        {renderPreview()}
                        <div 
                            className={`
                                absolute inset-0 bg-black/40 backdrop-blur-[2px] flex items-center justify-center text-white font-semibold z-20 transition-opacity duration-200
                                ${isHovered ? 'opacity-100' : 'opacity-0'}
                            `}
                        >
                            <span className="px-3 py-1.5 bg-black/50 rounded-lg text-sm border border-white/20">Змінити</span>
                        </div>
                        <button 
                            type="button" 
                            onClick={handleClear}
                            title="Очистити"
                            className={`
                                absolute top-1.5 right-1.5 bg-black/60 text-white border-none rounded-full w-6 h-6 flex items-center justify-center cursor-pointer z-30 transition-all duration-200 p-0 hover:bg-(--platform-danger)
                                ${isHovered ? 'opacity-100' : 'opacity-0'}
                            `}
                        >
                            <X size={14} />
                        </button>
                    </>
                ) : (
                    <div className="flex flex-col items-center gap-2 text-sm font-medium p-4 text-center z-10 relative">
                        {type === 'image' && <ImageIcon size={24} className="opacity-50" />}
                        {type === 'video' && <Video size={24} className="opacity-50" />}
                        {type === 'file' && <FileText size={24} className="opacity-50" />}
                        {type === 'font' && <Type size={24} className="opacity-50" />}
                        <span className="opacity-70">{placeholder}</span>
                    </div>
                )}
            </div>
            <MediaPickerModal 
                isOpen={isPickerOpen}
                onClose={() => setIsPickerOpen(false)}
                onSelect={handleSelectFromPicker}
                allowedTypes={
                    type === 'file' 
                    ? ['.pdf', '.doc', '.docx', '.xls', '.xlsx', '.txt', '.ppt', '.pptx', '.csv'] 
                    : [type]
                }
                title={`Вибір ${type === 'image' ? 'зображення' : type === 'video' ? 'відео' : type === 'font' ? 'шрифту' : 'файлу'}`}
            />
            <ImageCropperModal 
                isOpen={isCropperOpen}
                onClose={() => setIsCropperOpen(false)}
                imageSrc={cropImageSrc}
                onCropComplete={handleCropComplete}
                aspect={aspect === null ? undefined : aspect} // Дозволяє вільні пропорції
                circularCrop={circularCrop}
            />
        </div>
    );
};

export default UniversalMediaInput;

// frontend/src/shared/ui/elements/Avatar.jsx
import React, { useState, useEffect } from 'react';
import { BASE_URL } from '../../config';

const stringToColor = (string) => {
    if (!string) return '#cbd5e1'; 
    let hash = 0;
    for (let i = 0; i < string.length; i++) {
        hash = string.charCodeAt(i) + ((hash << 5) - hash);
    }
    const h = Math.abs(hash % 360); 
    return `hsl(${h}, 65%, 45%)`; 
};

const getInitials = (name) => {
    if (!name) return '?';
    return name.charAt(0).toUpperCase();
};

const Avatar = ({ url, name, size = 40, fontSize, className = '', style = {} }) => {
    const [imgError, setImgError] = useState(false);
    useEffect(() => {
        setImgError(false);
    }, [url]);
    const getFullUrl = (src) => {
        if (!src) return null;
        if (src.startsWith('http') || src.startsWith('data:') || src.startsWith('blob:')) return src;
        if (src.startsWith('/logos/')) return src;
        if (src.includes('/src/') || src.includes('/assets/') || src.includes('@fs')) return src;
        const cleanSrc = src.startsWith('/') ? src : `/${src}`;
        return `${BASE_URL}${cleanSrc}`;
    };
    const finalUrl = getFullUrl(url);
    const sizeStyle = {
        width: `${size}px`,
        height: `${size}px`,
        fontSize: fontSize || `${Math.round(size * 0.45)}px`,
        ...style
    };
    if (finalUrl && !imgError) {
        return (
            <div className={`avatar-container ${className}`} style={sizeStyle}>
                <img 
                    src={finalUrl} 
                    alt={name || 'User'} 
                    className="w-full h-full object-cover"
                    onError={() => setImgError(true)}
                    referrerPolicy="no-referrer"
                />
            </div>
        );
    }
    const bgColor = stringToColor(name || 'User');
    return (
        <div 
            className={`avatar-container ${className}`}
            style={{ 
                ...sizeStyle, 
                backgroundColor: bgColor,
                color: '#ffffff',
            }}
            title={name}
        >
            {getInitials(name)}
        </div>
    );
};

export default Avatar;

// frontend/src/shared/ui/elements/Button.jsx
import React from 'react';

export const Button = ({
  children,
  variant = 'primary',
  disabled = false,
  isLoading = false,
  type = 'button',
  onClick,
  className = '',
  icon,
  style,
  title,
  active,
  ...props
}) => {
  const variantMap = {
      'primary': 'btn-primary',
      'secondary': 'btn-secondary',
      'danger': 'btn-danger',
      'ghost': 'btn-ghost',
      'outline': 'btn-outline',
      'square-accent': 'btn-secondary btn-icon-square',
      'square-danger': 'btn-danger btn-icon-square'
  };

  const variantClass = variantMap[variant] || `btn-${variant}`;
  const activeClass = active ? 'active' : '';
  const isDisabled = disabled || isLoading;
  return (
    <button
      type={type}
      className={`btn ${variantClass} ${activeClass} ${className}`.trim()}
      onClick={onClick}
      disabled={isDisabled}
      title={title}
      style={style}
      {...props}
    >
      {isLoading ? (
          <span className="flex items-center gap-2 justify-center">
              <span className="w-4 h-4 border-2 border-white/30 border-t-white rounded-full animate-spin"></span>
              {children}
          </span>
      ) : (
          <>
            {icon}
            {children}
          </>
      )}
    </button>
  );
};

// frontend/src/shared/ui/elements/CustomSelect.jsx
import React, { useState, useRef, useEffect, useLayoutEffect, useMemo } from 'react';
import { createPortal } from 'react-dom';
import { ChevronDown, Check } from 'lucide-react';

const CustomSelect = ({ 
    name, value, onChange, options = [], placeholder = "Оберіть...", 
    disabled, error, style, multiple = false, maxSelections,
    dropdownClassName = '', dropdownStyle = {}
}) => {
    const [isOpen, setIsOpen] = useState(false);
    const [menuStyle, setMenuStyle] = useState({});
    const triggerRef = useRef(null);
    const menuRef = useRef(null);
    const flatOptions = useMemo(() => options.flatMap(opt => 
        opt.options ? [{ label: opt.label, isGroup: true }, ...opt.options] : opt
    ), [options]);
    useEffect(() => {
        if (!isOpen) return;
        const close = (e) => {
            if (e.type === 'mousedown') {
                if (triggerRef.current && !triggerRef.current.contains(e.target) && menuRef.current && !menuRef.current.contains(e.target)) {
                    setIsOpen(false);
                }
            } else {
                if (menuRef.current && menuRef.current.contains(e.target)) return;
                setIsOpen(false);
            }
        };
        document.addEventListener('mousedown', close);
        window.addEventListener('resize', close);
        window.addEventListener('scroll', close, true);
        return () => { 
            document.removeEventListener('mousedown', close); 
            window.removeEventListener('resize', close); 
            window.removeEventListener('scroll', close, true); 
        };
    }, [isOpen]);

    useLayoutEffect(() => {
        if (isOpen && triggerRef.current) {
            const rect = triggerRef.current.getBoundingClientRect();
            const spaceBelow = window.innerHeight - rect.bottom;
            const spaceAbove = rect.top;
            const idealMaxHeight = 300;
            let maxHeight, topStyle, bottomStyle;
            if (spaceBelow >= idealMaxHeight || spaceBelow > spaceAbove) {
                maxHeight = Math.max(150, spaceBelow - 16);
                topStyle = `${rect.bottom + 4}px`;
                bottomStyle = 'auto';
            } else {
                maxHeight = Math.max(150, spaceAbove - 16);
                topStyle = 'auto';
                bottomStyle = `${window.innerHeight - rect.top + 4}px`;
            }
            
            setMenuStyle({
                position: 'fixed',
                top: topStyle,
                bottom: bottomStyle,
                left: `${rect.left}px`,
                width: `${rect.width}px`,
                maxHeight: `${maxHeight}px`,
                zIndex: 999999,
                overflowY: 'auto',
                backgroundColor: 'var(--platform-card-bg, #ffffff)',
                border: '1px solid var(--platform-border-color, #e5e7eb)',
                borderRadius: '8px',
                boxShadow: '0 10px 25px -5px rgba(0, 0, 0, 0.2)',
                padding: '6px 0',
                display: 'flex',
                flexDirection: 'column'
            });
        }
    }, [isOpen, flatOptions.length]);

    const handleSelect = (val) => {
        if (multiple) {
            let currentValues = Array.isArray(value) ? [...value] : [];
            const strVal = String(val);
            if (currentValues.includes(strVal)) {
                currentValues = currentValues.filter(v => v !== strVal);
            } else {
                if (maxSelections && currentValues.length >= maxSelections) {
                    return;
                }
                currentValues.push(strVal);
            }
            onChange && onChange({ target: { name, value: currentValues } });
        } else {
            onChange && onChange({ target: { name, value: val } });
            setIsOpen(false);
        }
    };

    let displayLabel = placeholder;
    let SingleIcon = null;
    if (multiple) {
        if (Array.isArray(value) && value.length > 0) {
            const selectedOpts = flatOptions.filter(o => !o.isGroup && value.includes(String(o.value)));
            if (selectedOpts.length > 0) {
                displayLabel = selectedOpts.map(o => o.label).join(', ');
            }
        }
    } else {
        const selected = flatOptions.find(o => !o.isGroup && String(o.value) === String(value));
        if (selected) {
            displayLabel = selected.label;
            SingleIcon = selected.icon;
        }
    }

    return (
        <>
            <div 
                ref={triggerRef}
                onClick={() => !disabled && setIsOpen(!isOpen)}
                className={`select-trigger ${error ? 'border-(--platform-danger)' : ''} ${isOpen ? 'open' : ''} ${disabled ? 'opacity-60 cursor-not-allowed' : ''}`}
                style={{
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'space-between',
                    padding: '10px 14px',
                    backgroundColor: 'var(--platform-bg)',
                    border: `1px solid ${error ? 'var(--platform-danger)' : 'var(--platform-border-color)'}`,
                    borderRadius: '8px',
                    cursor: disabled ? 'not-allowed' : 'pointer',
                    userSelect: 'none',
                    ...style
                }}
            >
                <div className="flex items-center gap-2 overflow-hidden flex-1">
                    {!multiple && SingleIcon && <SingleIcon size={18} className="opacity-80 shrink-0" />}
                    <span className={`truncate text-sm font-medium ${displayLabel === placeholder ? 'text-(--platform-text-secondary)' : 'text-(--platform-text-primary)'}`}>
                        {displayLabel}
                    </span>
                </div>
                <ChevronDown size={16} className={`text-(--platform-text-secondary) transition-transform ${isOpen ? 'rotate-180' : ''}`} />
            </div>
            {isOpen && createPortal(
                <div 
                    ref={menuRef} 
                    className={`custom-scrollbar ${dropdownClassName}`} 
                    style={{...menuStyle, ...dropdownStyle}}
                >
                    {flatOptions.length ? flatOptions.map((opt, i) => {
                        if (opt.isGroup) {
                            return <div key={i} className="text-xs font-bold text-(--platform-text-secondary) uppercase px-3 py-1 mt-1">{opt.label}</div>;
                        }
                        const isSelected = multiple 
                            ? (Array.isArray(value) && value.includes(String(opt.value)))
                            : (String(opt.value) === String(value));
                        return (
                            <div 
                                key={opt.value} 
                                onClick={() => handleSelect(opt.value)}
                                style={{ 
                                    padding: `10px ${opt.isGroupChild ? '24px' : '14px'}`,
                                    display: 'flex',
                                    alignItems: 'center',
                                    gap: '10px',
                                    cursor: 'pointer',
                                    color: isSelected && !multiple ? 'var(--platform-accent)' : 'var(--platform-text-primary)',
                                    backgroundColor: isSelected && !multiple ? 'color-mix(in srgb, var(--platform-accent), transparent 90%)' : 'transparent',
                                    fontSize: '14px',
                                    fontWeight: isSelected ? '600' : '500',
                                    transition: 'background 0.2s',
                                    userSelect: 'none'
                                }}
                                onMouseOver={(e) => {
                                    if (!isSelected || multiple) e.currentTarget.style.backgroundColor = 'var(--platform-bg)';
                                }}
                                onMouseOut={(e) => {
                                    if (!isSelected || multiple) e.currentTarget.style.backgroundColor = 'transparent';
                                }}
                            >
                                {multiple && (
                                    <div className={`w-4 h-4 mr-2 rounded border flex items-center justify-center shrink-0 transition-colors ${isSelected ? 'bg-(--platform-accent) border-(--platform-accent) text-white' : 'border-(--platform-border-color)'}`}>
                                        {isSelected && <Check size={12} strokeWidth={3} />}
                                    </div>
                                )}
                                {!multiple && opt.icon && <opt.icon size={16} className={isSelected ? 'opacity-100' : 'opacity-60'} />}
                                <span className="flex-1 truncate">{opt.label}</span>
                                {!multiple && isSelected && <Check size={16} />}
                            </div>
                        );
                    }) : <div className="p-3 text-center text-sm opacity-60">Немає варіантів</div>}
                </div>,
                document.body
            )}
        </>
    );
};

export default CustomSelect;

