                        style={{
                            position: 'absolute',
                            left: '50%',
                            transform: 'translateX(-50%)'
                        }}
                    >
                        <div className="transition-transform duration-200 group-hover:scale-110">
                            {isOpen ? <ChevronRight size={20} /> : <ChevronLeft size={20} />}
                        </div>
                    </button>
                </div>
            )}
            <div style={{
                width: isMobile ? '100%' : (effectiveIsOpen ? sidebarWidth : '0px'),
                minWidth: isMobile ? '100%' : (effectiveIsOpen ? sidebarWidth : '0px'),
                position: isMobile ? 'absolute' : 'relative',
                right: 0, top: 0, bottom: 0, zIndex: 50,
                transform: isMobile ? (effectiveIsOpen ? 'translateX(0)' : 'translateX(100%)') : 'none',
                opacity: isMobile ? 1 : (effectiveIsOpen ? 1 : 0),
                transition: isMobile ? 'transform 0.3s cubic-bezier(0.2, 0, 0, 1)' : 'none', 
                display: 'flex', 
                flexDirection: 'column', 
                overflow: 'hidden',
                boxShadow: isMobile && effectiveIsOpen ? '-5px 0 25px rgba(0,0,0,0.1)' : 'none',
                paddingLeft: 0 
            }}>
                {React.isValidElement(content) 
                    ? React.cloneElement(content, { isMobile }) 
                    : content}
            </div>
        </div>
    );
};

// frontend/src/shared/ui/layouts/TitleManager.jsx
import React from 'react';
import { useLocation } from 'react-router-dom';
import { Helmet } from 'react-helmet-async';
import { getTitleForPath } from '../../../app/router/routesConfig';

const TitleManager = ({ siteData }) => {
    const location = useLocation();
    const staticTitle = getTitleForPath(location.pathname);
    let finalTitle = '';
    if (staticTitle) {
        finalTitle = `${staticTitle} | Kendr`;
    } 
    else if (siteData?.title) {
        if (location.pathname.startsWith('/site/')) {
            const pageName = siteData.page?.name || 'Головна';
            finalTitle = `${pageName} | ${siteData.title}`;
        } else if (location.pathname.startsWith('/dashboard/')) {
            finalTitle = `Редактор: ${siteData.title}`;
        } else if (location.pathname.startsWith('/product/')) {
            finalTitle = `Товар | ${siteData.title}`;
        } else {
            finalTitle = siteData.title;
        }
    } 
    else {
        finalTitle = 'Kendr - Платформа';
    }
    return (
        <Helmet>
            <title>{`${finalTitle}`}</title>
        </Helmet>
    );
};

export default TitleManager;

